window.BASAIR_QUESTIONS=window.BASAIR_QUESTIONS.concat([{"id":"s4-235","number":235,"surah":4,"verses":[103],"verseLabel":"النساء: 103","question":"لماذا رُتبت أحوال الذكر: ﴿قيامًا وقعودًا وعلى جنوبكم﴾ بهذا الترتيب؟","answer":"رتبت أحوال الذكر من القيام إلى القعود ثم الاضطجاع على الجنب، وهي مراتب قدرة الإنسان؛ لتشمل الأمر في الحركة والسكون والضعف بلا انقطاع.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص699–700.","url":""}]},{"id":"s4-236","number":236,"surah":4,"verses":[103],"verseLabel":"النساء: 103","question":"ما سرّ التعبير في قوله تعالى: ﴿فإذا اطمأننتم فأقيموا الصلاة﴾، دون أن يقال: فإذا أمنتم فصلّوا؟","answer":"الاطمئنان زوال الاضطراب والخوف واستقرار النفس، وإقامة الصلاة أداؤها تامة الحدود والأركان؛ فالمقابلة بين حال الضرورة وهيئة الأمن، لا بين الصلاة وتركها.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص700–702.","url":""}]},{"id":"s4-237","number":237,"surah":4,"verses":[103],"verseLabel":"النساء: 103","question":"لماذا وصف الصلاة بأنها ﴿كتابًا موقوتًا﴾، ولم يقل: فرضًا مؤقتًا؟","answer":"أي فريضة محددة بأوقات لا تؤدى وفق الهوى؛ فجمع ﴿كتابًا﴾ معنى الإلزام و﴿موقوتًا﴾ معنى الضبط الزمني.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص702–703.","url":""}]},{"id":"s4-238","number":238,"surah":4,"verses":[104],"verseLabel":"النساء: 104","question":"كيف نُهي المؤمنون عن الوهن في قوله: ﴿ولا تهنوا في ابتغاء القوم﴾ مع أن الوهن شعور قد يطرأ على الإنسان؟","answer":"الوهن ضعف داخلي في العزم، فنهى عنه مع بيان أن الألم مشترك بينهم وبين عدوهم، وأن رجاء المؤمنين بالله يميزهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص708–709.","url":""}]},{"id":"s4-239","number":239,"surah":4,"verses":[104],"verseLabel":"النساء: 104","question":"لماذا كرر فعل الألم: ﴿إن تكونوا تألمون فإنهم يألمون كما تألمون﴾؟","answer":"أعاد فعل الألم ليقرر المماثلة الحسية: ما يصيب المؤمنين يصيب عدوهم أيضًا؛ فلا يكون الألم المشترك سببًا لوهن فريق يرجو من الله ما لا يرجونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص709–710.","url":""}]},{"id":"s4-240","number":240,"surah":4,"verses":[104],"verseLabel":"النساء: 104","question":"ما سرّ التعبير في قوله تعالى: ﴿وترجون من الله ما لا يرجون﴾ ولم يذكر الشيء المرجو؟","answer":"أبهم المرجو بـ﴿مَا﴾ ليشمل النصر والأجر والشهادة والرضوان وكل ما عند الله؛ بينما لا يتجاوز رجاء عدوهم غاية الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص710–711.","url":""}]},{"id":"s4-241","number":241,"surah":4,"verses":[104],"verseLabel":"النساء: 104","question":"لماذا خُتمت الآية بـ﴿وكان الله عليمًا حكيمًا﴾ بعد الحديث عن المطاردة والألم والرجاء؟","answer":"﴿عَلِيمًا﴾ يناسب علم الله بآلامهم ونياتهم ورجائهم، و﴿حَكِيمًا﴾ يناسب ما شرعه من المطاردة والجهاد وما رتبه عليه من مصالح وجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص711–712.","url":""}]},{"id":"s4-242","number":242,"surah":4,"verses":[105],"verseLabel":"النساء: 105","question":"ما سرّ تقديم ﴿إليك﴾ في قوله: ﴿إنا أنزلنا إليك الكتاب بالحق﴾؟","answer":"قدم ﴿إِلَيْكَ﴾ للعناية بمن أنزل عليه الكتاب وإبراز مسؤوليته في الحكم، ثم ذكر الكتاب وملابسته بالحق الذي يجب أن يقضي به.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص714–716.","url":""}]},{"id":"s4-243","number":243,"surah":4,"verses":[105],"verseLabel":"النساء: 105","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا تكن للخائنين خصيمًا﴾، دون أن يقال: مدافعًا أو وكيلًا؟","answer":"النهي يحمي عدالة القضاء من أن تتحول البلاغة في الخصومة إلى نصرة للخائن، ويعلّم الأمة مع أن خطاب النبي تثبيت وتنزيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص718–720.","url":""}]},{"id":"s4-244","number":244,"surah":4,"verses":[107],"verseLabel":"النساء: 107","question":"ما سرّ التعبير في قوله تعالى: ﴿الذين يختانون أنفسهم﴾، وكيف يخون الإنسان نفسه؟","answer":"من يخون غيره إنما يخون نفسه، لأن وبال الخيانة وإثمها راجع إليه؛ وفي الجمع إشعار بأن الاعتداء على فرد من الجماعة اعتداء على النفس المؤمنة المشتركة.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص728–730.","url":""}]},{"id":"s4-245","number":245,"surah":4,"verses":[107],"verseLabel":"النساء: 107","question":"لماذا عُدّي الجدال بـ﴿عن﴾ في قوله: ﴿ولا تجادل عن الذين يختانون أنفسهم﴾؟","answer":"تعدية الجدال بـ﴿عَنْ﴾ تصور المجادل دافعًا التهمة والعقوبة بعيدًا عن الخائن؛ فالنهي ليس عن مطلق الحوار، بل عن اتخاذ الحجة ستارًا يحمي الباطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص728–729.","url":""}]},{"id":"s4-246","number":246,"surah":4,"verses":[108],"verseLabel":"النساء: 108","question":"ما سرّ التعبير في قوله تعالى: ﴿يستخفون من الناس﴾، دون أن يقال: من القوم؟","answer":"قابل استخفاءهم من نظر البشر بعدم استخفائهم من الله ليكشف انقلاب ميزان المراقبة؛ فمن استحيا من الخلق أولى أن يستحي من الخالق.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص734–736.","url":""}]},{"id":"s4-247","number":247,"surah":4,"verses":[108],"verseLabel":"النساء: 108","question":"لماذا قابل بين استخفائهم من الناس وعدم استخفائهم من الله؟","answer":"يستترون من الناس لئلا يروهم، ولا يستترون من الله مع أنه معهم بعلمه حين يدبرون؛ فالمقابلة تفضح تقديم رقابة الخلق على رقابة الخالق.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص735–737.","url":""}]},{"id":"s4-248","number":248,"surah":4,"verses":[108],"verseLabel":"النساء: 108","question":"لماذا عبّر عن تدبيرهم ليلًا بقوله: ﴿إذ يبيّتون ما لا يرضى من القول﴾؟","answer":"التبييت هو تدبير الأمر ليلًا في خفاء، واستعمل لما يضمرونه من قول باطل ويبرمونه بعيدًا عن الأنظار؛ فناسب سياق الاستخفاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص737–738.","url":""}]},{"id":"s4-249","number":249,"surah":4,"verses":[108],"verseLabel":"النساء: 108","question":"لماذا خُتمت الآية بـ﴿وكان الله بما يعملون محيطًا﴾؟","answer":"﴿مُحِيطًا﴾ أبلغ من مجرد العلم؛ فهو علم يطوق أعمالهم فلا يخفى منه ظاهر ولا باطن ولا يجدون منه مهربًا، وهو مقابل استخفائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص738–739.","url":""}]},{"id":"s4-250","number":250,"surah":4,"verses":[109],"verseLabel":"النساء: 109","question":"ما سر التعبير بقوله: ﴿ها أنتم هؤلاء﴾، ولم لم يقل: أنتم جادلتم عنهم؟","answer":"جمعت ﴿هَا﴾ التنبيه مع اسم الإشارة ﴿هَؤُلَاءِ﴾ فاستحضرت المخاطبين كأنهم معروضون للمحاسبة: أنتم الذين جادلتم عن الخائنين في الدنيا، فمن يفعل ذلك في الآخرة؟","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص742–743.","url":""}]},{"id":"s4-251","number":251,"surah":4,"verses":[109],"verseLabel":"النساء: 109","question":"ما سرّ التعبير في قوله تعالى: ﴿جادلتم عنهم﴾، دون أن يقال: خاصمتم عنهم؟","answer":"الجدال مراجعة الحجة ومحاولة فتل الخصم عنها، فناسب من سخر قدرته على المحاجة للدفاع عن الخائن؛ أما الخصومة فأعم من هذه الصورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص743–744.","url":""}]},{"id":"s4-252","number":252,"surah":4,"verses":[109],"verseLabel":"النساء: 109","question":"ما سرّ التعبير في قوله تعالى: ﴿فمن يجادل الله عنهم يوم القيامة﴾، مع أن المجادلة إنما تكون بين يدي الله؟","answer":"المعنى: من يقف مدافعًا عنهم في مواجهة حكم الله وحسابه؟ فعديت المجادلة إلى اسم الله لأن حجتهم الباطلة تصادم قضاءه، لا لأن أحدًا يساويه في مجلس خصومة.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص744–746.","url":""}]},{"id":"s4-253","number":253,"surah":4,"verses":[109],"verseLabel":"النساء: 109","question":"ما سرّ التعبير في قوله تعالى: ﴿يوم القيامة﴾، دون أن يقال: في الآخرة، في مقابلة ﴿الحياة الدنيا﴾؟","answer":"خص ﴿يَوْمَ الْقِيَامَةِ﴾ لأنه يوم قيام الناس للحساب وانكشاف الخيانة، وهو الموطن الذي يستحيل فيه وجود مجادل أو وكيل؛ أما الآخرة فأعم من موقف المحاكمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص744–746.","url":""}]},{"id":"s4-254","number":254,"surah":4,"verses":[109],"verseLabel":"النساء: 109","question":"ما سرّ التعبير في قوله تعالى في مقام التوبيخ: ﴿هَا أَنْتُمْ هَؤُلَاءِ جَادَلْتُمْ﴾، بينما يأتي في مقام التوجيه والمدح: ﴿هَا أَنْتُمْ أُولَاءِ﴾؟","answer":"﴿هؤلاء﴾ أكمل في التنبيه وأشد حضورًا، فناسب مقام التوبيخ على الجدال عن الخائنين؛ أما ﴿أولاء﴾ الأخف فترد حيث لا يحتاج المقام إلى هذا التشديد في التنبيه.","sources":[{"label":"*مختصر لمسات بيانية*؛ منقول في Quranpedia، ملاحظة 44101.","url":""}]},{"id":"s4-255","number":255,"surah":4,"verses":[110],"verseLabel":"النساء: 110","question":"ما سرّ التعبير في قوله تعالى: ﴿ومن يعمل سوءًا أو يظلم نفسه﴾؛ أليس عمل السوء ظلمًا للنفس؟","answer":"عمل السوء يتناول فعلًا قبيحًا قد يتعدى ضرره إلى غير صاحبه، وظلم النفس يبرز ما يجنيه المرء على نفسه بكل معصية؛ فـ﴿أَوْ﴾ تنوع صور الذنب مع فتح باب الاستغفار للجميع.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص750–752.","url":""}]},{"id":"s4-256","number":256,"surah":4,"verses":[110],"verseLabel":"النساء: 110","question":"ما سرّ تقديم عمل السوء على ظلم النفس؟","answer":"قدم عمل السوء لأنه الفعل الظاهر الذي وقع في قصة الخيانة، ثم عمم أثره بقوله ﴿أَوْ يَظْلِمْ نَفْسَهُ﴾؛ فانتقل من الجريمة المشاهدة إلى كل ذنب يرجع وباله إلى فاعله.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص751–752.","url":""}]},{"id":"s4-257","number":257,"surah":4,"verses":[110],"verseLabel":"النساء: 110","question":"ما سرّ التعبير في قوله تعالى: ﴿يجد الله غفورًا رحيمًا﴾، دون أن يقال: يجد مغفرة الله ورحمته؟","answer":"لم يقل يجد المغفرة فقط، بل ﴿يَجِدِ اللَّهَ غَفُورًا رَحِيمًا﴾؛ ليربط التائب بربه وصفاته الدائمة، ويصور أثر الاستغفار كأنه لقاء بقبول الله ورحمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص753–755.","url":""}]},{"id":"s4-258","number":258,"surah":4,"verses":[111],"verseLabel":"النساء: 111","question":"لماذا جاء القصر بـ﴿فإنما يكسبه على نفسه﴾؟","answer":"﴿إِنَّمَا﴾ تحصر وبال الإثم في كاسبه؛ فلا يحمله البريء الذي رماه به، ولا يضر الرسولَ دفاعُ المخادعين، وفي ذلك تقرير للمسؤولية الفردية.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص758–760.","url":""}]},{"id":"s4-259","number":259,"surah":4,"verses":[112],"verseLabel":"النساء: 112","question":"لماذا جمع بين ﴿خطيئة﴾ و﴿إثمًا﴾، وعطف بينهما بـ﴿أو﴾؟","answer":"الخطيئة ما أخطأ به المرء وجه الصواب، والإثم ما يبطئه عن الخير ويستحق به المؤاخذة؛ و﴿أَوْ﴾ تستوعب أيًّا من الوصفين قبل أن يضيف إليه جريمة رمي البريء.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص764–765.","url":""}]},{"id":"s4-260","number":260,"surah":4,"verses":[112],"verseLabel":"النساء: 112","question":"لماذا عاد الضمير مفردًا في ﴿ثم يرمِ به بريئًا﴾ بعد ذكر خطيئة وإثم؟","answer":"الضمير في ﴿بِهِ﴾ يعود إلى ما كسبه المفهوم من الفعلين، أو إلى كل واحد منهما على البدل؛ فوُحّد لأنه يلحظ الذنب المكتسب شيئًا واحدًا يُرمى به البريء.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص765–766.","url":""}]},{"id":"s4-261","number":261,"surah":4,"verses":[112],"verseLabel":"النساء: 112","question":"لماذا صُوّر إلصاق الذنب بالبريء بالرمي: ﴿يرم به بريئًا﴾؟","answer":"صوّر إلصاق الذنب بالبريء رميًا؛ لأن المتهم يقذف الحمل بعيدًا عن نفسه ويلقيه على غيره، فتجتمع في الصورة سرعة الاتهام وعنف إصابته.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص765–767.","url":""}]},{"id":"s4-262","number":262,"surah":4,"verses":[112],"verseLabel":"النساء: 112","question":"ما سرّ تقديم ﴿بهتانًا﴾ على ﴿إثمًا مبينًا﴾؟","answer":"قدم ﴿بُهْتَانًا﴾ لأنه الوصف الخاص الجديد الناشئ من رمي البريء، ثم أتبعه ﴿إِثْمًا مُبِينًا﴾ وهو الحكم العام الظاهر على هذا الفعل.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص766–768.","url":""}]},{"id":"s4-263","number":263,"surah":4,"verses":[113],"verseLabel":"النساء: 113","question":"ما سرّ تقديم فضل الله على رحمته في ﴿ولولا فضل الله عليك ورحمته﴾؟","answer":"الفضل إحسان زائد شمل عصمة النبي ﷺ وإنزال الكتاب، ثم الرحمة أثر ذلك الإحسان في حمايته من تضليلهم؛ فقدم الأصل الأوسع ثم ثمرته الخاصة.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص771–772.","url":""}]},{"id":"s4-264","number":264,"surah":4,"verses":[113],"verseLabel":"النساء: 113","question":"ما سرّ التعبير بقوله تعالى: ﴿همت طائفة منهم أن يضلوك﴾ ثم قُصر ضررهم على أنفسهم: ﴿وما يضلون إلا أنفسهم﴾؟","answer":"همّهم متجه إلى تضليل الرسول، لكن الله عصمه؛ فلم يقع ضرر سعيهم إلا عليهم بما اكتسبوا من إثم وافتضاح، فالقصر يقلب مكرهم إلى أصحابه.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص773–775.","url":""}]},{"id":"s4-265","number":265,"surah":4,"verses":[113],"verseLabel":"النساء: 113","question":"لماذا رُتب الامتنان: ﴿أنزل الله عليك الكتاب والحكمة وعلمك ما لم تكن تعلم﴾ بهذا النسق؟","answer":"بدأ بالكتاب، وهو الوحي المنزل، ثم الحكمة التي تضع معانيه وأحكامه مواضعها، ثم عمم بقوله ﴿وَعَلَّمَكَ مَا لَمْ تَكُنْ تَعْلَمُ﴾ ليشمل سائر ما أفاض الله عليه من علم.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص776–778.","url":""}]},{"id":"s4-266","number":266,"surah":4,"verses":[113],"verseLabel":"النساء: 113","question":"لماذا خُتم السياق بقوله: ﴿وكان فضل الله عليك عظيمًا﴾ بعد نفي إضرارهم بالنبي ﷺ؟","answer":"بعد بيان عصمته من تضليلهم وإنزال الكتاب والحكمة، جمعت الخاتمة هذه النعم في أصلها: ﴿فَضْلُ اللَّهِ عَلَيْكَ عَظِيمًا﴾؛ فما عجز الخصوم عن إضراره أثر من آثار ذلك الفضل.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص777–779.","url":""}]},{"id":"s4-267","number":267,"surah":4,"verses":[114],"verseLabel":"النساء: 114","question":"ما سرّ التعبير في قوله تعالى: ﴿لا خير في كثير من نجواهم﴾، دون أن يقال: في نجواهم شر؟","answer":"نفي الخير أبلغ في تقبيح نجواهم من إثبات الشر في بعضها؛ لأنه يسلب عنها كل نفع معتبر، مع إبقاء الاستثناء لما كان صدقة أو معروفًا أو إصلاحًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص783–784.","url":""}]},{"id":"s4-268","number":268,"surah":4,"verses":[114],"verseLabel":"النساء: 114","question":"ما سرّ التعبير في قوله تعالى: ﴿في كثير من نجواهم﴾ ولم ينف الخير عن النجوى كلها؟","answer":"قال ﴿فِي كَثِيرٍ﴾ ولم يعمم؛ لأن بعض النجوى خير، ثم بين أنواعه في الاستثناء. فالتقييد إنصاف دقيق لا يذم السرية لذاتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص783–785.","url":""}]},{"id":"s4-269","number":269,"surah":4,"verses":[114],"verseLabel":"النساء: 114","question":"لماذا خُصت النجوى بالذكر دون سائر كلامهم؟","answer":"خصت النجوى لأن الكلام الخفي مظنة التآمر والغيبة وإخفاء ما يستحيا منه، فكانت أحوج إلى الرقابة؛ ثم استثنى ما تدعو المصلحة إلى إسراره من الخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص784–786.","url":""}]},{"id":"s4-270","number":270,"surah":4,"verses":[114],"verseLabel":"النساء: 114","question":"لماذا رُتبت المستثنيات: ﴿بصدقة أو معروف أو إصلاح بين الناس﴾ بهذا الترتيب؟","answer":"بدأ بالصدقة وهي نفع مالي خاص، ثم المعروف وهو أوسع أبواب الخير، ثم الإصلاح بين الناس لما فيه من إزالة شر متعد وجمع القلوب؛ فتدرج من الإحسان الفردي إلى المصلحة الاجتماعية.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص786–790.","url":""}]},{"id":"s4-271","number":271,"surah":4,"verses":[114],"verseLabel":"النساء: 114","question":"ما دلالة الانتقال من قوله تعالى: ﴿إِلَّا مَنْ أَمَرَ﴾ إلى قوله: ﴿وَمَنْ يَفْعَلْ ذَلِكَ﴾؟","answer":"﴿أَمَرَ﴾ يدخل فيه الدال على الخير والداعي إليه وإن لم يباشره، ثم جاء ﴿يَفْعَلْ﴾ عند الوعد ليشمل تنفيذ هذه الخيرات وتحقيقها؛ فانتقل من التوجيه إلى الأثر العملي.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص792–795.","url":""}]},{"id":"s4-272","number":272,"surah":4,"verses":[114],"verseLabel":"النساء: 114","question":"ما سرّ التعبير في قوله تعالى: ﴿ابتغاء مرضات الله﴾، ثم عبّر عن الجزاء بـ﴿فسوف نؤتيه﴾؟","answer":"قيد العمل بـ﴿ابْتِغَاءَ مَرْضَاتِ اللَّهِ﴾ لأن صور الخير لا تستحق الوعد إلا بالإخلاص، ثم جاءت ﴿فَسَوْفَ نُؤْتِيهِ﴾ وعدًا مستقبلًا مؤكدًا بعطاء عظيم من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج7، ص795–799.","url":""}]},{"id":"s4-273","number":273,"surah":4,"verses":[115],"verseLabel":"النساء: 115","question":"ما سرّ التعبير في قوله تعالى: ﴿ومن يشاقق الرسول﴾ بصيغة المضارع؟","answer":"المضارع في ﴿ومن يشاقق الرسول﴾ يستحضر الفعل متجددًا أو متكررًا، فيجعل صورته حاضرة ويبين استمرار حكمه أو أثره.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص14–15.","url":""}]},{"id":"s4-274","number":274,"surah":4,"verses":[115],"verseLabel":"النساء: 115","question":"ما سرّ التعبير في قوله تعالى: ﴿من بعد ما تبين له الهدى﴾، دون أن يقال: من بعد ما عرف الحق؟","answer":"﴿تَبَيَّنَ لَهُ الْهُدَى﴾ يدل على أن طريق الحق ظهر واتضح بالحجة، ثم خالفه؛ فهو أبلغ في قيام الحجة من مجرد معرفة خبر قد لا يستبين وجهه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص15–17.","url":""}]},{"id":"s4-275","number":275,"surah":4,"verses":[115],"verseLabel":"النساء: 115","question":"لماذا جُمع بين مشاقّة الرسول واتباع غير سبيل المؤمنين؟","answer":"مشاقة الرسول خروج على مرجع الوحي، واتباع غير سبيل المؤمنين خروج على جماعة الحق وطريقها؛ فجمع بين نقض السلطة الرسالية ومفارقة الأمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص17–19.","url":""}]},{"id":"s4-276","number":276,"surah":4,"verses":[115],"verseLabel":"النساء: 115","question":"ما سرّ التعبير في قوله تعالى: ﴿غير سبيل المؤمنين﴾، دون أن يقال: غير سبيل الرسول؟","answer":"ذكر سبيل المؤمنين لأن اتباع الرسول يظهر عمليًا في الطريق الذي سلكته جماعة المؤمنين وفهمها للدين؛ وفيه تعظيم لحرمة مفارقة إجماعهم بعد ظهور الهدى.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص17–20.","url":""}]},{"id":"s4-277","number":277,"surah":4,"verses":[115],"verseLabel":"النساء: 115","question":"ما الصورة في قوله: ﴿نوله ما تولى﴾؟","answer":"﴿نُوَلِّهِ مَا تَوَلَّى﴾ أي نتركه للجهة التي اختارها ونجعله وليها؛ فالعقوبة من جنس اختياره: أعرض عن الهدى فخُلي بينه وبين طريق الضلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص21–22.","url":""}]},{"id":"s4-278","number":278,"surah":4,"verses":[115],"verseLabel":"النساء: 115","question":"لماذا خُتمت الآية بـ﴿وساءت مصيرًا﴾؟","answer":"﴿مَصِيرًا﴾ تركز على النهاية التي انتهى إليها بعد توليه طريقًا غير سبيل المؤمنين؛ فبئست جهنم غايةً يتحول إليها ومستقرًا أخيرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص22–23.","url":""}]},{"id":"s4-279","number":279,"surah":4,"verses":[116],"verseLabel":"النساء: 116","question":"لماذا تكررت آية ﴿إن الله لا يغفر أن يشرك به﴾ بعد ورودها في الآية 48؟","answer":"تكررت القاعدة لأن موضع الآية 48 يعقب تزكية أهل الكتاب لأنفسهم وافتراءهم، فختم الشرك بأنه ﴿إِثْمًا عَظِيمًا﴾؛ وهنا جاءت بعد مشاقة الرسول واتباع غير سبيل المؤمنين، فناسب وصفه بأنه ﴿ضَلَالًا بَعِيدًا﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص28–30.","url":""}]},{"id":"s4-280","number":280,"surah":4,"verses":[116],"verseLabel":"النساء: 116","question":"ما سرّ التعبير في قوله تعالى: ﴿ويغفر ما دون ذلك﴾، دون أن يقال: ما سوى ذلك؟","answer":"﴿دُونَ﴾ تصور ما عدا الشرك في مرتبة أدنى منه، فتدل على تفاوت الذنوب وعلو خطر الشرك؛ أما ﴿سوى﴾ فكانت ستفيد مجرد المغايرة بلا هذا الترتيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص30–32.","url":""}]},{"id":"s4-281","number":281,"surah":4,"verses":[116],"verseLabel":"النساء: 116","question":"لماذا عبّر عن الشرك بقوله: ﴿أن يشرك به﴾ بالبناء للمجهول؟","answer":"البناء للمجهول يصرف النظر عن شخص المشرك إلى فظاعة وقوع الشرك بالله أيًّا كان فاعله، ويجعل المحور حق الله الذي اتخذ له شريك.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص27–29.","url":""}]},{"id":"s4-282","number":282,"surah":4,"verses":[116],"verseLabel":"النساء: 116","question":"ما سرّ التعبير هنا في قوله تعالى: ﴿فقد ضل ضلالًا بعيدًا﴾، وفي الآية 48: ﴿افترى إثمًا عظيمًا﴾؟","answer":"في الآية 48 جاء السياق في الافتراء والتزكية الباطلة، فناسب ﴿افْتَرَى إِثْمًا عَظِيمًا﴾؛ وفي الآية 116 جاء بعد مفارقة طريق الهدى، فناسب ﴿ضَلَّ ضَلَالًا بَعِيدًا﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص29–33.","url":""}]},{"id":"s4-283","number":283,"surah":4,"verses":[117],"verseLabel":"النساء: 117","question":"لماذا عبّر عن العبادة بالدعاء في ﴿إن يدعون من دونه﴾؟","answer":"الدعاء من أظهر أعمال العبادة لأنه يتضمن التوجه والخضوع وطلب النفع ودفع الضر؛ فعبّر به عن عبادتهم ليكشف أنهم يناجون من لا يملك إجابة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص36–37.","url":""}]},{"id":"s4-284","number":284,"surah":4,"verses":[117],"verseLabel":"النساء: 117","question":"لماذا سمّى المعبودات الباطلة ﴿إناثًا﴾؟","answer":"سميت أصنامهم ﴿إِنَاثًا﴾ لأن كثيرًا من أسمائها مؤنث، وقيل لأنها جمادات ضعيفة لا فعل لها؛ وفيه توبيخ لمن نسب إلى الله البنات ثم عبد ما سماه بأسمائهن.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص36–39.","url":""}]},{"id":"s4-285","number":285,"surah":4,"verses":[117],"verseLabel":"النساء: 117","question":"لماذا كرر ﴿إن يدعون﴾ في الآية نفسها؟","answer":"الأولى تنفي أن تكون معبوداتهم الظاهرة إلا أصنامًا سموها إناثًا، والثانية تكشف الحقيقة وراءها: ما يطيعون في عبادتها إلا شيطانًا مريدًا؛ فتكرر الفعل لاختلاف المفعول وطبقة المعنى.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص38–40.","url":""}]},{"id":"s4-286","number":286,"surah":4,"verses":[117],"verseLabel":"النساء: 117","question":"لماذا أُخر ذكر الشيطان بعد ذكر الإناث: ﴿وإن يدعون إلا شيطانًا مريدًا﴾؟","answer":"أخر الشيطان لينتقل من ظاهر العبادة إلى محركها الخفي؛ فبعد تحقير الأصنام الجامدة كشف أن الطاعة الحقيقية للشيطان المتمرد الذي دعا إليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص39–42.","url":""}]},{"id":"s4-287","number":287,"surah":4,"verses":[118],"verseLabel":"النساء: 118","question":"ما دلالة قول إبليس: ﴿لَأَتَّخِذَنَّ مِنْ عِبَادِكَ نَصِيبًا مَفْرُوضًا﴾؟","answer":"صوّر إبليس أتباعه ﴿نَصِيبًا﴾ يقتطعه لنفسه من عباد الله، ووصفه بـ﴿مَفْرُوضًا﴾ أي مقدرًا معينًا في زعمه؛ وفيه جرأته وعزمه على استلاب طائفة محددة بالإغواء.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص46–48.","url":""}]},{"id":"s4-288","number":288,"surah":4,"verses":[118],"verseLabel":"النساء: 118","question":"لماذا اختار فعل ﴿لأتخذن﴾ بدل لأضلّن عددًا من عبادك؟","answer":"﴿لَأَتَّخِذَنَّ﴾ تزيد على مجرد الإضلال معنى الاصطفاء والاستحواذ: يجعل من أتباعه حصةً خاصة به تتولاه وتطيعه، وهو ما يفسره بعد ذلك بالأوامر المتتابعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص46–48.","url":""}]},{"id":"s4-289","number":289,"surah":4,"verses":[119],"verseLabel":"النساء: 119","question":"لماذا كرر إبليس ﴿ولآمرنهم﴾ في تعداد خطوات الإضلال؟","answer":"كرر ﴿وَلَآمُرَنَّهُمْ﴾ لأن كل أمر مشروع مستقل من مشروع الإغواء: تبتيك الآذان ثم تغيير الخلق؛ والتكرار يصور إحكام سلطانه المزعوم وتتابع توجيهاته.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص53–57.","url":""}]},{"id":"s4-290","number":290,"surah":4,"verses":[119],"verseLabel":"النساء: 119","question":"لماذا خُصّ تبتيك آذان الأنعام بالذكر قبل تغيير خلق الله؟","answer":"تبتيك آذان الأنعام مثال محسوس من شعائر الجاهلية التي حرموا بها ما أحل الله، ثم عطف عليه الأصل الأوسع ﴿فَلَيُغَيِّرُنَّ خَلْقَ اللَّهِ﴾؛ فانتقل من التطبيق إلى المنهج.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص53–56.","url":""}]},{"id":"s4-291","number":291,"surah":4,"verses":[119],"verseLabel":"النساء: 119","question":"ما سرّ التعبير في قوله تعالى: ﴿فليغيرن خلق الله﴾، دون أن يقال: فطرة الله؟","answer":"﴿خَلْقَ اللَّهِ﴾ أوسع من لفظ الفطرة؛ فيشمل تغيير ما خلقه الله في الأبدان وفي الوظائف والسنن المشروعة على الوجه الذي يريده الشيطان، بحسب ما يبينه الدليل في كل صورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص55–57.","url":""}]},{"id":"s4-292","number":292,"surah":4,"verses":[119],"verseLabel":"النساء: 119","question":"لماذا لم يُذكر مفعول ﴿ولأمنينهم﴾، وفُصّل مفعول الأمر بعده؟","answer":"حذف مفعول ﴿وَلَأُمَنِّيَنَّهُمْ﴾ ليعم كل أماني الباطل من طول الأجل والمغفرة بلا توبة، ثم فصّل مفعول الأمر لأنه يذكر نماذج عملية محددة من الإفساد.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص51–56.","url":""}]},{"id":"s4-293","number":293,"surah":4,"verses":[119],"verseLabel":"النساء: 119","question":"ما سرّ التعبير في قوله تعالى: ﴿ومن يتخذ الشيطان وليًا من دون الله فقد خسر خسرانًا مبينًا﴾، دون أن يقال: ضل ضلالًا مبينًا؟","answer":"الولاية مبادلة عملية: ترك ولاية الله واتخذ الشيطان وليًا، فناسب وصف النتيجة بالخسران؛ لأنه فقد الهدى والثواب واستبدل بهما الضلال والعذاب، وخسارته ظاهرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص58–60.","url":""}]},{"id":"s4-294","number":294,"surah":4,"verses":[120],"verseLabel":"النساء: 120","question":"لماذا جمع بين ﴿يعدهم﴾ و﴿يمنيهم﴾؟","answer":"الوعد يعلقهم بخير مستقبل كاذب، والتمنية تملأ نفوسهم بصور مرغوبة بلا أسباب؛ فجمع بين الكذب الخارجي الذي يلقيه الشيطان والوهم الذي ينميه في النفس.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص61–63.","url":""}]},{"id":"s4-295","number":295,"surah":4,"verses":[120],"verseLabel":"النساء: 120","question":"لماذا قصر وعد الشيطان على الغرور: ﴿وما يعدهم الشيطان إلا غرورًا﴾؟","answer":"القصر ينفي عن وعود الشيطان كل حقيقة نافعة؛ فما يعدهم به ليس إلا خداعًا يزين الباطل ثم ينكشف، فلا يبقى منه شيء يصدق عليه الوعد.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص62–64.","url":""}]},{"id":"s4-296","number":296,"surah":4,"verses":[121],"verseLabel":"النساء: 121","question":"ما سرّ التعبير في قوله تعالى عن جهنم: ﴿مأواهم﴾، دون أن يقال: مستقرهم؟","answer":"المأوى هو المكان الذي يلجأ إليه المرء ويقيم فيه؛ واستعماله لجهنم تهكم مرير، إذ صار ما يفترض فيه الأمن مأوى عذابهم الذي لا يجدون عنه مهربًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص65–67.","url":""}]},{"id":"s4-297","number":297,"surah":4,"verses":[122],"verseLabel":"النساء: 122","question":"لماذا قُرن الإيمان بالعمل الصالح مرة أخرى قبل وعد الجنة؟","answer":"الإيمان أصل باطن يحدد الوجهة، والعمل الصالح برهانه وثمرته؛ فاقترانهما يمنع الاتكال على الدعوى المجردة أو العمل المنفصل عن الإيمان قبل وعد الجنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص70–72.","url":""}]},{"id":"s4-298","number":298,"surah":4,"verses":[122],"verseLabel":"النساء: 122","question":"لماذا جُمعت الجنات في ﴿سندخلهم جنات﴾ ونُكّرت؟","answer":"جمع ﴿جَنَّاتٍ﴾ لتعدد البساتين ومراتب النعيم، ونكرها للتعظيم والتفخيم؛ فهي جنات واسعة لا يحيط الوصف المعروف بكنهها.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص71–74.","url":""}]},{"id":"s4-299","number":299,"surah":4,"verses":[122],"verseLabel":"النساء: 122","question":"ما سرّ التعبير في قوله تعالى في النساء: ﴿وَعْدَ اللَّهِ حَقًّا﴾، بينما تنوع التعبير في مواضع أخرى إلى ﴿وَعْدَهُ مَأْتِيًّا﴾ و﴿وَعْدَ الصِّدْقِ﴾ و﴿لَا يُخْلِفُ اللَّهُ الْمِيعَادَ﴾؟","answer":"﴿حَقًّا﴾ مصدر مؤكد يثبت الوعد في مقابلة الأماني، و﴿مَأْتِيًّا﴾ يلحظ وقوع الموعود، و﴿وَعْدَ الصِّدْقِ﴾ يصف الوعد، ونفي إخلاف الميعاد ينفي احتمال الخلف؛ فلكل صيغة جهة يقتضيها سياقها.","sources":[{"label":"فاضل السامرائي، *قبسات من البيان القرآني*، ص268–271؛ منقول في Quranpedia، ملاحظة 49250.","url":""}]},{"id":"s4-300","number":300,"surah":4,"verses":[123],"verseLabel":"النساء: 123","question":"ما سرّ افتتاح الحكم بقوله تعالى: ﴿ليس بأمانيكم ولا أماني أهل الكتاب﴾؟","answer":"قطع التعبير توهم النجاة بمجرد الانتساب والدعوى؛ فجزاء الله لا تحكمه أماني المسلمين ولا أماني أهل الكتاب، وإنما يرتبط بالإيمان والعمل على ما فصلته الآيات.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص80–84.","url":""}]},{"id":"s4-301","number":301,"surah":4,"verses":[123],"verseLabel":"النساء: 123","question":"ما دلالة تقديم أماني المخاطبين على أماني أهل الكتاب في قوله تعالى: ﴿ليس بأمانيكم ولا أماني أهل الكتاب﴾؟","answer":"بدأ بأماني المخاطبين لأن الخطاب موجه إليهم ولأن المقام مقام تربيتهم وقطع اتكالهم، ثم عطف أماني أهل الكتاب لتعم القاعدة الفريقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص82–85.","url":""}]},{"id":"s4-302","number":302,"surah":4,"verses":[123],"verseLabel":"النساء: 123","question":"ما دلالة الجمع بين الولي والنصير في قوله تعالى: ﴿ولا يجد له من دون الله وليًا ولا نصيرًا﴾؟","answer":"الولي يتولى شأنه ويجلب له النفع، والنصير يدفع عنه الضرر؛ فنفى اللفظان كل جهة يتوهم منها الحماية من جزاء الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص86–89.","url":""}]},{"id":"s4-303","number":303,"surah":4,"verses":[124],"verseLabel":"النساء: 124","question":"ما سرّ التعبير بقوله تعالى: ﴿ومن يعمل من الصالحات﴾، دون: ومن يعمل الصالحات؟","answer":"تفيد ﴿مِنَ الصَّالِحَاتِ﴾ أن الجزاء لا يتوقف على استيعاب جميع الأعمال الصالحة، وهو ما لا يطيقه أحد؛ بل على ما يعمله المكلف منها مع الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص93–96.","url":""}]},{"id":"s4-304","number":304,"surah":4,"verses":[124],"verseLabel":"النساء: 124","question":"ما دلالة التصريح بقوله تعالى: ﴿من ذكر أو أنثى﴾ مع أن اسم الشرط ﴿من﴾ يشملهما؟","answer":"التصريح يرفع كل توهم بأن اختلاف الجنس يغير ميزان الجزاء، ويقرر مساواة الذكر والأنثى في قبول العمل ودخول الجنة متى تحقق الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص94–98.","url":""}]},{"id":"s4-305","number":305,"surah":4,"verses":[124],"verseLabel":"النساء: 124","question":"ما دلالة القيد ﴿وهو مؤمن﴾ بعد العمل الصالح؟","answer":"جاءت الجملة حالًا تقيد العمل؛ فالإيمان أصل قبول العمل وثوابه، وبذلك لا تُغني صورة العمل الصالح إذا انفصلت عن أصل الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص96–99.","url":""}]},{"id":"s4-306","number":306,"surah":4,"verses":[124],"verseLabel":"النساء: 124","question":"ما سرّ ضرب المثل بالنقير في قوله تعالى: ﴿ولا يظلمون نقيرًا﴾؟","answer":"النقير هو النقرة الدقيقة في ظهر نواة التمرة، فضُرب به المثل في القلة؛ لينفي الظلم عن جزائهم حتى في أدق مقدار يتصوره المخاطب.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص99–102.","url":""}]},{"id":"s4-307","number":307,"surah":4,"verses":[195],"verseLabel":"النساء: 124؛ آل عمران: 195","question":"ما سرّ اختلاف التعبير بين قوله تعالى في النساء: ﴿مَنْ يَعْمَلْ مِنَ الصَّالِحَاتِ مِنْ ذَكَرٍ أَوْ أُنْثَى﴾، وقوله تعالى في آل عمران: ﴿لَا أُضِيعُ عَمَلَ عَامِلٍ مِنْكُمْ مِنْ ذَكَرٍ أَوْ أُنْثَى﴾؟","answer":"النساء تقرر قاعدة الجزاء بصيغة الشرط، فبدأت بالعمل ثم عممت فاعله. وآل عمران جواب دعاء، فبدأت بنفي إضاعة عمل أي عامل، تمهيدًا لما بعدها من أعمال المهاجرين والمجاهدين.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص498–514؛ وج8، ص93–102.","url":""}]},{"id":"s4-308","number":308,"surah":4,"verses":[125],"verseLabel":"النساء: 125","question":"ما دلالة الاستفهام في قوله تعالى: ﴿ومن أحسن دينًا ممن أسلم وجهه لله﴾؟","answer":"الاستفهام إنكاري يفيد نفي أن يكون أحد أحسن دينًا ممن جمع إخلاص الوجه لله والإحسان واتباع ملة إبراهيم؛ فيحمل السامع على الإقرار بهذه الحقيقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص104–106.","url":""}]},{"id":"s4-309","number":309,"surah":4,"verses":[125],"verseLabel":"النساء: 125","question":"ما الصورة في قوله تعالى: ﴿أسلم وجهه لله﴾، وما دلالة تخصيص الوجه؟","answer":"إسلام الوجه تمثيل للاستسلام الكامل لله، وخُص الوجه لأنه أشرف الأعضاء ومظهر القصد والتوجه؛ فإذا أسلمه المرء دل ذلك على انقياد ذاته كلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص106–107.","url":""}]},{"id":"s4-310","number":310,"surah":4,"verses":[125],"verseLabel":"النساء: 125","question":"ما دلالة الجمع بين ﴿أسلم وجهه لله﴾ و﴿وهو محسن﴾؟","answer":"إسلام الوجه يقرر إخلاص القصد والانقياد لله، والإحسان يقرر إتقان العمل وموافقته للحق؛ فجمع بين صلاح الباطن وصلاح العمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص106–108.","url":""}]},{"id":"s4-311","number":311,"surah":4,"verses":[125],"verseLabel":"النساء: 125","question":"ما سرّ وصف اتباع ملة إبراهيم بقوله تعالى: ﴿حنيفًا﴾؟","answer":"الحنيف هو المائل عن الأديان الباطلة إلى التوحيد والاستقامة عليه؛ فالوصف يبرز براءة ملة إبراهيم من الشرك، لا مجرد الاستقامة المجردة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص108–109.","url":""}]},{"id":"s4-312","number":312,"surah":4,"verses":[125],"verseLabel":"النساء: 125","question":"ما مناسبة ختم الثناء بقوله تعالى: ﴿واتخذ الله إبراهيم خليلًا﴾؟","answer":"الخلة أخص المحبة التي تتخلل النفس، وفي ذكرها غاية تشريف إبراهيم بعد بيان اتباع ملته، مع بقاء معنى عبوديته لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص109–111.","url":""}]},{"id":"s4-313","number":313,"surah":4,"verses":[126],"verseLabel":"النساء: 126","question":"ما دلالة ﴿ما﴾ في قوله تعالى: ﴿ولله ما في السماوات وما في الأرض﴾؟","answer":"جاءت ﴿ما﴾ شاملة لكل ما في السماوات والأرض من الموجودات والأشياء، فعممت الملك ولم تدع شيئًا خارج سلطان الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص112–114.","url":""}]},{"id":"s4-314","number":314,"surah":4,"verses":[126],"verseLabel":"النساء: 126","question":"ما مناسبة قوله تعالى: ﴿وكان الله بكل شيء محيطًا﴾ بعد تقرير ملكه للسماوات والأرض؟","answer":"بعد إثبات الملك العام أثبتت الإحاطة بكل شيء علمًا وقدرة؛ فملكه ليس اسمًا مجردًا، بل سلطان لا يخرج عنه موجود ولا تخفى عليه حال.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص113–115.","url":""}]},{"id":"s4-315","number":315,"surah":4,"verses":[127],"verseLabel":"النساء: 127","question":"ما سرّ تكرار مادة الفتوى والتصريح باسم الله في قوله تعالى: ﴿ويستفتونك في النساء قل الله يفتيكم فيهن﴾؟","answer":"الاستفتاء طلب بيان حكم مشكل، فجاء التصريح بأن الله هو الذي يفتي ليقرر أن حقوق النساء واليتامى أحكام وحي، لا أعرافًا يملك الأقوياء تغييرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص118–121.","url":""}]},{"id":"s4-316","number":316,"surah":4,"verses":[127],"verseLabel":"النساء: 127","question":"ما موقع قوله تعالى: ﴿وما يتلى عليكم في الكتاب﴾ من جواب الاستفتاء؟","answer":"عُطف ﴿وما يتلى عليكم﴾ على اسم الله؛ أي: الله يفتيكم، ويفتيكم أيضًا ما يتلى عليكم في الكتاب من الآيات السابقة في حقوق يتامى النساء، فجعل المتلو نفسه مبينًا للحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص120–123.","url":""}]},{"id":"s4-317","number":317,"surah":4,"verses":[127],"verseLabel":"النساء: 127","question":"ما سرّ حذف حرف الجر في قوله تعالى: ﴿وترغبون أن تنكحوهن﴾؛ أهو رغبة فيهن أم رغبة عنهن؟","answer":"احتمل الحذف الحالين: يرغب الولي في اليتيمة لجمالها أو مالها فيمنعها حقها، أو يرغب عنها لدمامتها أو فقرها ويمنعها أن تنكح غيره؛ فجمع الحذف وجهي الظلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص124–126.","url":""}]},{"id":"s4-318","number":318,"surah":4,"verses":[127],"verseLabel":"النساء: 127","question":"ما سرّ التعبير بقوله تعالى: ﴿وأن تقوموا لليتامى بالقسط﴾، دون: وأن تقسطوا في اليتامى؟","answer":"القيام لليتامى بالقسط يدل على النهوض الدائم بحفظ حقوقهم ورعاية مصالحهم، فهو أبلغ من فعل عدل عارض في شأن واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص125–127.","url":""}]},{"id":"s4-319","number":319,"surah":4,"verses":[127],"verseLabel":"النساء: 127","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿فإن الله كان به عليمًا﴾؟","answer":"عمّم قوله ﴿مِنْ خَيْرٍ﴾ كل إحسان إلى الضعفاء، ثم أكد أن الله يعلمه؛ ترغيبًا في الخير الخفي والظاهر وضمانًا لعدم ضياع جزائه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص127–129.","url":""}]},{"id":"s4-320","number":320,"surah":4,"verses":[128],"verseLabel":"النساء: 128","question":"ما سرّ التعبير بقوله تعالى: ﴿من بعلها﴾، دون: من زوجها؟","answer":"البعل هو الزوج مع ملاحظة قيامه على شأن المرأة واستعلائه، فناسب مقام الخوف من نشوزه وإعراضه، بخلاف لفظ الزوج الذي يبرز معنى الاقتران.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص132–134.","url":""}]},{"id":"s4-321","number":321,"surah":4,"verses":[128],"verseLabel":"النساء: 128","question":"ما دلالة ترتيب ﴿نشوزًا أو إعراضًا﴾؟","answer":"النشوز ترفع واستعلاء تظهر آثاره في المعاملة، والإعراض انصراف عنها وترك لمؤانستها؛ فجمع التعبير الصورتين اللتين تخشى المرأة وقوعهما من زوجها.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص133–135.","url":""}]},{"id":"s4-322","number":322,"surah":4,"verses":[128],"verseLabel":"النساء: 128","question":"ما سرّ نفي الجناح في قوله تعالى: ﴿فلا جناح عليهما أن يصلحا بينهما صلحًا﴾ مع أن الصلح مطلوب؟","answer":"رفع نفي الجناح ما قد يتوهم من الحرج في تنازل المرأة عن بعض حقها وفي قبول الزوج ذلك إذا تم بالتراضي؛ فالمقام ليس في أصل فضل الصلح، بل في صورة قد تلتبس بالمنع.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص134–137.","url":""}]},{"id":"s4-323","number":323,"surah":4,"verses":[128],"verseLabel":"النساء: 128","question":"ما دلالة مجيء قوله تعالى: ﴿والصلح خير﴾ جملة اعتراضية مطلقة؟","answer":"أكد الاعتراض الترغيب في المصالحة، وجاءت الجملة اسمية لتثبيت خيريتها. وإطلاقها يجعلها كالمثل العام: كل صلح مشروع يزيل الخصومة خير.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص136–138.","url":""}]},{"id":"s4-324","number":324,"surah":4,"verses":[128],"verseLabel":"النساء: 128","question":"ما الصورة في قوله تعالى: ﴿وأحضرت الأنفس الشح﴾؟","answer":"صوّر الشح كأنه شيء أُحضر عند النفس ولزمها، للدلالة على تمكنه منها واستعداده للحضور عند قسمة الحقوق؛ وفي ذلك تنبيه للزوجين إلى مجاهدة هذا الطبع.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص137–139.","url":""}]},{"id":"s4-325","number":325,"surah":4,"verses":[128,129],"verseLabel":"النساء: 128؛ 129","question":"ما سرّ اختلاف الخاتمة بين قوله تعالى: ﴿وَإِنْ تُحْسِنُوا وَتَتَّقُوا... خَبِيرًا﴾، وقوله: ﴿وَإِنْ تُصْلِحُوا وَتَتَّقُوا... غَفُورًا رَحِيمًا﴾؟","answer":"الأولى تحث على إحسان العشرة، وخفايا الإحسان يعلمها الخبير. والثانية تعالج تقصيرًا في العدل يحتاج إلى إصلاح، فناسبها الوعد بالمغفرة والرحمة لمن أصلح واتقى.","sources":[{"label":"ابن جماعة، كشف المعاني في المتشابه من المثاني، ص141؛ إسلام ويب، باب النساء: 128–129.","url":""}]},{"id":"s4-326","number":326,"surah":4,"verses":[129],"verseLabel":"النساء: 129","question":"كيف يُفهم قوله تعالى: ﴿ولن تستطيعوا أن تعدلوا بين النساء﴾ مع الأمر بالعدل؟","answer":"المنفي هو تمام التسوية في ميل القلب والمحبة، وهو خارج عن القدرة؛ أما المأمور به فالعدل في القسم والنفقة والمعاملة مما يملكه الإنسان، ولذلك عقب بالنهي عن الميل كل الميل.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص143–146.","url":""}]},{"id":"s4-327","number":327,"surah":4,"verses":[129],"verseLabel":"النساء: 129","question":"ما دلالة زيادة قوله تعالى: ﴿ولو حرصتم﴾ بعد نفي استطاعة العدل التام؟","answer":"تفيد المبالغة في نفي القدرة على تسوية ميل القلب: فلا يتحقق ذلك حتى مع استفراغ الحرص؛ وبذلك يمهد الكلام لتوجيه المكلف إلى العدل الذي يقدر عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص145–146.","url":""}]},{"id":"s4-328","number":328,"surah":4,"verses":[129],"verseLabel":"النساء: 129","question":"ما سرّ النهي عن ﴿كل الميل﴾ دون النهي عن أصل الميل؟","answer":"لأن أصل الميل القلبي لا يملكه الإنسان، أما الاسترسال فيه حتى يظهر في المعاملة ويضيع حق الأخرى فمقدور عليه؛ فوقع النهي على الميل كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص146–148.","url":""}]},{"id":"s4-329","number":329,"surah":4,"verses":[129],"verseLabel":"النساء: 129","question":"ما الصورة في قوله تعالى: ﴿فتذروها كالمعلقة﴾؟","answer":"شبه المرأة التي لا تنال حقوق الزوجة ولا تُطلق فتستقل بالمعلقة التي لا تستقر في جهة؛ فالتشبيه يجسم ألم إبقائها بين حالين.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص147–150.","url":""}]},{"id":"s4-330","number":330,"surah":4,"verses":[130],"verseLabel":"النساء: 130","question":"ما سرّ التعبير بقوله تعالى: ﴿وإن يتفرقا﴾، دون: وإن يتطلقا؟","answer":"التفرق أوسع من ذكر الطلاق؛ فهو يصور انقطاع الصحبة وذهاب كل واحد في جهة بعد تعذر الصلح، ويشمل ما تحصل به المفارقة بين الزوجين.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص152–153.","url":""}]},{"id":"s4-331","number":331,"surah":4,"verses":[130],"verseLabel":"النساء: 130","question":"ما دلالة قوله تعالى: ﴿يغن الله كلًا من سعته﴾ بعد ذكر افتراق الزوجين؟","answer":"يطمئن الطرفين ألا يمنعهما خوف الحاجة من المفارقة عند تعذر العشرة؛ فالله يغني كل واحد من فضله ورزقه الواسع، وقد يهيئ له ما هو أصلح.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص153–154.","url":""}]},{"id":"s4-332","number":332,"surah":4,"verses":[131],"verseLabel":"النساء: 131","question":"ما سرّ تكرار قوله تعالى: ﴿ولله ما في السماوات وما في الأرض﴾ في هذا السياق؟","answer":"تكرر تقرير الملك لتعلقه في كل مرة بغرض: فمرة يؤسس غنى الله بعد وعد الزوجين بالسعة، ومرة يؤكد الوصية بالتقوى، ومرة يقرر قدرته على إذهاب الناس والإتيان بغيرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص155–161.","url":""}]},{"id":"s4-333","number":333,"surah":4,"verses":[131],"verseLabel":"النساء: 131","question":"ما سرّ التعبير عن الأمر بالتقوى بقوله تعالى: ﴿ولقد وصينا﴾؟","answer":"الوصية أمر مؤكد مقترن بالعناية والحرص على نفع الموصى، وتناسب هنا حكمًا جامعًا متصلًا أوصى الله به الأمم السابقة واللاحقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص158–163.","url":""}]},{"id":"s4-334","number":334,"surah":4,"verses":[131],"verseLabel":"النساء: 131","question":"ما دلالة تقديم الذين أوتوا الكتاب على المخاطبين في الوصية بالتقوى؟","answer":"راعى الترتيب الزمن الذي صرحت به الآية: ﴿مِنْ قَبْلِكُمْ وَإِيَّاكُمْ﴾؛ فذكر من سبقت وصيتهم أولًا، ثم ألحق بهم هذه الأمة، ليظهر اتحاد أصل التقوى في الشرائع.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص160–164.","url":""}]},{"id":"s4-335","number":335,"surah":4,"verses":[131,132],"verseLabel":"النساء: 131؛ 132","question":"ما سرّ اختلاف خاتمة تكرار قوله تعالى: ﴿وَلِلَّهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ﴾ بين ﴿غَنِيًّا حَمِيدًا﴾ و﴿وَكَفَى بِاللَّهِ وَكِيلًا﴾؟","answer":"الأولى جاءت بعد الوعد بأن يغني الله الزوجين من سعته، فناسبها غناه المحمود. والثانية جاءت مع بيان قدرته على الاستبدال، فناسبها أنه الكافي في حفظ الأمر وتدبيره.","sources":[{"label":"ابن جماعة، كشف المعاني في المتشابه من المثاني، ص142؛ إسلام ويب، باب النساء: 131–132.","url":""}]},{"id":"s4-336","number":336,"surah":4,"verses":[133],"verseLabel":"النساء: 133","question":"ما سرّ التعبير بقوله تعالى: ﴿ويأت بآخرين﴾، دون: ويأت بقوم آخرين؟","answer":"حذف الموصوف ليعم كل من يصح أن يخلف المخاطبين، ونُكّر ﴿آخرين﴾ لتهويل قدرة الله على الاستبدال من غير تقيد بقوم معلومين.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص167–170.","url":""}]},{"id":"s4-337","number":337,"surah":4,"verses":[134],"verseLabel":"النساء: 134","question":"ما مناسبة تقديم ثواب الدنيا في قوله تعالى: ﴿فعند الله ثواب الدنيا والآخرة﴾؟","answer":"لما افتتحت الآية بمن يريد ثواب الدنيا قدم المطلوب الذي تعلق به قصده، ثم ضم إليه ثواب الآخرة ليصرفه عن قصر همته على العاجل؛ فكلاهما عند الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص171–173.","url":""}]},{"id":"s4-338","number":338,"surah":4,"verses":[135],"verseLabel":"النساء: 135","question":"ما دلالة صيغة المبالغة في قوله تعالى: ﴿كونوا قوامين بالقسط﴾؟","answer":"﴿قَوَّامِينَ﴾ تدل على شدة القيام بالعدل وتكرره والثبات عليه؛ فالمطلوب أن يكون القسط وصفًا راسخًا لا موقفًا عارضًا، ولو كانت الشهادة على النفس أو الأقربين.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص178–181.","url":""}]},{"id":"s4-339","number":339,"surah":4,"verses":[135],"verseLabel":"النساء: 135","question":"ما سرّ تقديم القيام بالقسط على الشهادة لله في آية النساء؟","answer":"محور السياق إقامة العدل في الشهادة ولو على النفس والوالدين والأقربين، فقدم القسط موضع العناية، ثم جعل أداء الشهادة لله ضمانًا للتجرد من الهوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص180–184.","url":""}]},{"id":"s4-340","number":340,"surah":4,"verses":[135],"verseLabel":"النساء: 135","question":"ما دلالة قوله تعالى: ﴿شهداء لله﴾، دون: شاهدين بالحق؟","answer":"جعل الشهادة لله يحدد باعثها وغايتها: تؤدى امتثالًا له وحده لا لمصلحة قريب أو غني أو فقير، وذلك أبلغ في اقتلاع المحاباة من مجرد وصفها بالحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص182–185.","url":""}]},{"id":"s4-341","number":341,"surah":4,"verses":[135],"verseLabel":"النساء: 135","question":"ما دلالة البدء بالنفس في قوله تعالى: ﴿ولو على أنفسكم أو الوالدين والأقربين﴾؟","answer":"بدأ بالنفس لأنها أقرب ما يحابيه الإنسان وأشد ما يشق عليه أن يشهد ضده، ثم ترقى إلى الوالدين والأقربين؛ ليشمل الأمر أقوى دواعي الهوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص184–187.","url":""}]},{"id":"s4-342","number":342,"surah":4,"verses":[135],"verseLabel":"النساء: 135","question":"ما دلالة الجمع بين الغني والفقير في قوله تعالى: ﴿إن يكن غنيًا أو فقيرًا فالله أولى بهما﴾؟","answer":"جمع طرفي الحال لأن الشاهد قد يحابي الغني رهبة أو طمعًا، وقد يحابي الفقير رحمةً به؛ فردت الآية تقدير مصلحتهما إلى الله ومنعت الهوى في الحالين.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص186–190.","url":""}]},{"id":"s4-343","number":343,"surah":4,"verses":[135],"verseLabel":"النساء: 135","question":"ما مناسبة النهي عن اتباع الهوى قبل ذكر لَيّ الشهادة والإعراض عنها؟","answer":"اتباع الهوى هو الدافع الباطن الذي ينشأ عنه تحريف الشهادة أو تركها؛ فنهت الآية عن الأصل أولًا، ثم حذرت من صورتي أثره: اللَّي والإعراض.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص188–193.","url":""}]},{"id":"s4-344","number":344,"surah":4,"verses":[135],"verseLabel":"النساء: 135","question":"ما سرّ اختلاف الترتيب بين قوله تعالى في النساء: ﴿قَوَّامِينَ بِالْقِسْطِ شُهَدَاءَ لِلَّهِ﴾، وفي المائدة: ﴿قَوَّامِينَ لِلَّهِ شُهَدَاءَ بِالْقِسْطِ﴾؟","answer":"في النساء مقام الشهادة على النفس والأقربين، فقدم القسط مقصدًا ولو خالف الهوى، ثم جعل الشهادة لله. وفي المائدة مقام الوفاء بعهد الله، فقدم القيام لله ثم بين أن الشهادة تكون بالقسط.","sources":[{"label":"ابن جماعة، *كشف المعاني*؛ منقول في Quranpedia، ملاحظة 40886.","url":""}]},{"id":"s4-345","number":345,"surah":4,"verses":[136],"verseLabel":"النساء: 136","question":"ما سرّ توجيه الخطاب إلى المؤمنين بقوله تعالى: ﴿يا أيها الذين آمنوا آمنوا﴾؟","answer":"الأمر الثاني ليس إنشاء أصل الإيمان من جديد، بل الثبات عليه واستكمال مقتضياته وتجديد التصديق بجميع أركانه من غير تفريق.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص196–198.","url":""}]},{"id":"s4-346","number":346,"surah":4,"verses":[136],"verseLabel":"النساء: 136","question":"ما دلالة ترتيب أركان الإيمان في قوله تعالى: ﴿بالله ورسوله والكتاب الذي نزل على رسوله والكتاب الذي أنزل من قبل﴾؟","answer":"بدأ بالله أصل الإيمان، ثم برسوله الذي تلقى الوحي، ثم بالقرآن المنزل عليه وهو موضع الخطاب المباشر، ثم عمم الإيمان بالكتب السابقة؛ فتدرج من الأصل إلى الواسطة ثم الوحي الحاضر وما سبقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص198–201.","url":""}]},{"id":"s4-347","number":347,"surah":4,"verses":[136],"verseLabel":"النساء: 136","question":"ما سرّ التعبير عن القرآن بقوله تعالى: ﴿الْكِتَابِ الَّذِي نَزَّلَ عَلَى رَسُولِهِ﴾، وعن الكتب السابقة بقوله: ﴿وَالْكِتَابِ الَّذِي أَنْزَلَ مِنْ قَبْلُ﴾؟","answer":"التنزيل بالتشديد يلحظ نزول القرآن مفرقًا متتابعًا، والإنزال في الكتب السابقة يلحظ أصل إيتائها؛ فاختلاف الصيغة يطابق جهة العرض في كل موضع.","sources":[{"label":"فاضل السامرائي، *لمسات بيانية*؛ منقول في Quranpedia، ملاحظة 44579.","url":""}]},{"id":"s4-348","number":348,"surah":4,"verses":[136],"verseLabel":"النساء: 136","question":"ما سرّ تأخير ﴿اليوم الآخر﴾ في النساء بعد الملائكة والكتب والرسل؟","answer":"سياق النساء في وجوب الإيمان بالوحي ورسله، فجمع وسائط الوحي أولًا ثم ختم باليوم الآخر الذي يظهر فيه جزاء التكذيب؛ فجاء الترتيب تابعًا لغرض السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج2، ص757، تحت «توجيه متشابه اللفظ».","url":""}]},{"id":"s4-349","number":349,"surah":4,"verses":[137],"verseLabel":"النساء: 137","question":"ما دلالة تكرار ﴿ثم﴾ في قوله تعالى: ﴿آمنوا ثم كفروا ثم آمنوا ثم كفروا﴾؟","answer":"تفيد ﴿ثم﴾ التراخي، وتكرارها يصور انتقالهم المتكرر بين الإيمان والكفر على مراحل، بما يكشف رسوخ التقلب وتعمد العودة بعد ظهور الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص202–204.","url":""}]},{"id":"s4-350","number":350,"surah":4,"verses":[137],"verseLabel":"النساء: 137","question":"ما دلالة قوله تعالى: ﴿ثم ازدادوا كفرًا﴾، دون الاكتفاء باستمرارهم عليه؟","answer":"الازدياد يدل على أن كفرهم لم يبق على درجة واحدة، بل انضم إليه تمادٍ وإنكار جديد بعد تكرر الردة؛ فهو تصاعد في الكفر لا مجرد بقاء عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص203–205.","url":""}]},{"id":"s4-351","number":351,"surah":4,"verses":[138],"verseLabel":"النساء: 138","question":"ما سرّ التعبير بالبشارة في قوله تعالى: ﴿فبشر المنافقين بأن لهم عذابًا أليمًا﴾؟","answer":"استعملت البشارة تهكمًا؛ لأن ما ينتظرونه خبر يسوءهم لا يسرهم، فقلب اللفظ المتوقع يزيد الوعيد إيلامًا وسخرية من أمانيهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص208–210.","url":""}]},{"id":"s4-352","number":352,"surah":4,"verses":[139],"verseLabel":"النساء: 139","question":"ما سرّ اختيار ﴿العزة﴾ في قوله تعالى: ﴿أيبتغون عندهم العزة﴾؟","answer":"العزة منعة ورفعة لا يُنال صاحبها، والمنافقون طلبوها بموالاة الكافرين؛ فردت الآية وهمهم بالقصر: ﴿فإن العزة لله جميعًا﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص211–214.","url":""}]},{"id":"s4-353","number":353,"surah":4,"verses":[140],"verseLabel":"النساء: 140","question":"ما دلالة النهي عن القعود مع الخائضين في آيات الله، دون الاكتفاء بالنهي عن سماعهم؟","answer":"القعود معهم حال خوضهم يدل على الرضا والمشاركة في مجلسهم ولو بالصمت، ولذلك وجب مفارقة المجلس حتى ينتقلوا إلى حديث غيره؛ أما السماع العارض فلا يؤدي هذا المعنى وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص215–220.","url":""}]},{"id":"s4-354","number":354,"surah":4,"verses":[140],"verseLabel":"النساء: 140","question":"ما دلالة قوله تعالى: ﴿إنكم إذًا مثلهم﴾، دون: فإنكم منهم؟","answer":"المماثلة هنا في إثم الرضا بالاستهزاء والمكث في مجلسه، ولا تستلزم التطابق معهم في كل صفة؛ ولذلك كان لفظ ﴿مثلهم﴾ أدق من إدخال القاعد في جماعتهم بإطلاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص219–223.","url":""}]},{"id":"s4-355","number":355,"surah":4,"verses":[140],"verseLabel":"النساء: 140","question":"ما مناسبة جمع المنافقين والكافرين في جهنم جميعًا بعد النهي عن مجالس الاستهزاء؟","answer":"جمعهم اشتراكهم في الكفر أو الرضا به ونصرة أهله؛ فمن نافق وجالس المستهزئين راضيًا التحق بهم في سبب الوعيد، فناسب أن يجمعهم الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص222–225.","url":""}]},{"id":"s4-356","number":356,"surah":4,"verses":[141],"verseLabel":"النساء: 141","question":"ما سرّ وصف المنافقين بقوله تعالى: ﴿الذين يتربصون بكم﴾؟","answer":"التربص انتظار مترقب مع مراقبة تحول الأحوال؛ وهو يصور المنافقين واقفين على النتائج ليظهروا لكل فريق أنهم معه طلبًا للغنيمة والنجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص226–230.","url":""}]},{"id":"s4-357","number":357,"surah":4,"verses":[141],"verseLabel":"النساء: 141","question":"ما دلالة اختلاف خطاب المنافقين عند فتح المؤمنين: ﴿ألم نكن معكم﴾، وعند نصيب الكافرين: ﴿ألم نستحوذ عليكم ونمنعكم من المؤمنين﴾؟","answer":"ادعوا للمؤمنين مجرد المعية ليستحقوا نصيبًا من الفتح، وادعوا للكافرين أنهم غلبوا أمرهم وحموهم من المؤمنين ليستحقوا عندهم يدًا؛ فتبدلت حجتهم بتبدل الجهة التي يطمعون فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص229–237.","url":""}]},{"id":"s4-358","number":358,"surah":4,"verses":[141],"verseLabel":"النساء: 141","question":"ما سرّ التعبير عن نصر المؤمنين بقوله تعالى: ﴿فتح من الله﴾؟","answer":"الفتح يلحظ إزالة ما كان مغلقًا من وجوه النصر والظفر، وإسناده إلى الله يقرر أن تحقق الغلبة للمؤمنين منه لا من مجرد قوتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص231–234.","url":""}]},{"id":"s4-359","number":359,"surah":4,"verses":[141],"verseLabel":"النساء: 141","question":"ما سرّ التعبير عما يناله الكافرون بقوله تعالى: ﴿نصيب﴾، دون: فتح أو نصر؟","answer":"سمى ما يقع للكافرين ﴿نَصِيبٌ﴾، أي حظًا عارضًا، ولم يشرفه باسم الفتح المسند إلى الله كما فعل مع المؤمنين؛ ففي اختلاف اللفظ اختلاف في تقويم النتيجتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص233–236.","url":""}]},{"id":"s4-360","number":360,"surah":4,"verses":[141],"verseLabel":"النساء: 141","question":"كيف يُفهم قوله تعالى: ﴿ولن يجعل الله للكافرين على المؤمنين سبيلًا﴾ مع وقوع غلبة للكافرين أحيانًا؟","answer":"لا تنفي الآية كل غلبة عارضة، بل تنفي السبيل المستقر الذي يستأصل به الكافرون جماعة المؤمنين، وقيل: تنفي حجتهم وسبيلهم عليهم يوم القيامة؛ فلا يعارضها ابتلاء يقع زمنًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص240–246.","url":""}]},{"id":"s4-361","number":361,"surah":4,"verses":[142],"verseLabel":"النساء: 142","question":"ما سرّ التعبير بقوله تعالى: ﴿إن المنافقين يخادعون الله﴾ بصيغة المفاعلة؟","answer":"صيغة المفاعلة تصور معاملتهم لله معاملة من يظن أنه يخدع مقابله بإظهار الإيمان وإبطان الكفر، مع أن وبال الخداع راجع إليهم والله عالم بسرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص248–252.","url":""}]},{"id":"s4-362","number":362,"surah":4,"verses":[142],"verseLabel":"النساء: 142","question":"ما دلالة مجيء فعل المنافقين مضارعًا في ﴿يخادعون﴾، وجواب الله جملة اسمية في ﴿وهو خادعهم﴾؟","answer":"المضارع يصور تجدد محاولتهم للخداع، والجملة الاسمية تثبت أن جزاء الله ومقابلته لخداعهم أمر محقق ملازم لا يفلتون منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص251–253.","url":""}]},{"id":"s4-363","number":363,"surah":4,"verses":[142],"verseLabel":"النساء: 142","question":"ما سرّ التعبير بقوله تعالى: ﴿قاموا إلى الصلاة﴾، دون: أقاموا الصلاة؟","answer":"﴿قاموا إلى الصلاة﴾ تصف مجرد توجههم إلى فعلها على كره، أما إقامتها فتدل على أدائها بحقوقها وحدودها؛ فاختير الأول لكشف حال المنافقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص252–255.","url":""}]},{"id":"s4-364","number":364,"surah":4,"verses":[142],"verseLabel":"النساء: 142","question":"ما دلالة وصف المنافقين بـ﴿كسالى﴾ بصيغة الاسم؟","answer":"الاسم أثبت من الفعل، فيصور الكسل صفة مستقرة تظهر كلما قاموا إلى الصلاة، لا حالة عابرة تقع مرة وتنقضي.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص254–256.","url":""}]},{"id":"s4-365","number":365,"surah":4,"verses":[142],"verseLabel":"النساء: 142","question":"ما مناسبة ذكر الرياء بعد الكسل في الصلاة؟","answer":"كشف الكسل فقدان الدافع الصادق إلى العبادة، ثم بيّن أن الدافع القليل الذي يحركهم هو رؤية الناس؛ فاجتمع في صلاتهم ضعف الباعث لله وقصد الخلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص255–257.","url":""}]},{"id":"s4-366","number":366,"surah":4,"verses":[142],"verseLabel":"النساء: 142","question":"كيف يجتمع إظهار المنافقين الصلاة مع قوله تعالى: ﴿ولا يذكرون الله إلا قليلًا﴾؟","answer":"صلاتهم الظاهرة ليست ناشئة عن إخلاص، ولذلك لا يصحبها من ذكر الله وحضور القلب إلا القليل؛ فالآية تكشف حقيقة العبادة وراء صورتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص257–261.","url":""}]},{"id":"s4-367","number":367,"surah":4,"verses":[143],"verseLabel":"النساء: 143","question":"ما الصورة في قوله تعالى: ﴿مذبذبين بين ذلك﴾، دون: مترددين؟","answer":"﴿مُذَبْذَبِينَ﴾ تصورهم كشيء تحركه قوتان من جانب إلى جانب فلا يثبت بنفسه؛ فهي أبلغ من مجرد التردد في تصوير اضطرابهم وتبعيتهم للمصلحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص262–265.","url":""}]},{"id":"s4-368","number":368,"surah":4,"verses":[143],"verseLabel":"النساء: 143","question":"ما دلالة إفراد اسم الإشارة في قوله تعالى: ﴿مذبذبين بين ذلك﴾ مع ذكر فريقين؟","answer":"أشير بـ﴿ذلك﴾ إلى الحال المذكورة أو إلى مجموع الجهتين بوصفهما أمرًا واحدًا حاضرًا في الذهن؛ فالإفراد عائد إلى المشار إليه المعنوي لا إلى عدد الفريقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص264–266.","url":""}]},{"id":"s4-369","number":369,"surah":4,"verses":[143],"verseLabel":"النساء: 143","question":"ما دلالة تكرار النفي في قوله تعالى: ﴿لا إلى هؤلاء ولا إلى هؤلاء﴾؟","answer":"كرر النفي ليثبت انتفاء انتمائهم إلى كل فريق على حدة؛ فلا هم مع المؤمنين باطنًا، ولا هم مع الكافرين على موقف معلن ثابت.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص265–268.","url":""}]},{"id":"s4-370","number":370,"surah":4,"verses":[144],"verseLabel":"النساء: 144","question":"ما سرّ اختيار الأولياء في قوله تعالى: ﴿لا تتخذوا الكافرين أولياء﴾، دون: أنصارًا؟","answer":"الولاية أوسع من النصرة؛ فهي تشمل القرب والموالاة والاعتماد وتسليم جانب من التدبير، فناسبت النهي عن رابطة تتجاوز الاستعانة العارضة إلى الولاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص270–273.","url":""}]},{"id":"s4-371","number":371,"surah":4,"verses":[144],"verseLabel":"النساء: 144","question":"ما دلالة قوله تعالى: ﴿من دون المؤمنين﴾، ثم قوله: ﴿أتريدون أن تجعلوا لله عليكم سلطانًا مبينًا﴾؟","answer":"﴿مِنْ دُونِ الْمُؤْمِنِينَ﴾ تكشف استبدال رابطة الإيمان بولاية الكافرين، والاستفهام يحذر من أن يصنعوا بهذا الاختيار حجة ظاهرة يستحقون بها مؤاخذة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص272–276.","url":""}]},{"id":"s4-372","number":372,"surah":4,"verses":[144],"verseLabel":"النساء: 144","question":"ما سرّ مجيء النهي في النساء خطابًا مباشرًا: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَتَّخِذُوا…﴾، وفي آل عمران بصيغة الغائب: ﴿لَا يَتَّخِذِ الْمُؤْمِنُونَ…﴾؟","answer":"آية النساء تواجه المؤمنين في سياق كشف المنافقين والتحذير من مسلكهم، فناسب النداء والنهي المباشر. وآل عمران تقرر أصلًا عامًا في سياق محاجة أهل الكتاب، فناسبها أسلوب الغائب.","sources":[{"label":"*مختصر لمسات بيانية*؛ منقول في Quranpedia، ملاحظة 44131.","url":""}]},{"id":"s4-373","number":373,"surah":4,"verses":[145],"verseLabel":"النساء: 145","question":"ما سرّ إظهار اسم المنافقين في قوله تعالى: ﴿إن المنافقين في الدرك الأسفل﴾، دون: إنهم؟","answer":"أظهر الاسم بدل الضمير لتسجيل وصف النفاق عليهم مرة أخرى وبيان أنه علة استحقاق الدرك الأسفل؛ فالمقام مقام تشنيع وحكم لا مجرد إحالة إلى سابق.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص277–280.","url":""}]},{"id":"s4-374","number":374,"surah":4,"verses":[145],"verseLabel":"النساء: 145","question":"ما سرّ التعبير بقوله تعالى: ﴿الدرك الأسفل﴾، دون: الطبقة السفلى؟","answer":"الدرك يقال للمراتب الهابطة، في مقابل الدرجات الصاعدة، وجعل المنافقين في أسفله يصور تناهي هبوطهم بسبب جمعهم الكفر والخداع والإفساد.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص279–282.","url":""}]},{"id":"s4-375","number":375,"surah":4,"verses":[145],"verseLabel":"النساء: 145","question":"ما مناسبة الاقتصار على النصير في قوله تعالى: ﴿ولن تجد لهم نصيرًا﴾؟","answer":"المقام مقام دفع العذاب عن أهل الدرك الأسفل، فناسب نفي النصير الذي يدفع ويمنع، ولم يحتج إلى ذكر الولي؛ لأن جهة الحاجة المقصودة هنا هي النصرة من العقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص283–285.","url":""}]},{"id":"s4-376","number":376,"surah":4,"verses":[146],"verseLabel":"النساء: 146","question":"ما دلالة ترتيب النجاة في قوله تعالى: ﴿تابوا وأصلحوا واعتصموا بالله وأخلصوا دينهم لله﴾؟","answer":"بدأت بالتوبة عن النفاق، ثم إصلاح ما أفسدوه، ثم الاعتصام بالله طلبًا للثبات، ثم إخلاص الدين له بإزالة أصل الرياء؛ فجمعت إزالة الماضي وبناء الحال وضمان الاستمرار.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص286–291.","url":""}]},{"id":"s4-377","number":377,"surah":4,"verses":[146],"verseLabel":"النساء: 146","question":"ما مناسبة ذكر الاعتصام بالله بعد الإصلاح؟","answer":"قد يبدأ المرء الإصلاح ثم ترده الفتن، فجاء الاعتصام بالله بعده ليدل على طلب الثبات والحفظ، فلا يكون الإصلاح حركة مؤقتة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص288–290.","url":""}]},{"id":"s4-378","number":378,"surah":4,"verses":[146],"verseLabel":"النساء: 146","question":"ما سرّ التعبير بقوله تعالى: ﴿فأولئك مع المؤمنين﴾، دون: من المؤمنين؟","answer":"ناسبت المعية حال من كان منفصلًا عن جماعة المؤمنين بنفاقه ثم عاد بالتوبة والإصلاح؛ فهي تبشر بإلحاقه بصحبتهم وحكمهم وجزائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص290–292.","url":""}]},{"id":"s4-379","number":379,"surah":4,"verses":[147],"verseLabel":"النساء: 147","question":"ما دلالة الاستفهام في قوله تعالى: ﴿ما يفعل الله بعذابكم إن شكرتم وآمنتم﴾؟","answer":"الاستفهام إنكاري ينفي أن تكون لله حاجة إلى تعذيبهم إذا شكروا وآمنوا؛ فالعذاب جزاء الكفر لا غرض مطلوب لذاته، وفيه فتح لباب الرجوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص294–296.","url":""}]},{"id":"s4-380","number":380,"surah":4,"verses":[147],"verseLabel":"النساء: 147","question":"ما دلالة الجمع بين الشكر والإيمان في قوله تعالى: ﴿إن شكرتم وآمنتم﴾؟","answer":"جمع الشكر الذي يظهر في الاعتراف بالنعمة والطاعة، والإيمان الذي يقوم عليه ذلك كله؛ لتكتمل استجابة الظاهر والباطن. ولا يلزم من عطفهما بالواو ترتيب في الرتبة أو الوقوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص295–297.","url":""}]},{"id":"s4-381","number":381,"surah":4,"verses":[147],"verseLabel":"النساء: 147","question":"ما دلالة وصف الله تعالى بقوله: ﴿شاكرًا عليمًا﴾؟","answer":"شكر الله لعبده هو قبوله طاعته وإثابته عليها ومضاعفة القليل منها، و﴿عليمًا﴾ تؤكد علمه بإيمانه وشكره ودوافعهما؛ فلا يضيع عنده عمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص297–301.","url":""}]},{"id":"s4-382","number":382,"surah":4,"verses":[148],"verseLabel":"النساء: 148","question":"ما دلالة تقييد النهي بالجهر في قوله تعالى: ﴿لا يحب الله الجهر بالسوء من القول﴾؟","answer":"خص الجهر لأنه ينشر السوء ويشيعه في الأسماع ويعتدي على الأعراض؛ أما ما يقع في النفس فله حكم آخر، ثم استثنت الآية المظلوم في حدود دفع ظلامته.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص302–305.","url":""}]},{"id":"s4-383","number":383,"surah":4,"verses":[148],"verseLabel":"النساء: 148","question":"ما دلالة استثناء ﴿إلا من ظلم﴾ من النهي عن الجهر بالسوء؟","answer":"أبيح للمظلوم أن يجهر بشكواه ويذكر ظلم ظالمه بقدر ما يسترد به حقه أو يدفع الضرر؛ فلا يحمل النهي على إسكات المظلوم، ولا يحمل الاستثناء على إطلاق العدوان.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص304–307.","url":""}]},{"id":"s4-384","number":384,"surah":4,"verses":[148],"verseLabel":"النساء: 148","question":"ما مناسبة ترتيب ﴿سميعًا عليمًا﴾ في ختام آية الجهر بالسوء؟","answer":"قدم السمع لأن السياق في قول يُجهر به فيُسمع، ثم جاء العلم ليشمل خفايا القصد ومقدار التجاوز وحدود الظلامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص305–309.","url":""}]},{"id":"s4-385","number":385,"surah":4,"verses":[149],"verseLabel":"النساء: 149","question":"ما دلالة مقابلة إبداء الخير بإخفائه، ثم إفراد العفو عن السوء؟","answer":"عممت الآية فعل الخير في حالتي ظهوره وخفائه، ثم خصت العفو لأنه الخير المقابل مباشرة للسوء المذكور قبلها، وهو أرفع استجابة عند القدرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص309–312.","url":""}]},{"id":"s4-386","number":386,"surah":4,"verses":[149],"verseLabel":"النساء: 149","question":"ما مناسبة الجمع بين العفو والقدرة في قوله تعالى: ﴿فإن الله كان عفوًا قديرًا﴾؟","answer":"العفو مع القدرة هو الكمال؛ لأن العاجز قد يترك الانتقام لعجزه، أما الله فيعفو وهو قادر، وفي ذلك حث للمؤمن على العفو حين يقدر.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص311–314.","url":""}]},{"id":"s4-387","number":387,"surah":4,"verses":[149],"verseLabel":"النساء: 149","question":"ما سرّ اختلاف التعبير بين قوله تعالى في النساء: ﴿إِنْ تُبْدُوا خَيْرًا أَوْ تُخْفُوهُ﴾، وفي الأحزاب: ﴿إِنْ تُبْدُوا شَيْئًا أَوْ تُخْفُوهُ﴾؟","answer":"في النساء قُيد الإبداء والإخفاء بالخير لأن المقام في العفو وحسن المعاملة، وفي الأحزاب عُمم بـ﴿شيئًا﴾ لأن علم الله هناك متعلق بكل ما يظهر أو يخفى، خيرًا كان أو غيره.","sources":[{"label":"*مختصر لمسات بيانية*؛ منقول في Quranpedia، ملاحظة 44146.","url":""}]},{"id":"s4-388","number":388,"surah":4,"verses":[150,151],"verseLabel":"النساء: 150–151","question":"ما دلالة تكرار ذكر الرسل في قوله تعالى: ﴿يكفرون بالله ورسله ويريدون أن يفرقوا بين الله ورسله﴾؟","answer":"ذكر الرسل أولًا لتقرير وقوع الكفر بهم، ثم أعيد ذكرهم لبيان صورة هذا الكفر ومشروع أصحابه: التفريق بين الإيمان بالله والإيمان برسله؛ فلكل ذكر وظيفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص316–321.","url":""}]},{"id":"s4-389","number":389,"surah":4,"verses":[150,151],"verseLabel":"النساء: 150–151","question":"ما دلالة تقديم قولهم ﴿نؤمن ببعض﴾ على ﴿ونكفر ببعض﴾؟","answer":"قدموا دعوى الإيمان لأنها الوجه الذي يتسترون به ويطلبون أن يجعل لهم طريقًا وسطًا، ثم كشف عطف الكفر أن هذا الإيمان الانتقائي لا يحقق حقيقة الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص319–322.","url":""}]},{"id":"s4-390","number":390,"surah":4,"verses":[150,151],"verseLabel":"النساء: 150–151","question":"ما دلالة قوله تعالى: ﴿ويريدون أن يتخذوا بين ذلك سبيلًا﴾ مع أنه لا منزلة بين الإيمان والكفر؟","answer":"حكى التعبير إرادتهم المزعومة أن يصنعوا طريقًا وسطًا بقبول بعض الرسل ورد بعضهم، ثم أبطلها الحكم ﴿أولئك هم الكافرون حقًا﴾؛ فالمذكور إرادتهم لا ثبوت ذلك السبيل.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص320–324.","url":""}]},{"id":"s4-391","number":391,"surah":4,"verses":[150,151],"verseLabel":"النساء: 150–151","question":"ما دلالة القصر في قوله تعالى: ﴿أولئك هم الكافرون حقًا﴾؟","answer":"ضمير الفصل و﴿حقًا﴾ يقطعان توهم منزلة وسطى بين الإيمان والكفر؛ فرفض رسول واحد نقض لأصل الإيمان بالرسل كلهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص322–325.","url":""}]},{"id":"s4-392","number":392,"surah":4,"verses":[152],"verseLabel":"النساء: 152","question":"ما دلالة ﴿أحد﴾ في قوله تعالى: ﴿ولم يفرقوا بين أحد منهم﴾؟","answer":"وقعت ﴿أحد﴾ في سياق النفي فتعم كل فرد من الرسل؛ أي لم يستثنوا رسولًا واحدًا من الإيمان، وبذلك تقابل تفريق الفريق السابق.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص327–329.","url":""}]},{"id":"s4-393","number":393,"surah":4,"verses":[152],"verseLabel":"النساء: 152","question":"ما دلالة قوله تعالى: ﴿أولئك سوف يؤتيهم أجورهم﴾ بعد وصف المؤمنين بالرسل جميعًا؟","answer":"اسم الإشارة يرفع شأنهم، و﴿سوف﴾ تؤكد الوعد بأجر مستقبل محقق، وجمع الأجور يقابل تعدد أعمال إيمانهم وطاعتهم؛ فالجزاء محفوظ وإن تأخر ميقاته.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص328–331.","url":""}]},{"id":"s4-394","number":394,"surah":4,"verses":[153],"verseLabel":"النساء: 153","question":"ما سرّ إظهار ﴿أهل الكتاب﴾ في قوله تعالى: ﴿يسألك أهل الكتاب أن تنزل عليهم كتابًا من السماء﴾، دون: يسألونك؟","answer":"إظهار الاسم يحدد أصحاب الطلب ويسجل عليهم وصفهم الذي كان ينبغي أن يحملهم على معرفة الوحي، كما يمهد لذكر تاريخ أسلافهم في التعنت مع موسى.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص332–335.","url":""}]},{"id":"s4-395","number":395,"surah":4,"verses":[153],"verseLabel":"النساء: 153","question":"ما مناسبة الانتقال من طلب إنزال كتاب إلى التذكير بقولهم لموسى: ﴿أرنا الله جهرة﴾؟","answer":"الطلب الأكبر من موسى شاهد على أن سؤالهم النبي ﷺ لم يصدر عن نقص دليل، بل هو امتداد لتعنت قديم تجاوز طلب الكتاب إلى طلب رؤية الله جهرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص334–338.","url":""}]},{"id":"s4-396","number":396,"surah":4,"verses":[153],"verseLabel":"النساء: 153","question":"ما دلالة قوله تعالى في الصاعقة: ﴿بظلمهم﴾، ثم في اتخاذ العجل: ﴿من بعد ما جاءتهم البينات﴾؟","answer":"عُللت الصاعقة بظلمهم في طلب الرؤية على وجه التعنت، ثم أبرز في اتخاذ العجل أنه وقع بعد مجيء البينات؛ فالثاني جريمة مضاعفة لوقوعها مع وضوح الدليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص336–340.","url":""}]},{"id":"s4-397","number":397,"surah":4,"verses":[148],"verseLabel":"النساء: 153؛ البقرة: 51، 92؛ الأعراف: 148","question":"ما سرّ حذف المفعول الثاني في قوله تعالى: ﴿ثم اتخذوا العجل﴾، وما تقديره؟","answer":"﴿اتَّخَذَ﴾ هنا بمعنى صيّر، ولذلك يتعدى إلى مفعولين؛ والمفعول الثاني محذوف تقديره: اتخذوا العجل إلهًا أو معبودًا. دل على المحذوف تصريحهم في موضع آخر: ﴿هذا إلهكم وإله موسى﴾، فحذفه إيجاز للعلم به من القصة.","sources":[{"label":"الواحدي، *التفسير البسيط*، تحت الأعراف: 152؛ نقلًا عن الطبري 9/70، والزجاج 2/379، والنحاس 3/84، [النص المحقق](https://tafsir.app/albaseet/7/152).","url":""}]},{"id":"s4-398","number":398,"surah":4,"verses":[154],"verseLabel":"النساء: 154","question":"ما سرّ اختلاف التعبير بين قوله تعالى في النساء والبقرة: ﴿رَفَعْنَا فَوْقَهُمُ الطُّورَ﴾، وفي الأعراف: ﴿نَتَقْنَا الْجَبَلَ فَوْقَهُمْ﴾؟","answer":"﴿رفعنا الطور﴾ يقرر وقوع الرفع في مقام أخذ الميثاق، أما ﴿نتقنا الجبل﴾ فيصور شدة اقتلاعه وزعزعته حتى صار كأنه ظلة، وهو أنسب بمشهد التخويف المفصل في الأعراف.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص550؛ يربط البقرة 63 و93 والنساء 154 بالأعراف 171.","url":""}]},{"id":"s4-399","number":399,"surah":4,"verses":[155,156],"verseLabel":"النساء: 155–156","question":"ما دلالة تراكم الجرائم في نسق واحد: نقض الميثاق، والكفر بالآيات، وقتل الأنبياء، وقولهم: قلوبنا غلف؟","answer":"جمع النسق أسباب المؤاخذة المتتابعة ليبين أن العقوبة لم تقع بذنب عارض، بل بتاريخ من نقض العهد والكفر والقتل والإصرار؛ فتراكم العطف يصور تراكم الجناية.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص342–349.","url":""}]},{"id":"s4-400","number":400,"surah":4,"verses":[155],"verseLabel":"النساء: 155","question":"ما دلالة قوله تعالى: ﴿وقتلهم الأنبياء بغير حق﴾ مع أن قتل الأنبياء لا يكون بحق؟","answer":"﴿بِغَيْرِ حَقٍّ﴾ قيد كاشف لا احترازي؛ فائدته التشنيع والإشارة إلى أنهم بلغوا الغاية في الظلم، حتى قتلوا الأنبياء اتباعًا للهوى من غير شبهة حق.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص346–349.","url":""}]},{"id":"s4-401","number":401,"surah":4,"verses":[155],"verseLabel":"النساء: 155","question":"ما دلالة الإضراب بقوله تعالى: ﴿بل طبع الله عليها بكفرهم﴾ بعد قولهم: ﴿قلوبنا غلف﴾؟","answer":"أبطل الإضراب دعواهم أن قلوبهم أوعية ممتلئة بالعلم أو مغلفة لا يصل إليها الخطاب، وبيّن الحقيقة: أن الطبع عليها جزاء كفرهم، لا عذر فطريًا لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص349–352.","url":""}]},{"id":"s4-402","number":402,"surah":4,"verses":[156],"verseLabel":"النساء: 156","question":"ما سرّ وصف قولهم على مريم بأنه ﴿بهتانًا عظيمًا﴾؟","answer":"البهتان كذب يحيّر من شدة افترائه، ووصفه بالعظيم يوافق فظاعة الطعن في مريم الطاهرة مع ما ظهر من آيات براءتها؛ فالجريمة عظيمة في موضوعها ودليل بطلانها.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص352–354.","url":""}]},{"id":"s4-403","number":403,"surah":4,"verses":[157],"verseLabel":"النساء: 157","question":"ما دلالة تكرار النفي في قوله تعالى: ﴿وما قتلوه وما صلبوه﴾؟","answer":"كرر النفي لإبطال كل دعوى على استقلال: لا تحقق قتل عيسى عليه السلام، ولا تحقق صلبه؛ ثم كشف أن منشأ خبرهم هو الشبه لا العلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص354–357.","url":""}]},{"id":"s4-404","number":404,"surah":4,"verses":[157],"verseLabel":"النساء: 157","question":"ما سرّ بناء قوله تعالى: ﴿ولكن شبه لهم﴾ للمجهول؟","answer":"صرف البناء للمجهول العناية عن تعيين من وقع عليه الشبه وكيفيته إلى الحقيقة المقصودة: أن ما رأوه أو توهموه لم يثبت قتل عيسى عليه السلام.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص356–359.","url":""}]},{"id":"s4-405","number":405,"surah":4,"verses":[157],"verseLabel":"النساء: 157","question":"ما سرّ جعل ﴿اتباع الظن﴾ استثناءً في قوله تعالى: ﴿ما لهم به من علم إلا اتباع الظن﴾؟","answer":"الاستثناء منقطع؛ أي ليس لهم علم أصلًا، وإنما غاية ما عندهم اتباع الظن. ووضع الظن عقب نفي العلم يفضح سقوط دعواهم ويؤكد أن الظن لا يصير علمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص357–360.","url":""}]},{"id":"s4-406","number":406,"surah":4,"verses":[158],"verseLabel":"النساء: 158","question":"ما دلالة الإضراب في قوله تعالى: ﴿بل رفعه الله إليه﴾ بعد نفي القتل والصلب؟","answer":"انتقل الإضراب من إبطال روايتهم إلى إثبات الحقيقة المقابلة المشرفة: لم يظفروا به، بل رفعه الله إليه؛ وإظهار اسم الله يقرر أن النجاة والرفع بقدرته.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص359–361.","url":""}]},{"id":"s4-407","number":407,"surah":4,"verses":[159],"verseLabel":"النساء: 159","question":"ما دلالة بناء التوكيد في قوله تعالى: ﴿وإن من أهل الكتاب إلا ليؤمنن به قبل موته﴾؟","answer":"اجتمع النفي والاستثناء ولام القسم ونون التوكيد لإفادة الاستغراق والتحقيق: ما من أحد من أهل الكتاب في الحال المرادة إلا سيقع منه الإيمان المذكور قبل الموت.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص360–362.","url":""}]},{"id":"s4-408","number":408,"surah":4,"verses":[159],"verseLabel":"النساء: 159","question":"ما دلالة عدم ذكر المشهود به في قوله تعالى: ﴿ويوم القيامة يكون عليهم شهيدًا﴾؟","answer":"حذف المشهود به ليعم ما يشهد به عيسى عليه السلام عليهم من تبليغه وعبوديته وموقفهم منه، ويحدد السياق منه تكذيبهم أو غلوهم فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص361–362.","url":""}]},{"id":"s4-409","number":409,"surah":4,"verses":[160],"verseLabel":"النساء: 160","question":"ما سرّ تقديم سبب التحريم في قوله تعالى: ﴿فبظلم من الذين هادوا حرمنا عليهم طيبات﴾؟","answer":"قدم الجار والمجرور لإبراز سبب العقوبة قبل ذكرها: فالتحريم لم يكن لخبث تلك الطيبات، وإنما وقع بسبب ظلمهم؛ وفي ذلك تشهير بالعلة وزجر عنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص363–367.","url":""}]},{"id":"s4-410","number":410,"surah":4,"verses":[160],"verseLabel":"النساء: 160","question":"ما دلالة وصف المحرمات بأنها ﴿طيبات أحلت لهم﴾؟","answer":"أبقى التعبير وصفها بالطيب وذكّر بأنها كانت حلالًا؛ ليبين أن التحريم عقوبة على ظلمهم لا حكمًا ناشئًا من خبث تلك الأطعمة في ذاتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص365–368.","url":""}]},{"id":"s4-411","number":411,"surah":4,"verses":[161],"verseLabel":"النساء: 161","question":"ما دلالة الجمع بين أخذ الربا وأكل أموال الناس بالباطل؟","answer":"أخذ الربا صورة مخصوصة من العدوان المالي وقد فعلوه مع النهي عنه، ثم عطف أكل الأموال بالباطل ليعم سائر وجوه الاعتداء؛ فجمع بين المثال البارز والأصل العام.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص367–369.","url":""}]},{"id":"s4-412","number":412,"surah":4,"verses":[162],"verseLabel":"النساء: 162","question":"ما دلالة الاستدراك بقوله تعالى: ﴿لكن الراسخون في العلم منهم﴾ بعد ذم أهل الكتاب؟","answer":"رفع الاستدراك توهم شمول الذم لجميع أهل الكتاب، فاستثنى من رسخ علمه وآمن منهم؛ وبذلك أنصف المحسن ولم يحمل أحدًا جناية غيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص370–372.","url":""}]},{"id":"s4-413","number":413,"surah":4,"verses":[162],"verseLabel":"النساء: 162","question":"ما دلالة تكرار مادتي الإيمان والإنزال في قوله تعالى: ﴿والمؤمنون يؤمنون بما أنزل إليك وما أنزل من قبلك﴾؟","answer":"وصفهم أولًا بالمؤمنين لثبوت الصفة، ثم ذكر فعلهم لبيان متعلقها. وكرر ﴿ما أنزل﴾ لتمييز القرآن المنزل إلى النبي ﷺ من الكتب السابقة مع جمعها في أصل التصديق.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص371–373.","url":""}]},{"id":"s4-414","number":414,"surah":4,"verses":[162],"verseLabel":"النساء: 162","question":"ما سرّ نصب ﴿والمقيمين الصلاة﴾ في قراءة المصحف مع عطف الصفات قبلها وبعدها؟","answer":"النصب على المدح والاختصاص يقطع النسق ليلفت إلى منزلة الصلاة؛ كأن المعنى: وأخص بالمدح المقيمين الصلاة، وليس في التركيب خطأ نحوي.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص372–373.","url":""}]},{"id":"s4-415","number":415,"surah":4,"verses":[7],"verseLabel":"النساء: 162؛ آل عمران: 7","question":"ما الفرق السياقي بين ﴿الرَّاسِخُونَ فِي الْعِلْمِ﴾ في النساء، و﴿الرَّاسِخُونَ فِي الْعِلْمِ﴾ في آل عمران؟","answer":"في آل عمران ظهر رسوخهم في منهج تلقي المحكم والمتشابه والتسليم للوحي، وفي النساء استدرك بهم على أهل الكتاب المذمومين فظهرت ثمرة العلم في الإيمان بالوحي وإقامة الصلاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج6، ص556، في مناسبة آل عمران والنساء؛ وج8، ص370–373.","url":""}]},{"id":"s4-416","number":416,"surah":4,"verses":[163],"verseLabel":"النساء: 163","question":"ما سرّ التعبير بقوله تعالى: ﴿إنا أوحينا إليك﴾، دون: أرسلناك؟","answer":"ركز الوحي على مصدر الرسالة وطريق تلقيها؛ وهو موضع احتجاج أهل الكتاب في طلب كتاب ينزل من السماء، أما الإرسال فيصف بعثة الرسول إلى الناس ولا يجيب وحده عن دعوى الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص375–377.","url":""}]},{"id":"s4-417","number":417,"surah":4,"verses":[163],"verseLabel":"النساء: 163","question":"ما دلالة تشبيه الوحي إلى محمد ﷺ بالوحي إلى نوح والنبيين من بعده؟","answer":"أدخل الوحي إلى النبي ﷺ في سنة الرسالات المتتابعة، فليس بدعًا يحتاج إلى الصورة المتعنتة التي طلبها أهل الكتاب؛ ومن صدق بوحي الأنبياء لزمه قبول نظيره إذا قامت حجته.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص377–380.","url":""}]},{"id":"s4-418","number":418,"surah":4,"verses":[163],"verseLabel":"النساء: 163","question":"ما مناسبة البدء بنوح عليه السلام في سلسلة الأنبياء هنا؟","answer":"بدأ بنوح لأنه أول رسول إلى أهل الأرض بعد ظهور الشرك العام، فصار أصلًا لسلسلة الرسالات التي يحتج بها على أهل الكتاب في وحدة الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص378–381.","url":""}]},{"id":"s4-419","number":419,"surah":4,"verses":[163],"verseLabel":"النساء: 163","question":"ما دلالة التعبير بقوله تعالى: ﴿كما أوحينا﴾؟","answer":"تفيد الكاف تشبيه الوحي إلى محمد ﷺ بالوحي الثابت للأنبياء قبله في أصل الحقيقة، و﴿ما﴾ المصدرية تجعل المعنى موجزًا: إيحاءً كإيحائنا إلى نوح ومن بعده.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص378–380.","url":""}]},{"id":"s4-420","number":420,"surah":4,"verses":[163],"verseLabel":"النساء: 163","question":"ما دلالة إجمال ﴿النبيين من بعده﴾ ثم تفصيل أسماء عدد منهم؟","answer":"أفاد الإجمال شمول سلسلة النبوة، ثم خص بعض الأنبياء بأسمائهم لشهرتهم وعلو مقامهم عند أهل الكتاب؛ فالتفصيل عطف خاص على عام للتنويه وإقامة الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص380–382.","url":""}]},{"id":"s4-421","number":421,"surah":4,"verses":[163],"verseLabel":"النساء: 163","question":"ما سرّ تقديم عيسى على أيوب عليهما السلام مع تقدم أيوب زمنًا؟","answer":"قُدّم عيسى تحقيقًا لنبوته وردًا على اليهود الذين كفروا به وطعنوا فيه، وهو محور الجدل في السياق؛ فاقتضى المقام تقديمه، لا ترتيب الأنبياء بحسب الزمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص381–383.","url":""}]},{"id":"s4-422","number":422,"surah":4,"verses":[163],"verseLabel":"النساء: 163","question":"ما سرّ العدول من ﴿أوحينا﴾ إلى ﴿وآتينا داود زبورًا﴾؟","answer":"الإيتاء هنا داخل في جنس الوحي، لكنه خص داود بعطاء معين هو الزبور بعد تقرير مطلق الإيحاء؛ فانتقل من الأصل المشترك إلى منقبة الكتاب المخصوص.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص382–384.","url":""}]},{"id":"s4-423","number":423,"surah":4,"verses":[84,85,86],"verseLabel":"النساء: 163؛ الأنعام: 84–86","question":"ما سرّ اختلاف ترتيب أسماء الأنبياء في النساء: 163 عن ترتيبهم في الأنعام: 84–86؟","answer":"سياق النساء يثبت وحدة الوحي ويرد على التفريق بين الرسل، فرتب الأسماء بحسب صلاتها بالحجة والمقام، وخص داود بالزبور. أما الأنعام ففي تعداد ذرية إبراهيم ومراتب هدايتهم، فلا يراد في الموضعين التسلسل الزمني.","sources":[{"label":"ابن جماعة، كشف المعاني في المتشابه من المثاني، ص144؛ إسلام ويب، باب النساء: 163.","url":""}]},{"id":"s4-424","number":424,"surah":4,"verses":[164],"verseLabel":"النساء: 164","question":"ما دلالة تكرار ﴿رسلًا﴾ في قوله تعالى: ﴿ورسلًا قد قصصناهم عليك من قبل ورسلًا لم نقصصهم عليك﴾؟","answer":"كرر الاسم لتكوين قسمين متقابلين مستقلين من الرسل: من عُرفت قصصهم ومن لم تُذكر؛ والتكرار يؤكد أن عدم القصص لا ينفي رسالتهم ولا يحصر عدد الرسل في المذكورين.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص386–391.","url":""}]},{"id":"s4-425","number":425,"surah":4,"verses":[164],"verseLabel":"النساء: 164","question":"ما دلالة ﴿لم﴾ في قوله تعالى: ﴿ورسلاً لم نقصصهم عليك﴾؟","answer":"نفت ﴿لم﴾ وقوع قصصهم إلى زمن الخطاب، ولم تستعمل ﴿لن﴾ التي تنفي المستقبل؛ فالمقصود بيان أن الوحي السابق لم يقصصهم، لا الحكم باستحالة ذكرهم بعد ذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص390–392.","url":""}]},{"id":"s4-426","number":426,"surah":4,"verses":[164],"verseLabel":"النساء: 164","question":"ما سرّ الجمع بين الفعل والمصدر في قوله تعالى: ﴿وكلم الله موسى تكليمًا﴾؟","answer":"المصدر المؤكد يثبت حقيقة التكليم وينفي حمل الفعل على مجرد الإلهام أو المجاز، فخص موسى بهذه المنقبة في سياق تنوع صور الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص392–394.","url":""}]},{"id":"s4-427","number":427,"surah":4,"verses":[165],"verseLabel":"النساء: 165","question":"ما مناسبة تقديم التبشير على الإنذار في قوله تعالى: ﴿رسلًا مبشرين ومنذرين﴾؟","answer":"قُدمت البشارة لأنها أقرب إلى فتح القلب ودعوته إلى القبول، ثم جاء الإنذار لمن أعرض؛ فجمع إرسالهم الترغيب والترهيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص394–396.","url":""}]},{"id":"s4-428","number":428,"surah":4,"verses":[165],"verseLabel":"النساء: 165","question":"ما سرّ التعبير في النساء بـ﴿رسلًا مبشرين ومنذرين﴾، وفي البقرة بـ﴿النبيين مبشرين ومنذرين﴾؟","answer":"سياق النساء في إقامة الحجة بالبلاغ، فناسب ﴿رسلًا﴾ لأن الرسالة تقتضي التكليف بالتبليغ. وفي البقرة جاء الكلام على بعث الأنبياء وإنزال الكتاب معهم في تاريخ اختلاف الناس، فناسب الاسم الأعم في ذلك السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص395–397.","url":""}]},{"id":"s4-429","number":429,"surah":4,"verses":[165],"verseLabel":"النساء: 165","question":"ما سرّ التعبير بقوله تعالى: ﴿لئلا يكون للناس على الله حجة﴾، دون: احتجاج؟","answer":"الحجة اسم للدليل الذي يمكن أن يقوم ويثبت، وهو أرسخ من مجرد فعل الاحتجاج؛ وإرسال الرسل يقطع عذر الجهل فلا يبقى للناس دليل يحتجون به بعدهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص396–398.","url":""}]},{"id":"s4-430","number":430,"surah":4,"verses":[165],"verseLabel":"النساء: 165","question":"ما دلالة قوله تعالى: ﴿بعد الرسل﴾ من غير ﴿من﴾؟","answer":"جاء الظرف مباشرة ليربط انتفاء الحجة بحصول إرسال الرسل، فمتى تم البلاغ انقطع العذر؛ ولا يحتاج المقام إلى إبراز ابتداء الغاية الذي تفيده ﴿من بعد﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص397–399.","url":""}]},{"id":"s4-431","number":431,"surah":4,"verses":[166],"verseLabel":"النساء: 166","question":"ما دلالة الاستدراك بقوله تعالى: ﴿لكن الله يشهد بما أنزل إليك﴾؟","answer":"إذا أنكر أهل الكتاب رسالته فإن إنكارهم لا يقدح فيها؛ فاستدرك بشهادة الله للوحي، وهي الشهادة الكافية التي لا يعارضها جحودهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص400–403.","url":""}]},{"id":"s4-432","number":432,"surah":4,"verses":[166],"verseLabel":"النساء: 166","question":"ما سرّ التعبير بقوله تعالى: ﴿بما أنزل إليك﴾، دون: بما أوحى إليك؟","answer":"الإنزال يبرز القرآن شيئًا منزلًا من عند الله إلى رسوله، وهو أنسب بمقام الشهادة على الكتاب الذي تحداهم وطالبوا بإنزاله؛ أما الوحي فيلحظ طريقة الإعلام في أصلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص401–404.","url":""}]},{"id":"s4-433","number":433,"surah":4,"verses":[166],"verseLabel":"النساء: 166","question":"ما دلالة قوله تعالى: ﴿أنزله بعلمه﴾؟","answer":"أي أنزله عالمًا بمن يستحق الرسالة وبما يحتاجه الخلق، وأنزله مشتملًا على علمه وحقه؛ فتعليق الإنزال بالعلم شهادة لمصدر القرآن ومضمونه ولمن تلقاه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص403–406.","url":""}]},{"id":"s4-434","number":434,"surah":4,"verses":[166],"verseLabel":"النساء: 166","question":"ما دلالة إفراد شهادة الله ثم عطف قوله تعالى: ﴿والملائكة يشهدون﴾؟","answer":"أفرد شهادة الله لأنها الأصل المستقل الكافي في إثبات الوحي، ثم عطف شهادة الملائكة تأييدًا؛ ولذلك ختم بأن الله وحده كافٍ شهيدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص405–408.","url":""}]},{"id":"s4-435","number":435,"surah":4,"verses":[166],"verseLabel":"النساء: 166","question":"ما سرّ التعبير بقوله تعالى: ﴿وكفى بالله شهيدًا﴾، دون: شاهدًا؟","answer":"﴿شهيد﴾ صيغة مبالغة تدل على كمال العلم والحضور وإقامة الحجة، والباء في هذا الأسلوب تؤكد كفاية شهادة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص407–409.","url":""}]},{"id":"s4-436","number":436,"surah":4,"verses":[167],"verseLabel":"النساء: 167","question":"ما دلالة الجمع بين الكفر والصد عن سبيل الله؟","answer":"الكفر ضلال صاحبه في نفسه، والصد عدوان يتعدى إلى منع غيره من طريق الحق؛ فجمعهما لأنهم أفسدوا الاعتقاد وحاربوا هداية الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص411–414.","url":""}]},{"id":"s4-437","number":437,"surah":4,"verses":[167],"verseLabel":"النساء: 167","question":"ما سرّ التعبير بقوله تعالى: ﴿وصدوا عن سبيل الله﴾، دون: ومنعوا الناس؟","answer":"الصد يجمع إعراضهم بأنفسهم وصرفهم غيرهم، و﴿سبيل الله﴾ تصور الدين طريقًا موصلًا إليه؛ فجريمتهم ليست منع أشخاص فحسب، بل إقامة العوائق في طريق الهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص412–415.","url":""}]},{"id":"s4-438","number":438,"surah":4,"verses":[167],"verseLabel":"النساء: 167","question":"ما دلالة قوله تعالى: ﴿قد ضلوا ضلالًا بعيدًا﴾ بعد الكفر والصد؟","answer":"حققت ﴿قد﴾ وقوع الضلال، وأكده المصدر، ووصفه بالبعد لأنهم لم يكتفوا بالانحراف بل صدوا غيرهم؛ فصار الرجوع أبعد مع تراكم الجريمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص414–416.","url":""}]},{"id":"s4-439","number":439,"surah":4,"verses":[168,169],"verseLabel":"النساء: 168–169","question":"ما دلالة الجمع بين ﴿كفروا وظلموا﴾ مع أن الكفر أعظم الظلم؟","answer":"الكفر يحدد فساد الاعتقاد، والظلم يشمل ما انضم إليه من تعد على الرسل والناس وصد عن الحق؛ فذكر الظلم لإظهار الجرائم العملية المترتبة على كفرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص417–420.","url":""}]},{"id":"s4-440","number":440,"surah":4,"verses":[168],"verseLabel":"النساء: 168","question":"ما سرّ التعبير بقوله تعالى: ﴿لم يكن الله ليغفر لهم﴾، دون: لن يغفر لهم؟","answer":"لام الجحود بعد ﴿لم يكن﴾ تنفي ملاءمة المغفرة لحال من استقر على الكفر والظلم، فهي أبلغ من خبر مستقبل مجرد؛ والتوبة تخرجه من هذا الوصف.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص418–421.","url":""}]},{"id":"s4-441","number":441,"surah":4,"verses":[168,169],"verseLabel":"النساء: 168–169","question":"كيف تُفهم الهداية في قوله تعالى: ﴿ولا ليهديهم طريقًا إلا طريق جهنم﴾؟","answer":"الهداية هنا بمعنى الدلالة والسوق إلى المصير الموافق للعمل، لا هداية التوفيق المحمودة؛ فطريق جهنم هو الطريق الذي انتهوا إليه بكفرهم وإصرارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص420–423.","url":""}]},{"id":"s4-442","number":442,"surah":4,"verses":[169],"verseLabel":"النساء: 169","question":"ما دلالة الجمع بين ﴿خالدين فيها﴾ و﴿أبدًا﴾؟","answer":"الخلود يدل على طول المكث أو دوامه بحسب السياق، وجاءت ﴿أبدًا﴾ لتقطع احتمال النهاية وتؤكد أن بقاءهم في جهنم لا ينقضي.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص422–424.","url":""}]},{"id":"s4-443","number":443,"surah":4,"verses":[169],"verseLabel":"النساء: 169","question":"ما دلالة تكرار لفظ ﴿طريقًا﴾ في قوله تعالى: ﴿ولا ليهديهم طريقًا إلا طريق جهنم﴾؟","answer":"كرر ﴿طريقًا﴾ ليجري الاستثناء على اللفظ نفسه: نُفي عنهم كل طريق نجاة، ثم أثبت الطريق الوحيد الذي ساقوا أنفسهم إليه، وهو طريق جهنم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص423–425.","url":""}]},{"id":"s4-444","number":444,"surah":4,"verses":[170],"verseLabel":"النساء: 170","question":"ما سرّ افتتاح الدعوة بقوله تعالى: ﴿يا أيها الناس﴾، دون تخصيص أهل الكتاب أو المؤمنين؟","answer":"عم الخطاب الناس لأن رسالة محمد ﷺ عامة، ولأن مجيء الرسول بالحق حجة على البشر جميعًا بعد محاجة أهل الكتاب خاصة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص426–429.","url":""}]},{"id":"s4-445","number":445,"surah":4,"verses":[170],"verseLabel":"النساء: 170","question":"ما دلالة تعريف الرسول في قوله تعالى: ﴿قد جاءكم الرسول بالحق﴾؟","answer":"التعريف للعهد؛ فهو الرسول المعروف الذي قامت دلائل رسالته وتقدمت أوصافه، لا رسولًا مجهولًا عابرًا، وفيه تفخيم لشأنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص427–430.","url":""}]},{"id":"s4-446","number":446,"surah":4,"verses":[170],"verseLabel":"النساء: 170","question":"ما دلالة تقييد الحق بقوله تعالى: ﴿من ربكم﴾؟","answer":"بيّن القيد مصدر الحق وأنه صادر من ربهم المتولي تربيتهم ومصلحتهم؛ فقبوله مقتضى الربوبية والرحمة، ورده ليس خلافًا مع الرسول وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص428–431.","url":""}]},{"id":"s4-447","number":447,"surah":4,"verses":[170],"verseLabel":"النساء: 170","question":"ما سرّ نصب ﴿خيرًا﴾ في قوله تعالى: ﴿فآمنوا خيرًا لكم﴾ من غير فعل ظاهر؟","answer":"أوجز الحذف وكثّر المعنى؛ فمن توجيهاته: فآمنوا يكن الإيمان خيرًا لكم، أو ائتوا إيمانًا خيرًا لكم. وفي كل وجه حث على الإيمان وبيان عاقبته النافعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص429–432.","url":""}]},{"id":"s4-448","number":448,"surah":4,"verses":[170],"verseLabel":"النساء: 170","question":"ما دلالة حذف جواب الشرط في قوله تعالى: ﴿وإن تكفروا فإن لله ما في السماوات والأرض﴾؟","answer":"دل تقرير الملك على الجواب المحذوف: فإن تكفروا فالله غني عنكم وعن إيمانكم وقادر على جزائكم؛ فتركه ليستنبط السامع من عموم الملك تهديدًا أوسع.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص430–432.","url":""}]},{"id":"s4-449","number":449,"surah":4,"verses":[171],"verseLabel":"النساء: 171","question":"ما مناسبة الانتقال من خطاب الناس جميعًا إلى قوله تعالى: ﴿يا أهل الكتاب﴾؟","answer":"بعد دعوة الناس إلى الرسول بالحق خص أهل الكتاب لأن الآيات التالية تعالج غلو النصارى في المسيح؛ فانتقل من أصل الرسالة العام إلى شبهة طائفة بعينها.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص433–436.","url":""}]},{"id":"s4-450","number":450,"surah":4,"verses":[171],"verseLabel":"النساء: 171","question":"ما الصورة في النهي بقوله تعالى: ﴿لا تغلوا في دينكم﴾؟","answer":"استعير الغلو، وهو مجاوزة الحد والارتفاع، للزيادة في الدين على ما شرعه الله؛ فصور الإفراط خروجًا عن الحد المرسوم، كما يرتفع الماء في غليانه أو يتجاوز السهم غايته.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص434–437.","url":""}]},{"id":"s4-451","number":451,"surah":4,"verses":[171],"verseLabel":"النساء: 171","question":"ما دلالة الجمع بين النهي عن الغلو والنهي عن القول على الله بغير الحق؟","answer":"الغلو أصل عام لكثير من الضلال، ثم خُص القول على الله بالباطل لعظم جريمة الافتراء التي نتج عنها تأليه المسيح؛ فهو عطف خاص على عام للاهتمام.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص435–438.","url":""}]},{"id":"s4-452","number":452,"surah":4,"verses":[171],"verseLabel":"النساء: 171","question":"ما دلالة وصف عيسى عليه السلام بأنه ﴿كلمته ألقاها إلى مريم وروح منه﴾؟","answer":"هو كلمة الله بمعنى أنه خُلق بكلمة ﴿كن﴾ من غير أب، وروح مخلوقة صادرة من عنده تشريفًا، لا جزءًا من ذاته؛ فالعبارتان تثبتان معجزة خلقه ولا تدلان على ألوهيته.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص437–440.","url":""}]},{"id":"s4-453","number":453,"surah":4,"verses":[171],"verseLabel":"النساء: 171","question":"ما سرّ التعبير بقوله تعالى: ﴿ألقاها إلى مريم﴾ بفعل الإلقاء وحرف ﴿إلى﴾؟","answer":"الإلقاء يدل على إيصال الكلمة إلى مريم من عند الله بلا وسائط الأسباب البشرية المعتادة، و﴿إلى﴾ تحدد جهة وصولها إليها؛ فبرزت خصوصية الخلق من غير أب.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص438–440.","url":""}]},{"id":"s4-454","number":454,"surah":4,"verses":[171],"verseLabel":"النساء: 171","question":"ما سرّ الإيجاز في قوله تعالى: ﴿ولا تقولوا ثلاثة﴾، دون تفصيل صورة التثليث؟","answer":"حذف المعدود ليعم النهي كل صيغة تجعل الألوهية ثلاثة، فلا يقر تركيبًا مخصوصًا من تراكيبهم ولا يتيح اختلاف عباراتها مهربًا من أصل النهي.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص440–442.","url":""}]},{"id":"s4-455","number":455,"surah":4,"verses":[171],"verseLabel":"النساء: 171","question":"ما سرّ نصب ﴿خيرًا﴾ في قوله تعالى: ﴿انتهوا خيرًا لكم﴾؟","answer":"التقدير: انتهوا يكن الانتهاء خيرًا لكم، أو ائتوا أمرًا خيرًا لكم؛ فحذف العامل للإيجاز، وجعل النهي عن التثليث موصولًا مباشرة بعاقبته النافعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص440–442.","url":""}]},{"id":"s4-456","number":456,"surah":4,"verses":[172],"verseLabel":"النساء: 172","question":"ما سرّ التعبير بقوله تعالى: ﴿لن يستنكف المسيح أن يكون عبدًا لله﴾، دون: لن يستكبر؟","answer":"الاستنكاف امتناع ناشئ من أنفة؛ فهو أدق في نفي أن يأنف المسيح من العبودية، ثم ذكر الاستكبار بعده لوعيد من يتعالى عن الطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص443–447.","url":""}]},{"id":"s4-457","number":457,"surah":4,"verses":[172],"verseLabel":"النساء: 172","question":"ما مناسبة عطف الملائكة المقربين على المسيح في مقام نفي الاستنكاف؟","answer":"ذُكر المسيح والملائكة ممن غلا فيهم بعض البشر؛ فإذا لم يأنف هؤلاء المقربون من عبودية الله فغيرهم أولى، وفي الجمع إبطال لتأليه المسيح والملائكة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص445–448.","url":""}]},{"id":"s4-458","number":458,"surah":4,"verses":[172],"verseLabel":"النساء: 172","question":"ما دلالة وصف الملائكة بـ﴿المقربين﴾ في هذا السياق؟","answer":"اختير أرفع أصناف الملائكة منزلة لإقامة الحجة من باب الأولى: إذا كان المقربون لا يستنكفون عن عبادة الله، فمن دونهم أولى ألا يأنف منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص446–449.","url":""}]},{"id":"s4-459","number":459,"surah":4,"verses":[172,173],"verseLabel":"النساء: 172–173","question":"ما دلالة الجمع بين الاستنكاف والاستكبار في الوعيد؟","answer":"الاستنكاف أنفة وامتناع عن العبادة، والاستكبار تعاظم وطلب للعلو؛ فجمعهما ليستوعب نفور الباطن ومظهر التعالي.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص449–451.","url":""}]},{"id":"s4-460","number":460,"surah":4,"verses":[174],"verseLabel":"النساء: 174","question":"ما دلالة الجمع بين قوله تعالى: ﴿قد جاءكم برهان من ربكم﴾ وقوله: ﴿وأنزلنا إليكم نورًا مبينًا﴾؟","answer":"البرهان حجة قاطعة تثبت صدق الرسالة، والنور هو القرآن الذي يكشف الحق ويبدد ظلمة الشك ويهدي الطريق؛ فالأول يقيم الدليل والثاني يحقق الكشف والهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص452–455.","url":""}]},{"id":"s4-461","number":461,"surah":4,"verses":[175],"verseLabel":"النساء: 175","question":"ما دلالة الجمع بين الإيمان بالله والاعتصام به؟","answer":"الإيمان تصديق وإقرار، والاعتصام لزوم عملي والتجاء إلى الله يحفظ صاحبه من الانحراف؛ فجمع بين أصل التصديق والثبات بمقتضاه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص456–458.","url":""}]},{"id":"s4-462","number":462,"surah":4,"verses":[175],"verseLabel":"النساء: 175","question":"ما دلالة ترتيب قوله تعالى: ﴿فسيدخلهم في رحمة منه وفضل ويهديهم إليه صراطًا مستقيمًا﴾؟","answer":"بدأ بالرحمة التي ينجون بها، ثم الفضل الذي يزاد لهم فوق النجاة، ثم الهداية إلى الصراط الموصل إلى رضوان الله؛ فجمع العطاء والمزيد والطريق الدائم إليهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص456–458.","url":""}]},{"id":"s4-463","number":463,"surah":4,"verses":[176],"verseLabel":"النساء: 176","question":"ما مناسبة ختم السورة بمسألة الكلالة بعد افتتاحها بأحكام الأسرة والمواريث؟","answer":"أحاطت أحكام الأسرة والحقوق ببناء السورة من أولها إلى آخرها، وخاتمة الكلالة تسد صورة دقيقة يكثر فيها التنازع؛ فعاد الختام إلى مقصد الافتتاح.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص459–462.","url":""}]},{"id":"s4-464","number":464,"surah":4,"verses":[176],"verseLabel":"النساء: 176","question":"ما سرّ حذف متعلق الاستفتاء أولًا ثم إظهاره في قوله تعالى: ﴿يستفتونك قل الله يفتيكم في الكلالة﴾؟","answer":"حُذف لأن السؤال كان حاضرًا معلومًا للمخاطبين، ثم أُظهر ﴿في الكلالة﴾ في جواب الله لرفع الاحتمال وتثبيت موضوع الحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص462–465.","url":""}]},{"id":"s4-465","number":465,"surah":4,"verses":[176],"verseLabel":"النساء: 176","question":"ما دلالة التصريح باسم الله في قوله تعالى: ﴿قل الله يفتيكم في الكلالة﴾؟","answer":"في التصريح تعظيم للفتوى وقطع لتحكم العرف والهوى في المواريث؛ فالمفتي هو الله، والرسول ﷺ مبلغ حكمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص464–465.","url":""}]},{"id":"s4-466","number":466,"surah":4,"verses":[176],"verseLabel":"النساء: 176","question":"ما سرّ التعبير بقوله تعالى: ﴿إن امرؤ هلك﴾، دون: مات؟","answer":"الهلاك هنا زوال الشخص وانتهاء حياته مع بقاء ماله للورثة، فناسب مقام انقطاع المورث وانتقال تركته، ولا يحمل في هذا الموضع على الذم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص466–468.","url":""}]},{"id":"s4-467","number":467,"surah":4,"verses":[176],"verseLabel":"النساء: 176","question":"ما سرّ عدم التصريح بالوالد في قوله تعالى: ﴿ليس له ولد وله أخت﴾ مع أن الكلالة تكون بغير والد ولا ولد؟","answer":"اكتفى بانتفاء الولد لأن حكم الأخت المذكور واسم الكلالة يدلان على انتفاء الوالد؛ فلو وجد الأب لم ترث الأخت هذا الفرض، فحذفه إيجاز لدلالة الحكم عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص467–468.","url":""}]},{"id":"s4-468","number":468,"surah":4,"verses":[176],"verseLabel":"النساء: 176","question":"ما سرّ زيادة ﴿اثنتين﴾ في قوله تعالى: ﴿فإن كانتا اثنتين﴾ مع دلالة ألف الاثنين عليها؟","answer":"جاءت ﴿اثنتين﴾ لتثبيت العدد الذي ينبني عليه الفرض ورفع احتمال عود الضمير إلى فئتين أو جماعتين؛ فهي توكيد مبيّن لا حشو.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص468–470.","url":""}]},{"id":"s4-469","number":469,"surah":4,"verses":[176],"verseLabel":"النساء: 176","question":"ما سرّ التعبير بقوله تعالى: ﴿يبين الله لكم أن تضلوا﴾، دون: لئلا تضلوا؟","answer":"التقدير: يبين الله لكم كراهة أن تضلوا، أو يبين لكم لئلا تضلوا؛ فحذف ما دل عليه مقام البيان، وجاء المصدر المؤول موجزًا في بيان غاية الفتوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص470–472.","url":""}]},{"id":"s4-470","number":470,"surah":4,"verses":[176],"verseLabel":"النساء: 176","question":"ما مناسبة ختم السورة بقوله تعالى: ﴿والله بكل شيء عليم﴾؟","answer":"تفاصيل المواريث مبنية على علم محيط بالقرابات والمصالح والعواقب، فتعَلّل الخاتمة الأحكام بعلم الله وتدعو إلى التسليم، كما تستقل بعموم علمه بكل شيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص471–474.","url":""}]},{"id":"s4-471","number":471,"surah":4,"verses":[176],"verseLabel":"النساء: 176","question":"ما سرّ بدء فتوى الكلالة بقوله تعالى: ﴿يَسْتَفْتُونَكَ﴾ بلا واو، مع مجيء فتوى النساء قبلها: ﴿وَيَسْتَفْتُونَكَ فِي النِّسَاءِ﴾ بالواو؟","answer":"فتوى الكلالة استئناف مستقل في خاتمة السورة بعد انقضاء السياق السابق، أما فتوى النساء فعُطفت بالواو على أحكام النساء المتصلة قبلها؛ فالحرف يكشف صلة كل سؤال بسياقه.","sources":[{"label":"*مختصر لمسات بيانية*؛ منقول في Quranpedia، ملاحظة 44175.","url":""}]},{"id":"s5-1","number":1,"surah":5,"verses":[1],"verseLabel":"المائدة: السورة","question":"ما سرّ تسمية السورة بـ﴿المائدة﴾؟","answer":"سُمّيت سورة المائدة لاختصاصها بذكر المائدة التي طلب الحواريون من عيسى عليه السلام أن يسأل ربه إنزالها، ولم ترد قصتها في سورة أخرى. وسُمّيت أيضًا سورة العقود لافتتاحها بالأمر بالوفاء بالعقود.","sources":[{"label":"ابن عاشور، *التحرير والتنوير*، مقدمة سورة المائدة؛ [النص المنشور](https://quran.com/ar/al-maidah/info).","url":""}]},{"id":"s5-2","number":2,"surah":5,"verses":[1],"verseLabel":"المائدة: 1","question":"ما مناسبة افتتاح سورة المائدة بالأمر: ﴿أوفوا بالعقود﴾؟","answer":"افتتحت بالوفاء لأن السورة تشتمل على عقود ومواثيق كثيرة مع الله وبين الناس، وعلى أحكام الحلال والحرام والشهادة؛ فجاء المطلع براعة استهلال لمقاصدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص488–503.","url":""}]},{"id":"s5-3","number":3,"surah":5,"verses":[1],"verseLabel":"المائدة: 1","question":"ما سرّ التعبير بقوله تعالى: ﴿أوفوا بالعقود﴾ بالجمع، دون: أوفوا بالعهد؟","answer":"العقود أعم من عهد واحد؛ فهي تشمل ما عقده الله على عباده وما تعاقده الناس بينهم، والجمع يستوعب كثرة الالتزامات التي تفصلها السورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص488–503.","url":""}]},{"id":"s5-4","number":4,"surah":5,"verses":[1],"verseLabel":"المائدة: 1","question":"ما الصورة في التعبير عن العهود بـ﴿العقود﴾؟","answer":"العقد في الأصل ربط طرفين ربطًا محكمًا، فاستعير للعهد الذي يلزم صاحبه ولا يحله بالهوى؛ وفي الصورة معنى التوثيق والقوة واللزوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص488–503.","url":""}]},{"id":"s5-5","number":5,"surah":5,"verses":[1],"verseLabel":"المائدة: 1","question":"ما مناسبة ذكر تحليل بهيمة الأنعام عقب الأمر بالوفاء بالعقود؟","answer":"بعد الأمر الجامع بالوفاء بدأ بتفصيل أول ما عقده الله عليهم من أحكام الحلال والحرام؛ فصار تحليل الأنعام وما استثني منها تطبيقًا مباشرًا للعقد العام.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص488–503.","url":""}]},{"id":"s5-6","number":6,"surah":5,"verses":[1],"verseLabel":"المائدة: 1","question":"ما سرّ بناء قوله تعالى: ﴿أُحلت لكم﴾ للمجهول؟","answer":"بُني الفعل للمفعول لأن المحلِّل معلوم وهو الله، ولتوجيه العناية إلى النعمة والحكم نفسه؛ ثم صُرح بسلطان الله في الخاتمة: ﴿إن الله يحكم ما يريد﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص488–503.","url":""}]},{"id":"s5-7","number":7,"surah":5,"verses":[1],"verseLabel":"المائدة: 1","question":"ما سرّ التعبير بقوله تعالى: ﴿بهيمة الأنعام﴾، دون الاكتفاء بالأنعام؟","answer":"﴿بهيمة﴾ تعم الحيوان الذي لا ينطق، و﴿الأنعام﴾ تبين الجنس المقصود؛ فالإضافة تضبط المباح في الأنعام وما يلحق بها، ولا تترك لفظ البهيمة على عمومه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص488–503.","url":""}]},{"id":"s5-8","number":8,"surah":5,"verses":[1],"verseLabel":"المائدة: 1","question":"ما سرّ إجمال المستثنى في قوله تعالى: ﴿إلا ما يتلى عليكم﴾؟","answer":"أُجمل المحرم أولًا لأن بيانه سيأتي قريبًا في الآية الثالثة، وفي الإحالة إلى ما يتلوه الوحي تشويق للبيان وربط للحكم بالشرع لا بعادة الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص488–503.","url":""}]},{"id":"s5-9","number":9,"surah":5,"verses":[1],"verseLabel":"المائدة: 1","question":"ما سرّ التعبير بقوله تعالى: ﴿غير محلي الصيد وأنتم حرم﴾ بدل التصريح: وحرم عليكم الصيد في الإحرام؟","answer":"جاء النهي في صورة حال تقيد المخاطبين وقت الانتفاع بالإباحة: أحلت لكم الأنعام حال كونكم غير مستحلين للصيد وأنتم محرمون؛ فجمع التركيب سعة النعمة وحدها في جملة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص488–503.","url":""}]},{"id":"s5-10","number":10,"surah":5,"verses":[1],"verseLabel":"المائدة: 1","question":"ما مناسبة ختم أول آية بقوله تعالى: ﴿إن الله يحكم ما يريد﴾؟","answer":"الخاتمة تقرر أن التحليل والتحريم حكم الله وحده، وأن استثناء الصيد حال الإحرام داخل في سلطانه التشريعي، فلا تخضع الحدود لأهواء الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص488–503.","url":""}]},{"id":"s5-11","number":11,"surah":5,"verses":[2],"verseLabel":"المائدة: 2","question":"ما دلالة تكرار نداء المؤمنين في أول الآية الثانية بعد وروده في الآية الأولى؟","answer":"جُدد النداء لأن الآية الثانية تفتتح عقدًا جديدًا من الأحكام يتعلق بتعظيم الشعائر والعدل مع الخصوم؛ فالتكرار ينبه إلى استقلال التكليف وأهميته.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص504–523.","url":""}]},{"id":"s5-12","number":12,"surah":5,"verses":[2],"verseLabel":"المائدة: 2","question":"ما الصورة في قوله تعالى: ﴿لا تحلوا شعائر الله﴾؟","answer":"الإحلال جعل ما له حرمة كأنه حلال مباح، فالنهي يصور انتهاك الشعائر بفك سياج حرمتها؛ وإضافتها إلى الله تعظمها لأنها أعلام طاعته.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص504–523.","url":""}]},{"id":"s5-13","number":13,"surah":5,"verses":[2],"verseLabel":"المائدة: 2","question":"ما دلالة إضافة الشعائر إلى اسم الله في قوله تعالى: ﴿شعائر الله﴾؟","answer":"الإضافة للتشريف والتعظيم، وتقرر أن حرمة هذه المعالم مستمدة من نسبتها إلى الله لا من عادات القبائل؛ لذلك كان انتهاكها اعتداءً على حدوده.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص504–523.","url":""}]},{"id":"s5-14","number":14,"surah":5,"verses":[2],"verseLabel":"المائدة: 2","question":"ما دلالة ذكر الشهر الحرام والهدي والقلائد بعد النهي العام عن إحلال شعائر الله؟","answer":"ذكر الخاص بعد العام للعناية بأبرز الشعائر التي كانت مظنة الاعتداء: حرمة الزمن، والهدي، وعلامته الظاهرة، وقاصدو البيت؛ ففصّل ما تشتد الحاجة إلى صيانته.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص504–523.","url":""}]},{"id":"s5-15","number":15,"surah":5,"verses":[2],"verseLabel":"المائدة: 2","question":"ما سرّ إسناد الإحلال إلى ﴿الشهر الحرام﴾ مع أن المقصود انتهاك حرمته؟","answer":"أسند الإحلال إلى الشهر نفسه مبالغةً، كأن التعرض لحرمته جعل الشهر كله مستباحًا؛ فحذف المضاف وأقيم المضاف إليه مقامه لقوة التحذير.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص504–523.","url":""}]},{"id":"s5-16","number":16,"surah":5,"verses":[2],"verseLabel":"المائدة: 2","question":"ما مناسبة تخصيص ﴿القلائد﴾ بالذكر بعد ﴿الهدي﴾ وهي منه؟","answer":"القلائد العلامة الظاهرة التي يعرف بها الهدي فيأمن، وتخصيصها بعد عموم الهدي يشدد حرمة ما ظهر شعاره حتى لا يُعتدى عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص504–523.","url":""}]},{"id":"s5-17","number":17,"surah":5,"verses":[2],"verseLabel":"المائدة: 2","question":"ما سرّ وصف قاصدي البيت بقوله تعالى: ﴿آمين البيت الحرام﴾، دون: الحجاج؟","answer":"﴿آمّين﴾ بمعنى قاصدين، وتستحضر حركة توجههم المستمر نحو البيت وحرمة وجهتهم؛ وهي أوسع من الاسم الذي يصفهم بعد تحقق الحج.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص504–523.","url":""}]},{"id":"s5-18","number":18,"surah":5,"verses":[2],"verseLabel":"المائدة: 2","question":"كيف يُفهم وصف قاصدي البيت بقوله تعالى: ﴿يبتغون فضلًا من ربهم ورضوانًا﴾ مع دخول من لم يصح إيمانه فيهم زمن النزول؟","answer":"حكى التعبير مقصدهم في ظاهر أمرهم وما يزعمون طلبه من فضل الله بالتجارة ومن رضوانه بالنسك، وليس في ذلك تصحيح لعقيدتهم؛ إنما هو بيان لحرمة القاصد ما دام داخلًا في العهد القائم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص504–523.","url":""}]},{"id":"s5-19","number":19,"surah":5,"verses":[2],"verseLabel":"المائدة: 2","question":"ما دلالة الأمر في قوله تعالى: ﴿وإذا حللتم فاصطادوا﴾؛ أهو للوجوب؟","answer":"الأمر بعد حظر الصيد حال الإحرام يرفع المنع ويعيد الإباحة، ولا يوجب الصيد؛ فالسياق صرف صيغة الأمر من الطلب إلى الإذن.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص504–523.","url":""}]},{"id":"s5-20","number":20,"surah":5,"verses":[2],"verseLabel":"المائدة: 2","question":"ما الصورة في قوله تعالى: ﴿لا يجرمنكم شنآن قوم﴾؟","answer":"﴿يجرمنكم﴾ أي لا يحملنكم أو يكسبنكم بغض قوم جريمة العدوان؛ فصُور الشنآن قوةً تدفع صاحبها ليحذر أثرها في حكمه وسلوكه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص504–523.","url":""}]},{"id":"s5-21","number":21,"surah":5,"verses":[2,8],"verseLabel":"المائدة: 2، 8","question":"ما سرّ اختلاف التعدية بين قوله تعالى: ﴿لا يجرمنكم شنآن قوم أن صدوكم﴾، وقوله: ﴿لا يجرمنكم شنآن قوم على ألا تعدلوا﴾؟","answer":"في الآية الثانية بيّن ﴿أن صدوكم﴾ سبب الشنآن الذي قد يحمل على الاعتداء، وفي الآية الثامنة صرحت ﴿على﴾ بالغاية التي قد يدفع إليها البغض وهي ترك العدل؛ فالأولى تذكر باعث العداوة والثانية نتيجتها المحذورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص523–524، وله عودة عند آية 8.","url":""}]},{"id":"s5-22","number":22,"surah":5,"verses":[2],"verseLabel":"المائدة: 2","question":"ما مناسبة الانتقال من أحكام الحج والصيد إلى قوله تعالى: ﴿وتعاونوا على البر والتقوى ولا تعاونوا على الإثم والعدوان﴾؟","answer":"بعد النهي عن الانتقام ممن صدوا المؤمنين عمّم المبدأ: تكون المعاملة تعاونًا على الخير وصيانة الحدود، لا تعاونًا على المعصية والاعتداء؛ فارتقى من الواقعة إلى قاعدة اجتماعية شاملة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص504–523.","url":""}]},{"id":"s5-23","number":23,"surah":5,"verses":[2],"verseLabel":"المائدة: 2","question":"ما دلالة الجمع بين ﴿البر والتقوى﴾ ومقابلتهما بـ﴿الإثم والعدوان﴾؟","answer":"البر فعل الخير، والتقوى صيانة النفس من مخالفة الله؛ وقوبلا بالإثم الذي يفسد صاحبه، والعدوان الذي يتجاوز إلى حق غيره؛ فاستوعبت المقابلة وجهي الصلاح والفساد.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص504–523.","url":""}]},{"id":"s5-24","number":24,"surah":5,"verses":[2],"verseLabel":"المائدة: 2","question":"ما دلالة تقديم ﴿الإثم﴾ على ﴿العدوان﴾؟","answer":"الإثم أصل المعصية في ذات الفاعل، والعدوان أثرها المتجاوز إلى غيره؛ فبدأ بفساد العمل ثم بما ينشأ عنه من تعدي الحدود والحقوق.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص504–523.","url":""}]},{"id":"s5-25","number":25,"surah":5,"verses":[2],"verseLabel":"المائدة: 2","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿إن الله شديد العقاب﴾؟","answer":"لما كثرت النواهي عن انتهاك الشعائر والاعتداء والتعاون على الإثم جاءت الخاتمة زجرًا يضمن جدية الحدود؛ فمن خالفها فالله شديد العقاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص504–523.","url":""}]},{"id":"s5-26","number":26,"surah":5,"verses":[3],"verseLabel":"المائدة: 3","question":"ما سرّ بناء قوله تعالى في المائدة: ﴿حرمت عليكم الميتة﴾ للمجهول، مع التصريح بالفعل في البقرة: ﴿إنما حرم عليكم الميتة﴾؟","answer":"فصّلت المائدة قائمة المحرمات فوجه البناء للمفعول العناية إلى الأصناف المحكوم عليها، والفاعل معلوم من التشريع السابق واللاحق. أما البقرة فورد الفعل ضمن تقرير أن التحريم من الله في سياق محاجة من يحرم بغير إذنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص524–565.","url":""}]},{"id":"s5-27","number":27,"surah":5,"verses":[3],"verseLabel":"المائدة: 3","question":"ما سرّ التعبير بقوله تعالى: ﴿حرمت عليكم الميتة﴾ مع أن المقصود أكلها؟","answer":"حُذف الأكل للعلم به لأنه أبرز وجوه الانتفاع المقصودة في سياق المطعومات، وإسناد التحريم إلى عين الميتة أبلغ في تنفير النفس منها ومنع تناولها.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص524–565.","url":""}]},{"id":"s5-28","number":28,"surah":5,"verses":[3],"verseLabel":"المائدة: 3","question":"ما سرّ تخصيص ﴿لحم الخنزير﴾ بالذكر، مع إسناد التحريم إلى الميتة والدم نفسيهما؟","answer":"خُص اللحم لأنه المقصود الأعظم من الخنزير في باب الطعام، فذكر محل الأكل منه مباشرة؛ أما الميتة والدم فاسما المحرم نفسه ولا يحتاجان إلى هذا القيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص524–565.","url":""}]},{"id":"s5-29","number":29,"surah":5,"verses":[3],"verseLabel":"المائدة: 3","question":"ما سرّ تقديم ﴿لغير الله﴾ في قوله تعالى في المائدة: ﴿وما أهل لغير الله به﴾، وتأخيره في البقرة: ﴿وما أهل به لغير الله﴾؟","answer":"في المائدة جاء تفصيل شعائر الجاهلية وما خُصص لغير الله، فقدم الجهة التي أفسدت الذبيحة موضع العناية. وفي البقرة عُني أولًا بالفعل الواقع على الذبيحة ثم بيّن أن الإهلال كان لغير الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص524–565.","url":""}]},{"id":"s5-30","number":30,"surah":5,"verses":[3],"verseLabel":"المائدة: 3","question":"ما مناسبة تفصيل المنخنقة والموقوذة والمتردية والنطيحة بعد دخولها في عموم الميتة؟","answer":"فُصلت لأنها طرق واقعة لموت الأنعام وقد يلتبس بعضها بالمذكى، فالتفصيل يسد منافذ التحايل ويبين الصور التي تلحق بالميتة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص524–565.","url":""}]},{"id":"s5-31","number":31,"surah":5,"verses":[3],"verseLabel":"المائدة: 3","question":"ما سرّ التعبير بقوله تعالى: ﴿وما أكل السبع﴾ مع أن السبع قد يترك من الفريسة بقية؟","answer":"أطلق الأكل على الافتراس والأخذ؛ فالمراد ما عدا عليه السبع فأصابه إصابة الموت، ولو لم يستوعب أكله. واستثني ما أُدرك حيًا فذُكي.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص524–565.","url":""}]},{"id":"s5-32","number":32,"surah":5,"verses":[3],"verseLabel":"المائدة: 3","question":"ما سرّ التعبير بقوله تعالى: ﴿إلا ما ذكيتم﴾، دون: إلا ما ذبحتم؟","answer":"التذكية إتمام الذبح الشرعي الذي تطيب به الذبيحة، وهي أوسع وأدق من مجرد إحداث الذبح؛ لأنها تقيد الاستثناء بإدراك الحيوان حيًا واستيفاء التذكية.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص524–565.","url":""}]},{"id":"s5-33","number":33,"surah":5,"verses":[3],"verseLabel":"المائدة: 3","question":"ما مناسبة ذكر ﴿وما ذبح على النصب﴾ بعد قوله تعالى: ﴿وما أهل لغير الله به﴾؟","answer":"ما أُهل لغير الله به يلحظ الاسم المقصود عند الذبح، وما ذبح على النصب يلحظ المكان والشعيرة الوثنية ولو لم يسم اسم الصنم؛ فذكرهما يسد طريقي الشرك في القصد والمشهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص524–565.","url":""}]},{"id":"s5-34","number":34,"surah":5,"verses":[3],"verseLabel":"المائدة: 3","question":"ما مناسبة إدخال الاستقسام بالأزلام في سياق المطعومات المحرمة؟","answer":"السياق لا يقتصر على ذوات الأطعمة، بل يبطل طرائق الجاهلية في الذبح وتعيين المباح والمحظور؛ والاستقسام بالأزلام كان وسيلة يحكمون بها في شؤونهم، فجمعه مع النصب جامع الشعيرة الوثنية.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص524–565.","url":""}]},{"id":"s5-35","number":35,"surah":5,"verses":[3],"verseLabel":"المائدة: 3","question":"إلام يعود اسم الإشارة المفرد في قوله تعالى: ﴿ذلكم فسق﴾ بعد المذكورات المتعددة؟","answer":"يجوز أن يعود إلى أقرب مذكور وهو الاستقسام بالأزلام، ويجوز أن يجمع ما تقدم بوصفه أمرًا واحدًا من الخروج عن طاعة الله؛ فالإفراد باعتبار المشار إليه معنىً واحدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص524–565.","url":""}]},{"id":"s5-36","number":36,"surah":5,"verses":[3],"verseLabel":"المائدة: 3","question":"ما سرّ وصف المذكور بقوله تعالى: ﴿ذلكم فسق﴾، دون الاكتفاء بوصفه بالحرام؟","answer":"الفسق خروج عن طاعة الله، وهو يلائم الاستقسام والنصب لما فيهما من شعيرة جاهلية وتمرد على حكم الله؛ فليس الحكم منعًا فقهيًا مجردًا بل انحرافًا عقديًا وعمليًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص524–565.","url":""}]},{"id":"s5-37","number":37,"surah":5,"verses":[3],"verseLabel":"المائدة: 3","question":"ما مناسبة مجيء قوله تعالى: ﴿اليوم يئس الذين كفروا من دينكم﴾ وسط أحكام المطعومات؟","answer":"أعلن الاعتراض أن اكتمال سلطان الدين قطع طمع الكافرين في إبطاله؛ فيتلقى المؤمن أحكام الحلال والحرام من الله غير خائف من ضغطهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص524–565.","url":""}]},{"id":"s5-38","number":38,"surah":5,"verses":[3],"verseLabel":"المائدة: 3","question":"ما دلالة حذف ياء المتكلم في قوله تعالى: ﴿واخشون﴾؟","answer":"حُذفت الياء تخفيفًا واكتفاءً بالكسرة الدالة عليها، وجاء الرسم على هذا الإيجاز؛ وبقي توجيه الخشية إلى الله وحده في مقابلة ﴿فلا تخشوهم﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص524–565.","url":""}]},{"id":"s5-39","number":39,"surah":5,"verses":[3],"verseLabel":"المائدة: 3","question":"ما دلالة تكرار ﴿اليوم﴾ في قوله تعالى: ﴿اليوم يئس﴾ ثم ﴿اليوم أكملت﴾؟","answer":"استأنفت كل جملة بـ﴿اليوم﴾ لتعظيم الحدثين وتثبيتهما في الزمن نفسه: يأس الكافرين، وإكمال الدين وإتمام النعمة؛ فكان الثاني علة كبرى للأول.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص524–565.","url":""}]},{"id":"s5-40","number":40,"surah":5,"verses":[3],"verseLabel":"المائدة: 3","question":"ما سرّ التعبير بقوله تعالى: ﴿أكملت لكم دينكم﴾، دون: أكملت ديني؟","answer":"تقديم ﴿لكم﴾ يبرز أن كمال الدين نعمة ومصلحة عائدة إلى المخاطبين، مع أن الدين لله؛ والمقام مقام امتنان عليهم بما استكمل لهم من التشريع والهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص524–565.","url":""}]},{"id":"s5-41","number":41,"surah":5,"verses":[3],"verseLabel":"المائدة: 3","question":"ما الفرق بين الإكمال في قوله تعالى: ﴿أكملت لكم دينكم﴾، والإتمام في قوله: ﴿وأتممت عليكم نعمتي﴾؟","answer":"الإكمال بلوغ أجزاء الدين وتشريعاته الغاية المطلوبة، والإتمام بلوغ النعمة حدها الوافي بوصفها عطاءً على العباد؛ فناسب كل فعل متعلقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص524–565.","url":""}]},{"id":"s5-42","number":42,"surah":5,"verses":[3],"verseLabel":"المائدة: 3","question":"ما دلالة تعدية الدين باللام في ﴿أكملت لكم دينكم﴾، والنعمة بـ﴿على﴾ في ﴿أتممت عليكم نعمتي﴾؟","answer":"اللام تبرز منفعة كمال الدين العائدة إليهم، و﴿على﴾ تصور النعمة واصلةً نازلةً عليهم ومستعلية بإحسانها؛ فوافقت كل صلة جهة معناها.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص524–565.","url":""}]},{"id":"s5-43","number":43,"surah":5,"verses":[3],"verseLabel":"المائدة: 3","question":"ما سرّ إفراد النعمة في قوله تعالى: ﴿نعمتي﴾ مع كثرة نعم الله؟","answer":"أفردت النعمة باعتبار الجنس الجامع، أو باعتبار نعمة الإسلام والهداية التي تنتظم تحتها نعم كثيرة؛ فالإفراد للتعظيم والجمع المعنوي لا لنفي التعدد.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص524–565.","url":""}]},{"id":"s5-44","number":44,"surah":5,"verses":[3],"verseLabel":"المائدة: 3","question":"ما دلالة تقديم ﴿لكم﴾ في قوله تعالى: ﴿ورضيت لكم الإسلام دينًا﴾؟","answer":"قدم ﴿لكم﴾ للاهتمام بالمخاطبين وإبراز الاختصاص والمنفعة: اختار الله لهم الإسلام ورضيه طريقًا لهم، فلا يطلبون عنه بديلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص524–565.","url":""}]},{"id":"s5-45","number":45,"surah":5,"verses":[3],"verseLabel":"المائدة: 3","question":"ما مناسبة العودة إلى حكم المضطر في المخمصة بعد إعلان كمال الدين؟","answer":"جملة إكمال الدين اعترضت بين تفصيل المحرمات واستثناء حال الضرورة، ثم عاد الكلام إلى تمام الحكم. وفي ذلك بيان أن كمال التشريع يشمل العزيمة والرخصة والرحمة بالمضطر.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص524–565.","url":""}]},{"id":"s5-46","number":46,"surah":5,"verses":[3],"verseLabel":"المائدة: 3","question":"ما سرّ التعبير عن شدة الجوع بـ﴿مخمصة﴾؟","answer":"المخمصة المجاعة الشديدة التي تخمص فيها البطون، أي تضمر وتلتصق من الجوع؛ فاللفظ يصور أثر الضرورة في الجسد ولا يدل على جوع عادي.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص524–565.","url":""}]},{"id":"s5-47","number":47,"surah":5,"verses":[3],"verseLabel":"المائدة: 3","question":"ما الصورة في قوله تعالى: ﴿غير متجانف لإثم﴾؟","answer":"التجانف ميل متعمد إلى جانب؛ فالقيد يصور من يتخذ الضرورة ذريعة مائلًا نحو المعصية. إنما الرخصة لمن ألجأته المخمصة من غير قصد للإثم ولا تجاوز للحاجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص524–565.","url":""}]},{"id":"s5-48","number":48,"surah":5,"verses":[3],"verseLabel":"المائدة: 3","question":"ما مناسبة ختم حكم المضطر بقوله تعالى: ﴿فإن الله غفور رحيم﴾ مع أنه غير متعمد للمعصية؟","answer":"المغفرة تستر ما قد يقع في حال الاضطرار من تناول المحرم، والرحمة هي التي شرعت الرخصة ورفعت الحرج؛ فالخاتمة تطمئن المضطر وتبين أصل التيسير.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص524–565.","url":""}]},{"id":"s5-49","number":49,"surah":5,"verses":[3],"verseLabel":"المائدة: 3","question":"ما سرّ إجمال المحرمات في أربعة أصول في الأنعام، وتفصيل صور الميتة في المائدة؟","answer":"الأنعام مكية تقرر الأصول الجامعة ردًا على تحريم المشركين بغير علم، والمائدة مدنية تفصل الأحكام العملية وصور الميتة التي قد تلتبس بالمذكى؛ فناسب كل مقام درجته من البيان.","sources":[{"label":"موسوعة التفسير البلاغي، الموضع العكسي: ج12، ص373 وما بعدها.","url":""}]},{"id":"s5-50","number":50,"surah":5,"verses":[4],"verseLabel":"المائدة: 4","question":"ما مناسبة سؤالهم: ﴿ماذا أحل لهم﴾ بعد تفصيل المحرمات؟","answer":"لما فُصل المحرم سألوا عن الجانب المقابل، ولا سيما حكم الصيد بالجوارح؛ فجاء السؤال انتقالًا طبيعيًا من حدود المنع إلى قاعدة المباح وكيفية تحصيله.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص566–577.","url":""}]},{"id":"s5-51","number":51,"surah":5,"verses":[4],"verseLabel":"المائدة: 4","question":"ما دلالة إعادة الفعل في الجواب: ﴿قل أحل لكم الطيبات﴾؟","answer":"أعيد الفعل ليأتي الجواب جملة تشريعية تامة مسندة إلى التحليل الإلهي، لا مجرد تسمية أصناف؛ وفي مطابقته للسؤال تقرير للحكم وتثبيت له.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص566–577.","url":""}]},{"id":"s5-52","number":52,"surah":5,"verses":[4],"verseLabel":"المائدة: 4","question":"ما سرّ الإجمال في قوله تعالى: ﴿أحل لكم الطيبات﴾ دون تعدادها؟","answer":"جمع ﴿الطيبات﴾ كل ما استلذته الفطر السليمة ولم يرد تحريمه، فجعل الأصل قاعدة واسعة تستوعب أفرادًا متجددة بدل حصرها في قائمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص566–577.","url":""}]},{"id":"s5-53","number":53,"surah":5,"verses":[4],"verseLabel":"المائدة: 4","question":"ما سرّ تسمية حيوانات الصيد المدرَّبة ﴿الجوارح﴾؟","answer":"الجوارح من الجرح بمعنى الكسب، لأنها تكسب الصيد لصاحبها، ومن الجرح الحسي لأنها تمسكه بمخالبها أو أنيابها؛ فجمع الاسم فعلها وأثرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص566–577.","url":""}]},{"id":"s5-54","number":54,"surah":5,"verses":[4],"verseLabel":"المائدة: 4","question":"ما سرّ التعبير بقوله تعالى: ﴿مكلبين﴾ مع دخول جوارح من الطير في الحكم؟","answer":"التكليب تعليم الجوارح الصيد، واشتق من الكلب لأنه أشهر ما يدرب عليه وأكثره استعمالًا؛ فغلب اسمه على مهنة التعليم مع شمول الحكم لغيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص566–577.","url":""}]},{"id":"s5-55","number":55,"surah":5,"verses":[4],"verseLabel":"المائدة: 4","question":"ما دلالة قوله تعالى: ﴿تعلمونهن مما علمكم الله﴾؟","answer":"رد علم الإنسان بالتدريب إلى فضل الله الذي وهبه الفهم والقدرة؛ و﴿من﴾ تفيد أن ما عنده بعض من تعليم الله الواسع، فيجمع الحكم الامتنان والتواضع.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص566–577.","url":""}]},{"id":"s5-56","number":56,"surah":5,"verses":[4],"verseLabel":"المائدة: 4","question":"ما سرّ تعدية الإمساك بـ﴿على﴾ في قوله تعالى: ﴿مما أمسكن عليكم﴾، دون: لكم؟","answer":"تفيد ﴿عليكم﴾ أن الجارحة حبست الصيد وخصصته بصاحبها ولم تستقل بأكله لنفسها؛ ففي الحرف معنى الاستعلاء على الصيد مع حفظه لأجلكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص566–577.","url":""}]},{"id":"s5-57","number":57,"surah":5,"verses":[4],"verseLabel":"المائدة: 4","question":"ما دلالة إفراد الضمير في قوله تعالى: ﴿واذكروا اسم الله عليه﴾ بعد ذكر الجوارح جمعًا؟","answer":"عاد الضمير إلى ما أمسكت الجوارح، أي إلى الصيد أو المصيد، وهو مفرد اللفظ يشمل كل فرد؛ فليس مرجعه الجوارح حتى يلزم جمعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص566–577.","url":""}]},{"id":"s5-58","number":58,"surah":5,"verses":[4],"verseLabel":"المائدة: 4","question":"ما مناسبة ختم أحكام الصيد بقوله تعالى: ﴿إن الله سريع الحساب﴾؟","answer":"تفاصيل الصيد قد تخفى على الناس من إرسال الجارحة وأكلها وقصد صاحبها، فذكرت سرعة الحساب للمراقبة وعدم التساهل؛ فالله لا يشغله حساب عن حساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص566–577.","url":""}]},{"id":"s5-59","number":59,"surah":5,"verses":[5],"verseLabel":"المائدة: 5","question":"ما دلالة تكرار قوله تعالى: ﴿اليوم أحل لكم الطيبات﴾ بعد قوله: ﴿قل أحل لكم الطيبات﴾؟","answer":"الأولى جواب عام عن الطيبات وصيد الجوارح، والثانية تستأنف مرحلة من تمام التشريع تعلن فيها إباحة طعام أهل الكتاب والزواج من محصناتهم؛ فلكل تحليل متعلق جديد.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص578–589.","url":""}]},{"id":"s5-60","number":60,"surah":5,"verses":[5],"verseLabel":"المائدة: 5","question":"ما سرّ التعبير بقوله تعالى: ﴿الذين أوتوا الكتاب﴾، دون: أهل الكتاب؟","answer":"يستحضر الموصول أصل الوحي الذي بني عليه الحكم، لا مجرد هويتهم الاجتماعية؛ ففيه تذكير بأنهم أصحاب كتاب سابق.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص578–589.","url":""}]},{"id":"s5-61","number":61,"surah":5,"verses":[5],"verseLabel":"المائدة: 5","question":"ما دلالة قوله تعالى: ﴿وطعامكم حل لهم﴾ مع أن المقصود بيان ما يحل للمؤمنين؟","answer":"أثبتت الجملة المعاملة المتبادلة ورفعت الحرج عن المؤاكلة من الجانبين، فالإباحة ليست انتفاع المسلم بطعامهم فقط، بل باب صلة اجتماعية منضبطة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص578–589.","url":""}]},{"id":"s5-62","number":62,"surah":5,"verses":[5],"verseLabel":"المائدة: 5","question":"ما سرّ التعبير بالمصدر في قوله تعالى: ﴿حل لكم﴾، دون: أحل لكم؟","answer":"المصدر الواقع خبرًا يثبت وصف الحل للطعام ثبوتًا واستقرارًا، بينما الفعل يبرز حدوث التشريع؛ فناسب هنا تقرير الإباحة المتبادلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص578–589.","url":""}]},{"id":"s5-63","number":63,"surah":5,"verses":[5],"verseLabel":"المائدة: 5","question":"ما مناسبة الجمع في آية واحدة بين طعام أهل الكتاب والزواج من نسائهم؟","answer":"جمع الحكمين لأن كليهما يفتح باب المخالطة الاجتماعية الوثيقة مع أهل الكتاب: مشاركة الطعام وتكوين الأسرة، مع إبقاء ضوابط الإيمان والعفة والعقد.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص578–589.","url":""}]},{"id":"s5-64","number":64,"surah":5,"verses":[5],"verseLabel":"المائدة: 5","question":"ما مناسبة ذكر ﴿المحصنات من المؤمنات﴾ قبل محصنات أهل الكتاب مع أن حل المؤمنات معلوم؟","answer":"ذُكرت المؤمنات أولًا تشريفًا وبيانًا للأصل الأقرب، ثم ألحقت بهن محصنات أهل الكتاب؛ وقيد الإحصان يربط الإباحة بالعفة والزواج الصحيح.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص578–589.","url":""}]},{"id":"s5-65","number":65,"surah":5,"verses":[5],"verseLabel":"المائدة: 5","question":"ما سرّ تقييد حل الزواج بقوله تعالى: ﴿المحصنات﴾، دون: نساء الذين أوتوا الكتاب؟","answer":"الإحصان هنا العفة، فقيد الإباحة بالمرأة المصونة عن الزنا، وربط الزواج بعلاقة تحفظ العرض لا بمجرد الانتماء إلى أهل الكتاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص578–589.","url":""}]},{"id":"s5-66","number":66,"surah":5,"verses":[5],"verseLabel":"المائدة: 5","question":"ما دلالة قوله تعالى عن أهل الكتاب: ﴿من قبلكم﴾؟","answer":"ذكّر القيد بأن إيتاءهم الكتاب سبق نزول القرآن، فالحكم متعلق بأصحاب الوحي السابق المعروف، وفيه وصل الرسالات مع بيان موقعهم الزمني من الأمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص578–589.","url":""}]},{"id":"s5-67","number":67,"surah":5,"verses":[5],"verseLabel":"المائدة: 5","question":"ما سرّ تسمية المهور في قوله تعالى: ﴿إذا آتيتموهن أجورهن﴾؟","answer":"سمي المهر أجرًا لأنه حق مالي واجب في مقابلة عقد النكاح وما يترتب عليه من اختصاص، لا لأنه ثمن للمرأة؛ والتعبير يؤكد وجوب إيتائه لها.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص578–589.","url":""}]},{"id":"s5-68","number":68,"surah":5,"verses":[5],"verseLabel":"المائدة: 5","question":"ما الفرق بين السفاح واتخاذ الأخدان في قوله تعالى: ﴿محصنين غير مسافحين ولا متخذي أخدان﴾؟","answer":"السفاح زنا معلن أو علاقة بلا اختصاص، والأخدان علاقات سرية يتخذ فيها كل طرف صاحبًا مخصوصًا؛ فنفى القرآن الفاحشة في صورتها الظاهرة والخفية، وأثبت قصد الإحصان.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص578–589.","url":""}]},{"id":"s5-69","number":69,"surah":5,"verses":[5],"verseLabel":"المائدة: 5","question":"ما مناسبة الانتقال من إباحة الطعام والزواج إلى قوله تعالى: ﴿ومن يكفر بالإيمان فقد حبط عمله﴾؟","answer":"بعد توسيع المخالطة مع أهل الكتاب حذرت الخاتمة من أن تتحول الرخصة إلى ذوبان عقدي؛ فتبقى الإباحة داخل حفظ الإيمان، ومن يرفضه يبطل عمله.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص578–589.","url":""}]},{"id":"s5-70","number":70,"surah":5,"verses":[5],"verseLabel":"المائدة: 5","question":"ما سرّ التعبير بقوله تعالى: ﴿ومن يكفر بالإيمان﴾، دون: ومن لم يؤمن؟","answer":"جعل الإيمان نفسه متعلقًا للكفر ليصور رفضه بعد ظهوره وتحققه، لا مجرد غياب التصديق ابتداءً؛ وفيه تشنيع على استبدال الكفر بنعمة الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص578–589.","url":""}]},{"id":"s5-71","number":71,"surah":5,"verses":[5],"verseLabel":"المائدة: 5","question":"ما الصورة في قوله تعالى: ﴿حبط عمله﴾؟","answer":"الحبط في الأصل فساد ينتفخ به بطن الدابة ثم يهلكها، فاستعير للعمل الذي يبدو موجودًا ثم يسقط أثره وثوابه بسبب الكفر؛ صورة خسارة بعد توهم النماء.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص578–589.","url":""}]},{"id":"s5-72","number":72,"surah":5,"verses":[5],"verseLabel":"المائدة: 5","question":"ما مناسبة قوله تعالى: ﴿وهو في الآخرة من الخاسرين﴾ بعد حبوط العمل؟","answer":"حبوط العمل يبين ضياع ما قدم، والخسارة في الآخرة تبين المآل الذي يظهر فيه ذلك الضياع؛ فجمع فقدان الرصيد وفوات النجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص578–589.","url":""}]},{"id":"s5-73","number":73,"surah":5,"verses":[6],"verseLabel":"المائدة: 6","question":"ما مناسبة الانتقال من أحكام الطعام والزواج إلى أحكام الطهارة للصلاة؟","answer":"تتابع السورة عقود التشريع التي افتتحت بالأمر بالوفاء بها؛ فبعد طيب المطعم والأسرة جاء تطهير البدن استعدادًا لأعظم العبادات، وكلها حدود يتلقى المؤمن حكمها من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص591–619.","url":""}]},{"id":"s5-74","number":74,"surah":5,"verses":[6],"verseLabel":"المائدة: 6","question":"كيف يُفهم قوله تعالى: ﴿إذا قمتم إلى الصلاة فاغسلوا وجوهكم﴾ مع أن الوضوء يسبق الدخول فيها؟","answer":"القيام إلى الشيء يأتي بمعنى إرادة الشروع فيه والتوجه إليه؛ أي إذا أردتم القيام إلى الصلاة وأنتم محدثون فتوضؤوا، كما يقال: إذا قرأت فاستعذ، أي إذا أردت القراءة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص591–619.","url":""}]},{"id":"s5-75","number":75,"surah":5,"verses":[6],"verseLabel":"المائدة: 6","question":"ما دلالة ترتيب أعضاء الوضوء: الوجه واليدان والرأس والرجلان؟","answer":"بدأ بالوجه وهو أشرف الأعضاء وأظهرها، ثم اليدين وهما آلة العمل، ثم مسح الرأس، وختم بالرجلين اللتين تحملان البدن؛ وجاء الترتيب بيانًا عمليًا منظمًا لشعيرة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص591–619.","url":""}]},{"id":"s5-76","number":76,"surah":5,"verses":[6],"verseLabel":"المائدة: 6","question":"ما سرّ ذكر الغاية في ﴿إلى المرافق﴾ و﴿إلى الكعبين﴾، دون حد مماثل للوجه والرأس؟","answer":"حد اليد والرجل في الاستعمال يحتمل امتدادهما إلى مواضع مختلفة، فاحتاجا إلى بيان الغاية بالمرافق والكعبين؛ أما حدود الوجه والرأس فمعروفة بأسماء العضوين.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص591–619.","url":""}]},{"id":"s5-77","number":77,"surah":5,"verses":[6],"verseLabel":"المائدة: 6","question":"ما سرّ التعبير بقوله تعالى: ﴿وإن كنتم جنبًا فاطهروا﴾، دون: فاغتسلوا؟","answer":"التطهر أوسع من مجرد صب الماء، فيدل على إزالة وصف الجنابة عن البدن كله بالطهارة التامة؛ فناسب الحكم الكلي لا تسمية وسيلته وحدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص591–619.","url":""}]},{"id":"s5-78","number":78,"surah":5,"verses":[6],"verseLabel":"المائدة: 6","question":"ما الصورة في قوله تعالى: ﴿أو على سفر﴾، دون: أو مسافرين؟","answer":"صورت ﴿على﴾ المسافر كأنه راكب حالًا ممتدة مستولية على وقته، لا متصفًا بوصف عابر؛ فناسبت ما في السفر من حركة ومشقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص606.","url":""}]},{"id":"s5-79","number":79,"surah":5,"verses":[6],"verseLabel":"المائدة: 6","question":"ما سرّ الكناية في قوله تعالى: ﴿أو جاء أحد منكم من الغائط﴾؟","answer":"الغائط في الأصل المكان المنخفض الذي يقصده الإنسان ليستتر، ثم كُني بالمجيء منه عن قضاء الحاجة؛ فحفظ التعبير الأدب وتجنب التصريح بما يستقبح ذكره.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص608–611.","url":""}]},{"id":"s5-80","number":80,"surah":5,"verses":[6],"verseLabel":"المائدة: 6","question":"ما سرّ الكناية بقوله تعالى: ﴿أو لامستم النساء﴾؟","answer":"عبّر بالملامسة عن الجماع كنايةً تحفظ أدب الخطاب، وفي القراءة الأخرى ﴿لمستم﴾ مجال للمعنى الفقهي المعروف؛ فاختير لفظ قريب يفهم منه المقصود بلا فحش.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص610–611.","url":""}]},{"id":"s5-81","number":81,"surah":5,"verses":[6],"verseLabel":"المائدة: 6","question":"ما دلالة قوله تعالى: ﴿فتيمموا صعيدًا طيبًا﴾؟","answer":"التيمم هو القصد، والصعيد وجه الأرض، والطيب الطاهر؛ أي اقصدوا عند فقد الماء أو تعذر استعماله جزءًا طاهرًا من جنس الأرض، فجمع اللفظ القصد والبديل وصفته.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص591–619.","url":""}]},{"id":"s5-82","number":82,"surah":5,"verses":[6],"verseLabel":"المائدة: 6","question":"ما دلالة زيادة ﴿منه﴾ في آية المائدة: ﴿فامسحوا بوجوهكم وأيديكم منه﴾، وحذفها في النساء؟","answer":"﴿منه﴾ تبين ابتداء المسح من الصعيد أو تعلق شيء منه باليد، فصرحت المائدة بما يُفهم من ذكر الصعيد في النساء؛ والموضعان متكاملان لا متعارضان.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص615.","url":""}]},{"id":"s5-83","number":83,"surah":5,"verses":[6],"verseLabel":"المائدة: 6","question":"ما دلالة نفي الحرج ثم إثبات إرادة التطهير وإتمام النعمة؟","answer":"نفى أن يكون تشريع الطهارة والتيمم لإيقاع المشقة، ثم أثبت غايته الإيجابية: تطهير المؤمن ظاهرًا وباطنًا وإتمام نعمة العبادة مع وجود العذر؛ فالتكليف رحمة لا عنت.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص591–619.","url":""}]},{"id":"s5-84","number":84,"surah":5,"verses":[6],"verseLabel":"المائدة: 6","question":"ما مناسبة ختم آية الطهارة بقوله تعالى: ﴿لعلكم تشكرون﴾؟","answer":"لأن الله جمع لهم طهارة الماء ورخصة التيمم عند العجز، فأتم النعمة ولم يقطعهم عن الصلاة؛ وهذه النعمة تستدعي الشكر بالاعتراف والطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص591–619.","url":""}]},{"id":"s5-85","number":85,"surah":5,"verses":[6],"verseLabel":"المائدة: 6","question":"ما سرّ اختيار ﴿إذا﴾ في قوله تعالى: ﴿إذا قمتم إلى الصلاة﴾، و﴿إن﴾ في قوله: ﴿وإن كنتم جنبًا﴾؟","answer":"﴿إذا﴾ لما يتكرر ويتوقع من القيام إلى الصلاة، و﴿إن﴾ للجنابة لأنها حالة عارضة لا تتحقق كل مرة؛ فاختلاف الأداة يطابق اختلاف الوقوع.","sources":[{"label":"موسوعة التفسير البلاغي، الموضع العكسي: ج65، ص120–121.","url":""}]},{"id":"s5-86","number":86,"surah":5,"verses":[7],"verseLabel":"المائدة: 7","question":"ما سرّ إفراد النعمة في قوله تعالى: ﴿واذكروا نعمة الله عليكم﴾؟","answer":"أفردت باعتبار جنس النعمة الشامل، أو النعمة العظمى المتمثلة في الهداية والتشريع، فتدخل فيها نعم كثيرة يستحضرها كل مخاطب.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص620–628.","url":""}]},{"id":"s5-87","number":87,"surah":5,"verses":[7],"verseLabel":"المائدة: 7","question":"ما دلالة الجمع بين ﴿نعمة الله﴾ و﴿ميثاقه الذي واثقكم به﴾؟","answer":"النعمة تستدعي الشكر حبًا واعترافًا، والميثاق يستدعي الوفاء التزامًا؛ فجمع الدافع الوجداني والعهد الملزم حتى تقوم الطاعة عليهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص620–628.","url":""}]},{"id":"s5-88","number":88,"surah":5,"verses":[7],"verseLabel":"المائدة: 7","question":"ما سرّ التعبير بقوله تعالى: ﴿واثقكم به﴾، دون: أخذه عليكم؟","answer":"المواثقة من الوثاق، وفيها معنى الإحكام والتوكيد والتزام الطرف المخاطب بما قبله؛ فهي أبلغ من مجرد وقوع الأخذ في تصوير قوة العهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص620–628.","url":""}]},{"id":"s5-89","number":89,"surah":5,"verses":[7],"verseLabel":"المائدة: 7","question":"ما مناسبة استحضار قول المؤمنين: ﴿سمعنا وأطعنا﴾ هنا؟","answer":"هذا القول هو مضمون قبول الميثاق: سمع فهم وقبول، وطاعة تنفيذ؛ فذكّرهم بإقرارهم السابق قبل أن يأمرهم بالوفاء والعدل في الآيات التالية.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص620–628.","url":""}]},{"id":"s5-90","number":90,"surah":5,"verses":[7],"verseLabel":"المائدة: 7","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿إن الله عليم بذات الصدور﴾ بعد قولهم: ﴿سمعنا وأطعنا﴾؟","answer":"لأن الوفاء لا يثبت بظاهر القول وحده؛ فالله يعلم ما في الصدور من صدق الطاعة أو نية النقض، وجاءت الخاتمة مراقبةً للباطن بعد إعلان اللسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص620–628.","url":""}]},{"id":"s5-91","number":91,"surah":5,"verses":[8],"verseLabel":"المائدة: 8","question":"ما سرّ اختلاف الترتيب بين قوله تعالى في المائدة: ﴿قوامين لله شهداء بالقسط﴾، وفي النساء: ﴿قوامين بالقسط شهداء لله﴾؟","answer":"في المائدة المقام وفاء بعهد الله وعدل مع قوم مبغضين، فقدم القيام لله وجعل القسط وصف الشهادة. وفي النساء المقام شهادة على النفس والأقربين، فقدم القسط لمقاومة المحاباة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص629–638.","url":""}]},{"id":"s5-92","number":92,"surah":5,"verses":[8],"verseLabel":"المائدة: 8","question":"ما دلالة صيغة المبالغة في قوله تعالى: ﴿قوامين﴾، دون: قائمين؟","answer":"﴿قوامين﴾ تدل على قوة القيام بالحق وتكرره والثبات عليه؛ فليس المطلوب موقف عدل عابرًا، بل أن يصير القيام لله وصفًا راسخًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص629–638.","url":""}]},{"id":"s5-93","number":93,"surah":5,"verses":[8],"verseLabel":"المائدة: 8","question":"ما مناسبة إعادة التحذير من الشنآن في الآية الثامنة بعد وروده في الآية الثانية؟","answer":"في الآية الثانية نُهي عن أن يحملهم صد المشركين على الاعتداء، وفي الثامنة نُهي عن أن يحملهم البغض على ترك العدل في الشهادة والحكم؛ فتكرر الأصل لاختلاف ميدان تطبيقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص629–638.","url":""}]},{"id":"s5-94","number":94,"surah":5,"verses":[8],"verseLabel":"المائدة: 8","question":"ما سرّ التعبير بقوله تعالى: ﴿اعدلوا هو أقرب للتقوى﴾، دون: العدل هو التقوى؟","answer":"أعاد الأمر بالعدل بعد النهي عن الجور لينقلهم من مجرد الكف إلى الفعل الإيجابي، وجعل العدل أقرب إلى التقوى لأنه طريقها العملي ودليلها، لا أنه يستوعب حقيقتها كلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص629–638.","url":""}]},{"id":"s5-95","number":95,"surah":5,"verses":[8],"verseLabel":"المائدة: 8","question":"ما دلالة إظهار اسم الله في قوله تعالى: ﴿واتقوا الله إن الله خبير بما تعملون﴾؟","answer":"إظهار الاسم الجليل بدل الضمير يجدد التعظيم والمهابة، ويربط الأمر بالتقوى مباشرة بمن يعلم خفايا العمل ودوافع العدل والجور.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص636.","url":""}]},{"id":"s5-96","number":96,"surah":5,"verses":[8],"verseLabel":"المائدة: 8","question":"ما سرّ اختيار ﴿خبير بما تعملون﴾ في ختام آية العدل؟","answer":"الخبير هو العالم بدقائق الأمور وبواطنها، وهو الأنسب لعدل قد تحرفه مشاعر الشنآن الخفية؛ فالله يعلم ظاهر الحكم والدافع المستتر وراءه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص629–638.","url":""}]},{"id":"s5-97","number":97,"surah":5,"verses":[9],"verseLabel":"المائدة: 9","question":"ما دلالة تقديم المغفرة على الأجر العظيم في وعد المؤمنين؟","answer":"المغفرة تزيل تبعات الذنوب أولًا، ثم يأتي الأجر زيادةً وإكرامًا على العمل الصالح؛ فقدم تطهير العبد من الموانع قبل تحليته بالثواب.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص639–645.","url":""}]},{"id":"s5-98","number":98,"surah":5,"verses":[9],"verseLabel":"المائدة: 9","question":"ما دلالة تقديم ﴿لهم﴾ في قوله تعالى: ﴿لهم مغفرة وأجر عظيم﴾؟","answer":"تقديم الجار والمجرور للاختصاص والاهتمام بأصحاب الوعد؛ فالمغفرة والأجر ثابتان لهم في مقابلة أصحاب الجحيم في الآية التالية.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص642.","url":""}]},{"id":"s5-99","number":99,"surah":5,"verses":[9],"verseLabel":"المائدة: 9","question":"ما دلالة الجمع بين الإيمان والعمل الصالح في قوله تعالى: ﴿الذين آمنوا وعملوا الصالحات﴾؟","answer":"الإيمان أصل باطن يحدد الوجهة، والعمل الصالح ثمرته وبرهانه الظاهر؛ فجمعهما يمنع الاتكال على الدعوى المجردة أو على عمل منفصل عن الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص639–645.","url":""}]},{"id":"s5-100","number":100,"surah":5,"verses":[10],"verseLabel":"المائدة: 10","question":"ما دلالة الجمع بين الكفر والتكذيب في قوله تعالى: ﴿والذين كفروا وكذبوا بآياتنا﴾؟","answer":"الكفر يصف موقفهم العقدي العام، والتكذيب بآيات الله يبين صورته العملية بعد مجيء الدليل؛ فجمع فساد الاعتقاد والرد الصريح للحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص646–651.","url":""}]},{"id":"s5-101","number":101,"surah":5,"verses":[10],"verseLabel":"المائدة: 10","question":"ما دلالة تقديم الكفر على التكذيب؟","answer":"الكفر هو الأصل العقدي العام، والتكذيب بالآيات مظهره الصريح بعد قيام الدليل؛ فقدم الأصل ثم ذكر أثره العملي.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص649.","url":""}]},{"id":"s5-102","number":102,"surah":5,"verses":[10],"verseLabel":"المائدة: 10","question":"ما سرّ تسمية أهل النار ﴿أصحاب الجحيم﴾؟","answer":"الصحبة تدل على الملازمة وطول المكث، والجحيم النار الشديدة التأجج؛ فالتعبير لا يذكر مجرد دخول عابر بل مصاحبة دائمة للعذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص646–651.","url":""}]},{"id":"s5-103","number":103,"surah":5,"verses":[11],"verseLabel":"المائدة: 11","question":"ما سرّ تكرار الأمر بذكر نعمة الله في الآية 11 بعد وروده في الآية 7؟","answer":"في الآية 7 ذُكرت نعمة الهداية والميثاق، وهنا ذُكرت نعمة الحفظ من قوم هموا بالاعتداء؛ فتكرر الأمر لاختلاف النعمة وتجدد موجب الشكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص652–661.","url":""}]},{"id":"s5-104","number":104,"surah":5,"verses":[11],"verseLabel":"المائدة: 11","question":"ما الصورة في قوله تعالى: ﴿إذ هم قوم أن يبسطوا إليكم أيديهم﴾؟","answer":"بسط اليد كناية عن مدها بالأذى والقتل، فحوّل نية الاعتداء إلى مشهد أيدٍ تمتد نحو المؤمنين، ليظهر أثر نعمة كفها.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص652–661.","url":""}]},{"id":"s5-105","number":105,"surah":5,"verses":[11],"verseLabel":"المائدة: 11","question":"ما سرّ التعبير بقوله تعالى: ﴿فكف أيديهم عنكم﴾، دون: فمنعهم؟","answer":"الكف حبس اليد بعد توجهها إلى الفعل، ويقابل ﴿أن يبسطوا إليكم أيديهم﴾ مقابلة تصويرية؛ فظهر الاعتداء والحماية في حركتين متضادتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص652–661.","url":""}]},{"id":"s5-106","number":106,"surah":5,"verses":[11],"verseLabel":"المائدة: 11","question":"ما دلالة تقديم ﴿إليكم﴾ في قوله تعالى: ﴿أن يبسطوا إليكم أيديهم﴾؟","answer":"قُدم المتعلق لتوجيه العناية إلى المؤمنين الذين قصدهم الاعتداء وإلى خصوص النعمة الواقعة عليهم، ثم ذُكرت وسيلة الأذى وهي الأيدي.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص658.","url":""}]},{"id":"s5-107","number":107,"surah":5,"verses":[11],"verseLabel":"المائدة: 11","question":"ما دلالة إظهار اسم الله في قوله تعالى: ﴿واتقوا الله وعلى الله فليتوكل المؤمنون﴾؟","answer":"تكرار الاسم الجليل يجدد التعظيم ويجعل التقوى والتوكل متعلقين بالله تصريحًا؛ فهو الذي كف الأيدي، ومن ثم يستحق أن يُتقى ويُعتمد عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص660–661.","url":""}]},{"id":"s5-108","number":108,"surah":5,"verses":[11],"verseLabel":"المائدة: 11","question":"ما دلالة تقديم ﴿على الله﴾ في قوله تعالى: ﴿وعلى الله فليتوكل المؤمنون﴾؟","answer":"تقديم الجار والمجرور يفيد القصر: على الله وحده يعتمد المؤمنون، لا على قوتهم وأسبابهم، ولا سيما بعد تذكيرهم بحفظه لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص661.","url":""}]},{"id":"s5-109","number":109,"surah":5,"verses":[12],"verseLabel":"المائدة: 12","question":"ما مناسبة الانتقال من خطاب المؤمنين إلى الحديث عن ميثاق بني إسرائيل؟","answer":"بعد تذكير المؤمنين بميثاقهم انتقل إلى بني إسرائيل للعبرة من عاقبة نقض الميثاق؛ فصار الخبر السابق تحذيرًا للمخاطبين من تكرار الطريق نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص662–678.","url":""}]},{"id":"s5-110","number":110,"surah":5,"verses":[12],"verseLabel":"المائدة: 12","question":"ما سرّ التصريح بعدد النقباء في قوله تعالى: ﴿وبعثنا منهم اثني عشر نقيبًا﴾؟","answer":"النقيب من ينقب عن أحوال قومه ويتفقدها، والعدد يوافق أسباط بني إسرائيل حتى يكون لكل سبط ممثل تقوم به الحجة عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص662–678.","url":""}]},{"id":"s5-111","number":111,"surah":5,"verses":[12],"verseLabel":"المائدة: 12","question":"ما دلالة قوله تعالى بعد بعث النقباء: ﴿إني معكم﴾؟","answer":"هي معية نصرة وتأييد مشروطة بالوفاء بما بعدها من الصلاة والزكاة والإيمان بالرسل؛ فطمأنتهم إلى العون وربطته بالطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص662–678.","url":""}]},{"id":"s5-112","number":112,"surah":5,"verses":[12],"verseLabel":"المائدة: 12","question":"ما دلالة ترتيب شروط الميثاق: الصلاة، والزكاة، والإيمان بالرسل وتعزيرهم، والإقراض الحسن؟","answer":"بدأ بعبادة البدن، ثم حق المال، ثم التصديق بالرسل ونصرتهم، ثم البذل الزائد؛ فتدرج من أصول الطاعة اللازمة إلى النصرة والإنفاق المتطوع به.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص662–678.","url":""}]},{"id":"s5-113","number":113,"surah":5,"verses":[12],"verseLabel":"المائدة: 12","question":"ما سرّ تسمية الإنفاق في سبيل الله ﴿قرضًا حسنًا﴾ مع أن المال لله؟","answer":"سماه قرضًا تشريفًا للمنفق وتوكيدًا لضمان الوفاء والزيادة، و﴿حسنًا﴾ تقيده بالإخلاص وطيب المال ووضعه في موضعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص676.","url":""}]},{"id":"s5-114","number":114,"surah":5,"verses":[12],"verseLabel":"المائدة: 12","question":"ما دلالة تقديم تكفير السيئات على إدخال الجنات؟","answer":"تكفير السيئات يزيل أسباب العقوبة أولًا، ثم يأتي إدخال الجنات إكرامًا وثوابًا؛ فقدم التطهير من الموانع على الفوز بالنعيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص676.","url":""}]},{"id":"s5-115","number":115,"surah":5,"verses":[12],"verseLabel":"المائدة: 12","question":"ما الصورة في قوله تعالى: ﴿فقد ضل سواء السبيل﴾، وما دلالة ﴿سواء﴾؟","answer":"سواء السبيل وسطه ومستقيمه، فصور من كفر بعد الميثاق وقد انحرف عن أوضح موضع في الطريق، لا أنه أخطأ طرفًا خفيًا منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص662–678.","url":""}]},{"id":"s5-116","number":116,"surah":5,"verses":[13],"verseLabel":"المائدة: 13","question":"ما دلالة الباء و﴿ما﴾ في قوله تعالى: ﴿فبما نقضهم ميثاقهم لعناهم﴾؟","answer":"الباء للسببية، أي بسبب نقضهم، و﴿ما﴾ تؤكد هذا الربط؛ فالعقوبة لم تقع اعتباطًا، بل ترتبت على جريمتهم في نقض الميثاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص679–695.","url":""}]},{"id":"s5-117","number":117,"surah":5,"verses":[13],"verseLabel":"المائدة: 13","question":"ما الصورة في قوله تعالى: ﴿وجعلنا قلوبهم قاسية﴾؟","answer":"شبهت القلوب بما يبس وصلب فلا يقبل أثرًا؛ فكما لا ينفذ في الحجر شيء لم تنفذ الموعظة فيهم، وكانت القسوة جزاءً لنقضهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص679–695.","url":""}]},{"id":"s5-118","number":118,"surah":5,"verses":[13],"verseLabel":"المائدة: 13","question":"ما الفرق بين قوله تعالى: ﴿يحرفون الكلم عن مواضعه﴾، وقوله: ﴿من بعد مواضعه﴾؟","answer":"﴿عن مواضعه﴾ تعم إمالة الكلام عن لفظه أو معناه، أما ﴿من بعد مواضعه﴾ فتبرز أنهم عرفوا مواضعه الثابتة ثم نقلوه عنها؛ فالثانية أشد في تصوير التحريف عن علم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص693–694، وله عودة عند آية 41.","url":""}]},{"id":"s5-119","number":119,"surah":5,"verses":[13],"verseLabel":"المائدة: 13","question":"ما سرّ التعبير بقوله تعالى: ﴿ونسوا حظًا مما ذكروا به﴾، دون: نسوا ما ذكروا به؟","answer":"الحظ نصيب كان ينبغي أن ينتفعوا به من الوحي، و﴿من﴾ تدل على ضياع جانب عظيم منه؛ فليس المراد مجرد نسيان اللفظ بل ترك نصيب العمل والهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص679–695.","url":""}]},{"id":"s5-120","number":120,"surah":5,"verses":[13],"verseLabel":"المائدة: 13","question":"ما دلالة إفراد ﴿خائنة﴾ في قوله تعالى: ﴿ولا تزال تطلع على خائنة منهم﴾؟","answer":"﴿خائنة﴾ مصدر بمعنى الخيانة، أو فعلة خائنة وطائفة منها؛ فالإفراد يلحظ كل حادثة خيانة تتجدد منهم، وهو ما يلائم ﴿لا تزال تطلع﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص688–690.","url":""}]},{"id":"s5-121","number":121,"surah":5,"verses":[13],"verseLabel":"المائدة: 13","question":"ما مناسبة الأمر بالعفو والصفح بعد ذكر النقض والتحريف والخيانة؟","answer":"الأمر متعلق بما تقتضيه مصلحة الدعوة والعهد ممن لم يؤمر بقتاله؛ فالعفو ترك المؤاخذة، والصفح تجاوز أثرها، وهو إحسان يضبط رد الفعل ولا يقر الخيانة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص692–695.","url":""}]},{"id":"s5-122","number":122,"surah":5,"verses":[13],"verseLabel":"المائدة: 13","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿إن الله يحب المحسنين﴾؟","answer":"لما أمر بالعفو والصفح رفعهما من مجرد كف الانتقام إلى مقام الإحسان، ثم رغب فيهما بمحبة الله للمحسنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص679–695.","url":""}]},{"id":"s5-123","number":123,"surah":5,"verses":[14],"verseLabel":"المائدة: 14","question":"ما سرّ التعبير بقوله تعالى: ﴿ومن الذين قالوا إنا نصارى﴾، دون: ومن النصارى؟","answer":"نسبهم إلى دعواهم التي قالوها ولم يحققوا مقتضاها من نصرة الله والوفاء بميثاقه؛ ففي الموصول تعريض بالفارق بين الاسم المعلن والعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص696–709.","url":""}]},{"id":"s5-124","number":124,"surah":5,"verses":[14],"verseLabel":"المائدة: 14","question":"ما مناسبة جعل العداوة والبغضاء جزاءً لنسيانهم الميثاق؟","answer":"لما تركوا نصيبًا من الوحي الذي يجمعهم على الحق تفرقت أهواؤهم ومذاهبهم، فكان اختلاف القلوب والفرق جزاءً من جنس تركهم لعهد الوحدة والهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص696–709.","url":""}]},{"id":"s5-125","number":125,"surah":5,"verses":[14],"verseLabel":"المائدة: 14","question":"ما الفرق بين العداوة والبغضاء، وما دلالة الجمع بينهما؟","answer":"العداوة تظهر في القول والفعل والاعتداء، والبغضاء كراهية مستقرة في القلب؛ فجمع بين فساد الظاهر وفساد الباطن.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص696–709.","url":""}]},{"id":"s5-126","number":126,"surah":5,"verses":[14],"verseLabel":"المائدة: 14","question":"ما دلالة تقديم ﴿العداوة﴾ على ﴿البغضاء﴾؟","answer":"قدم ما يظهر من الخصومة ويشاهده الناس، ثم ذكر أصلها الباطن في القلوب؛ فاستوعب أثر الفرقة وسبب استمرارها.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص696–709.","url":""}]},{"id":"s5-127","number":127,"surah":5,"verses":[14],"verseLabel":"المائدة: 14","question":"ما دلالة تقييد العداوة والبغضاء بقوله تعالى: ﴿إلى يوم القيامة﴾؟","answer":"يجعل القيد الفرقة ممتدة ما داموا على أسبابها من نسيان الميثاق والتحريف، فلا تعد حادثة عابرة بل أثرًا متوارثًا إلى نهاية الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص696–709.","url":""}]},{"id":"s5-128","number":128,"surah":5,"verses":[14],"verseLabel":"المائدة: 14","question":"ما مناسبة قوله تعالى: ﴿وسوف ينبئهم الله بما كانوا يصنعون﴾، وما دلالة ﴿يصنعون﴾؟","answer":"﴿سوف﴾ وعيد بالجزاء الآتي، والإنباء إظهار لحقيقة ما أخفوه. والصنع عمل مقصود محكم التدبير، فناسب تحريفًا وفرقةً نشآ عن تعمد لا عن سهو.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص696–709.","url":""}]},{"id":"s5-129","number":129,"surah":5,"verses":[15],"verseLabel":"المائدة: 15","question":"ما دلالة تكرار نداء ﴿يا أهل الكتاب﴾ في السورة؟","answer":"يتجدد النداء عند انتقال الحجة إلى موضوع جديد، ويواجههم بوصف الكتاب الذي يلزمهم اتباع ما جاء مصدقًا له؛ فكل نداء استدعاء مستقل للرجوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص710–725.","url":""}]},{"id":"s5-130","number":130,"surah":5,"verses":[15],"verseLabel":"المائدة: 15","question":"ما سرّ بيان الرسول كثيرًا مما أخفوه من الكتاب والعفو عن كثير؟","answer":"بيّن ما تقوم به الحجة وتصلح به العقيدة والشريعة، وترك كشف ما لا تقتضيه الرسالة أو ما لا تتعلق به مصلحة البيان؛ فالعفو إعراض مقصود لا عجز.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص710–725.","url":""}]},{"id":"s5-131","number":131,"surah":5,"verses":[15],"verseLabel":"المائدة: 15","question":"ما سرّ التعبير عن ترك بيان بعض ما أخفوه بقوله تعالى: ﴿ويعفو عن كثير﴾؟","answer":"العفو أصله المحو والتجاوز؛ فصور ترك فضح كل مخفي تفضلًا وإعراضًا كريمًا، لا نقصًا في العلم أو القدرة على البيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص714–715.","url":""}]},{"id":"s5-132","number":132,"surah":5,"verses":[15],"verseLabel":"المائدة: 15","question":"ما دلالة الجمع بين ﴿نور﴾ و﴿كتاب مبين﴾؟","answer":"النور يكشف ظلمات الاعتقاد والحيرة، والكتاب يجمع الأحكام ويثبتها، و﴿مبين﴾ يدل على وضوحه وإظهاره للحق؛ فاجتمعت الهداية والمرجعية.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص710–725.","url":""}]},{"id":"s5-133","number":133,"surah":5,"verses":[16],"verseLabel":"المائدة: 16","question":"ما دلالة قوله تعالى: ﴿يهدي به الله﴾ بعد ذكر النور والكتاب؟","answer":"أظهر اسم الله ليقرر أن الكتاب سبب، أما واهب الهداية فهو الله؛ والضمير المفرد يعود إلى المذكور بوصفه وحيًا واحدًا أو إلى الكتاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص717.","url":""}]},{"id":"s5-134","number":134,"surah":5,"verses":[16],"verseLabel":"المائدة: 16","question":"ما سرّ جمع ﴿سبل السلام﴾ وإفراد ﴿صراط مستقيم﴾؟","answer":"سبل السلام متعددة بتعدد أعمال الخير ووسائل النجاة، لكنها تلتقي في صراط واحد هو دين الله المستقيم؛ فجمع الفروع وأفرد الأصل الجامع.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص710–725.","url":""}]},{"id":"s5-135","number":135,"surah":5,"verses":[16],"verseLabel":"المائدة: 16","question":"ما سرّ جمع الظلمات وإفراد النور في قوله تعالى: ﴿يخرجهم من الظلمات إلى النور﴾؟","answer":"طرق الباطل كثيرة متفرقة من كفر وجهل وهوى، أما الحق فواحد متناسق؛ فجمعت الظلمات لتعددها وأفرد النور لوحدته.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص720.","url":""}]},{"id":"s5-136","number":136,"surah":5,"verses":[16],"verseLabel":"المائدة: 16","question":"ما الفرق بين الهداية إلى ﴿سبل السلام﴾ والهداية إلى ﴿صراط مستقيم﴾؟","answer":"الأولى بالكتاب إلى وجوه السلام والنجاة في الاعتقاد والعمل، ثم يخرجهم من الظلمات، والثانية تثبيت وتوجيه إلى الطريق الجامع المستقيم الموصل إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص710–725.","url":""}]},{"id":"s5-137","number":137,"surah":5,"verses":[17],"verseLabel":"المائدة: 17","question":"ما سرّ تكرار الحكم: ﴿لقد كفر الذين قالوا إن الله هو المسيح ابن مريم﴾ في الآيتين 17 و72؟","answer":"جاء الأول ضمن إبطال الألوهية بدليل خضوع المسيح وأمه للخلق والهلاك، وعاد الثاني بعد تفصيل العهود لينقل شهادة المسيح نفسه بالأمر بعبادة الله والوعيد على الشرك؛ فاختلف مساق الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص726–737، ج9، ص437–447.","url":""}]},{"id":"s5-138","number":138,"surah":5,"verses":[17],"verseLabel":"المائدة: 17","question":"ما دلالة الاستفهام في قوله تعالى: ﴿فمن يملك من الله شيئًا﴾، وما علاقة الملك بالمنع؟","answer":"الاستفهام ينفي أن يملك أحد دفع شيء من قضاء الله؛ فإذا كان المسيح وأمه داخلين في سلطان الخلق والهلاك بطلت دعوى ألوهيته.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص729.","url":""}]},{"id":"s5-139","number":139,"surah":5,"verses":[17],"verseLabel":"المائدة: 17","question":"ما دلالة بناء الحجة على قوله تعالى: ﴿إن أراد أن يهلك المسيح ابن مريم وأمه ومن في الأرض جميعًا﴾؟","answer":"فرضت الآية تعلق القدرة الإلهية بالمسيح وأمه كسائر الخلق، ثم سألت عمن يستطيع المنع؛ فانتقل البرهان من إمكان الهلاك إلى نفي الألوهية عمن لا يملك دفعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص730.","url":""}]},{"id":"s5-140","number":140,"surah":5,"verses":[17],"verseLabel":"المائدة: 17","question":"ما دلالة التدرج في ذكر المسيح وأمه ومن في الأرض جميعًا؟","answer":"بدأ بالمسيح موضع الدعوى، ثم بأمه المرتبطة بمعجزته، ثم عم جميع أهل الأرض؛ فأدخلهما بالتدرج في جنس المخلوقين الخاضعين لملك الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص726–737.","url":""}]},{"id":"s5-141","number":141,"surah":5,"verses":[17],"verseLabel":"المائدة: 17","question":"ما مناسبة ختم الحجة بقوله تعالى: ﴿يخلق ما يشاء والله على كل شيء قدير﴾؟","answer":"خلق المسيح من غير أب صورة من المشيئة والقدرة لا دليل ألوهية؛ فالخاتمة ترد المعجزة إلى أصلها: الله يخلق على أي هيئة يشاء ولا يعجزه شيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص726–737.","url":""}]},{"id":"s5-142","number":142,"surah":5,"verses":[17],"verseLabel":"المائدة: 17","question":"ما سرّ زيادة ﴿لكم﴾ في قوله تعالى في الفتح: ﴿فمن يملك لكم من الله شيئًا﴾، وحذفها في المائدة؟","answer":"في الفتح الخطاب لجماعة يزعمون دفع الضر عن المخلفين، فذكرت ﴿لكم﴾ لتخصيص المنع بنفعهم. وفي المائدة الحجة عامة في المسيح وأمه والخلق، فنفي ملك أي شيء من الله أبلغ في العموم.","sources":[{"label":"موسوعة التفسير البلاغي، الموضع العكسي: ج56، ص401–408.","url":""}]},{"id":"s5-143","number":143,"surah":5,"verses":[18],"verseLabel":"المائدة: 18","question":"ما دلالة حكاية قول اليهود والنصارى: ﴿نحن أبناء الله وأحباؤه﴾ ثم الرد عليه؟","answer":"حكى دعواهم نفسها ثم ألزمهم بالعقوبة الواقعة: لو كانت البنوة والمحبة امتيازًا يعصمهم لما عذبوا بذنوبهم، ثم ردهم إلى حقيقتهم: بشر من خلقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص738–748.","url":""}]},{"id":"s5-144","number":144,"surah":5,"verses":[18],"verseLabel":"المائدة: 18","question":"ما دلالة الاستفهام في قوله تعالى: ﴿قل فلم يعذبكم بذنوبكم﴾؟","answer":"استفهام إلزامي إنكاري يجعل واقع العقوبة حجة على بطلان دعوى المحبة التي تعصمهم؛ فوجود التعذيب يناقض ما توهموه من خصوصية مطلقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص738–748.","url":""}]},{"id":"s5-145","number":145,"surah":5,"verses":[18],"verseLabel":"المائدة: 18","question":"ما سرّ التعبير بقوله تعالى: ﴿بل أنتم بشر ممن خلق﴾، دون: بل أنتم عباده؟","answer":"لفظ البشر يسويهم بغيرهم في الطبيعة المخلوقة التي يدعون التميز عليها، و﴿ممن خلق﴾ تدخلهم صراحة في عموم الخلق الخاضع لمشيئته.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص738–748.","url":""}]},{"id":"s5-146","number":146,"surah":5,"verses":[18],"verseLabel":"المائدة: 18","question":"ما دلالة الجمع بين ﴿يغفر لمن يشاء ويعذب من يشاء﴾ بعد نفي دعوى البنوة والمحبة؟","answer":"الجمع يقرر أنهم كسائر العباد تحت حكم الله وعدله: لا نسب مزعوم يوجب المغفرة ولا لقب يمنع العقوبة، وإنما المرجع إلى مشيئته وحكمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص738–748.","url":""}]},{"id":"s5-147","number":147,"surah":5,"verses":[18],"verseLabel":"المائدة: 18","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿وإليه المصير﴾؟","answer":"إذا كان الملك له والمغفرة والعذاب بيده فمرجع الجميع إليه للحساب؛ وبذلك تسقط دعوى امتياز لا يمتحن يوم المصير.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص746–748.","url":""}]},{"id":"s5-148","number":148,"surah":5,"verses":[19],"verseLabel":"المائدة: 19","question":"ما الصورة في قوله تعالى: ﴿على فترة من الرسل﴾؟","answer":"الفترة سكون وانقطاع بعد نشاط، فصورت المدة بين الرسالات زمنًا فتر فيه توالي الرسل وخفيت معالم من الوحي، فجاء الرسول ﷺ يجدد البيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص749–760.","url":""}]},{"id":"s5-149","number":149,"surah":5,"verses":[19],"verseLabel":"المائدة: 19","question":"ما دلالة تكرار ﴿يبين لكم﴾ بعد ورودها في الآية 15؟","answer":"الأولى تتعلق ببيان ما أخفاه أهل الكتاب من كتابهم، والثانية ببيان الرسول بعد فترة من الرسل حتى تنقطع حجة غياب البشير والنذير؛ فاختلف متعلق البيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص749–760.","url":""}]},{"id":"s5-150","number":150,"surah":5,"verses":[19],"verseLabel":"المائدة: 19","question":"ما دلالة تقديم البشير على النذير في العذر المحكي والجواب عنه؟","answer":"قدمت البشارة لأن الرحمة وفتح باب القبول أصل الدعوة، ثم جاء الإنذار لمن أعرض؛ وردت الآية بألفاظ عذرهم نفسها لتبطل قولهم: ﴿فقد جاءكم بشير ونذير﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص754–757.","url":""}]},{"id":"s5-151","number":151,"surah":5,"verses":[19],"verseLabel":"المائدة: 19","question":"ما دلالة قوله تعالى: ﴿أن تقولوا ما جاءنا من بشير ولا نذير﴾؟","answer":"﴿أن تقولوا﴾ تعليل للبيان، أي كراهة أن تحتجوا بهذا القول، و﴿من﴾ بعد النفي تستغرق أي بشير أو نذير؛ فجاء الرسول قاطعًا للعذر كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص749–760.","url":""}]},{"id":"s5-152","number":152,"surah":5,"verses":[19],"verseLabel":"المائدة: 19","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿والله على كل شيء قدير﴾؟","answer":"قدرته ظهرت في إرسال الرسول بعد الفترة وإحياء معالم الوحي، وهي تضمن قدرته على إنفاذ البشارة والإنذار والجزاء الذي بلغه الرسول.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص758–760.","url":""}]},{"id":"s5-153","number":153,"surah":5,"verses":[20],"verseLabel":"المائدة: 20","question":"ما مناسبة بدء موسى خطابه بقوله: ﴿يا قوم اذكروا نعمة الله عليكم﴾ قبل الأمر بدخول الأرض؟","answer":"استثار ذكر النعم الثقة بالطاعة والشجاعة للدخول؛ فمن جعل فيهم الأنبياء وحررهم وملكهم قادر على نصرهم إذا امتثلوا.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص761–772.","url":""}]},{"id":"s5-154","number":154,"surah":5,"verses":[20],"verseLabel":"المائدة: 20","question":"ما سرّ التعبير بـ﴿فيكم أنبياء﴾، ثم ﴿وجعلكم ملوكًا﴾؟","answer":"الأنبياء بعض منهم قائمون في جماعتهم، فناسب ﴿فيكم﴾، أما وصف الملوك أو نعمة الحرية والملك فتعلقت بالجماعة المخاطبة، فجيء بـ﴿جعلكم﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص761–772.","url":""}]},{"id":"s5-155","number":155,"surah":5,"verses":[20],"verseLabel":"المائدة: 20","question":"كيف يُفهم قوله تعالى: ﴿وجعلكم ملوكًا﴾ مع أنهم لم يكونوا جميعًا أصحاب عروش؟","answer":"الملك هنا سعة الاستقلال بعد العبودية وامتلاك المسكن والأهل والخادم، أو جعل الملوك فيهم؛ فلا يلزم أن يكون كل فرد صاحب تاج وسلطان.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص764.","url":""}]},{"id":"s5-156","number":156,"surah":5,"verses":[20],"verseLabel":"المائدة: 20","question":"كيف يُفهم قوله تعالى: ﴿وآتاكم ما لم يؤت أحدًا من العالمين﴾ مع إيتاء أمم أخرى نعمًا عظيمة؟","answer":"المراد عالمو زمانهم، أو اجتماع نعم مخصوصة لهم كالأنبياء والنجاة والملك والمن والسلوى؛ فلا يقتضي تفضيل كل فرد منهم على جميع الأمم في كل زمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص761–772.","url":""}]},{"id":"s5-157","number":157,"surah":5,"verses":[20],"verseLabel":"المائدة: 20","question":"ما سرّ إثبات ﴿يا قوم﴾ في خطاب موسى هنا، وحذفها من الخطاب المشابه في سورة إبراهيم؟","answer":"في المائدة حكي كلام موسى مباشرة فكرر النداء استمالةً لقومه قبل التكليف الشاق، أما في إبراهيم فتقدم ﴿إذ قال موسى لقومه﴾ فدل ذكر القوم على المخاطبين واستغني عن النداء.","sources":[{"label":"موسوعة التفسير البلاغي، الموضع العكسي: ج24، ص550–551.","url":""}]},{"id":"s5-158","number":158,"surah":5,"verses":[21],"verseLabel":"المائدة: 21","question":"ما دلالة وصف الأرض بقوله تعالى: ﴿المقدسة﴾؟","answer":"المقدسة المطهرة المباركة، فوصفها يرفع قدرها ويرغب في دخولها، ويجعل النكوص عنها بعد الأمر أشد قبحًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص761–772.","url":""}]},{"id":"s5-159","number":159,"surah":5,"verses":[21],"verseLabel":"المائدة: 21","question":"كيف يُفهم قوله تعالى: ﴿التي كتب الله لكم﴾ مع عقوبتهم بالتيه ومنعهم منها؟","answer":"الكتابة وعد وقضاء مرتبط بالطاعة ودخولهم مأمورين، لا تمليك أبدي بلا تكليف؛ فلما نكل ذلك الجيل حرم منها مدة التيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص761–772.","url":""}]},{"id":"s5-160","number":160,"surah":5,"verses":[21],"verseLabel":"المائدة: 21","question":"ما الصورة في قوله تعالى: ﴿ولا ترتدوا على أدباركم﴾؟","answer":"صور العصيان برجوع المرء إلى الوراء على عقبيه بعد أن توجه نحو الغاية؛ فهو تراجع حسي يجسد النكوص عن أمر الله بعد وضوح الطريق.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص761–772.","url":""}]},{"id":"s5-161","number":161,"surah":5,"verses":[21],"verseLabel":"المائدة: 21","question":"ما سرّ التعبير بقوله تعالى: ﴿فتنقلبوا خاسرين﴾، دون: فتكونوا خاسرين؟","answer":"الانقلاب تحول من حال إلى حال؛ فهم على أبواب نصر ونعمة، فإن ارتدوا رجعوا من فرصة الفوز إلى حقيقة الخسارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص761–772.","url":""}]},{"id":"s5-162","number":162,"surah":5,"verses":[21],"verseLabel":"المائدة: 21","question":"ما الفرق بين الأمر في المائدة: ﴿ادخلوا الأرض المقدسة﴾، وقوله في الأعراف: ﴿اسكنوا هذه القرية﴾؟","answer":"في المائدة كان المطلوب اقتحام الأرض قبل استقرارهم فيها فناسب ﴿ادخلوا﴾، وفي الأعراف حكي الإذن بعد تحقق الوصول والغلبة فناسب ﴿اسكنوا﴾.","sources":[{"label":"موسوعة التفسير البلاغي، الموضع العكسي: ج29، ص256 فما بعدها.","url":""}]},{"id":"s5-163","number":163,"surah":5,"verses":[22],"verseLabel":"المائدة: 22","question":"ما دلالة وصف القوم بقوله تعالى: ﴿جبارين﴾ بدل تفصيل قوتهم وعددهم؟","answer":"الجبار شديد القوة والبطش المتعالي على غيره، فجمع الوصف ما أرادوا تضخيمه من القوة والرهبة، واتخذوه ذريعة لرفض الأمر.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص773–776.","url":""}]},{"id":"s5-164","number":164,"surah":5,"verses":[22],"verseLabel":"المائدة: 22","question":"ما دلالة تكرار رفضهم الدخول ثم تعليقه على خروج الجبارين؟","answer":"أكدوا أولًا امتناعهم ما دام الجبارون فيها، ثم أعلنوا استعدادًا مشروطًا بزوال الخطر كله؛ فالتكرار يكشف أنهم لا يريدون جهادًا بل دخولًا بلا مقاومة.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص773–776.","url":""}]},{"id":"s5-165","number":165,"surah":5,"verses":[22],"verseLabel":"المائدة: 22","question":"ما دلالة قولهم: ﴿فإن يخرجوا منها فإنا داخلون﴾ بالجملة الاسمية والتوكيد؟","answer":"ثبتوا دخولهم بـ﴿إن﴾ والجملة الاسمية، لكن بعد شرط يفرغه من الشجاعة: لا يدخلون إلا إذا خرج العدو؛ فالتوكيد يبرز مفارقة ثبات القول وضعف الفعل.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص773–776.","url":""}]},{"id":"s5-166","number":166,"surah":5,"verses":[23],"verseLabel":"المائدة: 23","question":"ما سرّ تعريف الرجلين بصفتهما: ﴿من الذين يخافون أنعم الله عليهما﴾، دون ذكر اسميهما؟","answer":"المقصود قدوتهما لا شخصاهما؛ فعرّفهما بالخوف من الله والنعمة التي ثبتتهما، ليبين أن الشجاعة ثمرة تقوى وفضل.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص777–782.","url":""}]},{"id":"s5-167","number":167,"surah":5,"verses":[23],"verseLabel":"المائدة: 23","question":"ما دلالة تقديم ﴿عليهم﴾ في قوله تعالى: ﴿ادخلوا عليهم الباب﴾؟","answer":"وجه التقديم النظر إلى مباغتة الجبارين ومواجهتهم قبل ذكر مكان الدخول؛ فالعناية بالفعل الواقع عليهم الذي يكسر هيبتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص780.","url":""}]},{"id":"s5-168","number":168,"surah":5,"verses":[23],"verseLabel":"المائدة: 23","question":"ما دلالة الجزم بالغلبة في قوله تعالى: ﴿فإذا دخلتموه فإنكم غالبون﴾؟","answer":"بنيا الجزم على وعد الله ومعرفتهما بحال العدو: متى امتثلوا واقتحموا الباب انهارت رهبتهم وحضر نصر الله؛ فجاءت ﴿إن﴾ والجملة الاسمية للتثبيت.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص777–782.","url":""}]},{"id":"s5-169","number":169,"surah":5,"verses":[23],"verseLabel":"المائدة: 23","question":"ما دلالة ختم كلام الرجلين بقوله تعالى: ﴿وعلى الله فتوكلوا إن كنتم مؤمنين﴾؟","answer":"قدما ﴿على الله﴾ لقصر الاعتماد عليه، وجعلا التوكل مقتضى الإيمان؛ فالمشكلة لم تكن نقص الأسباب فقط، بل ضعف الثقة بوعد الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص777–782.","url":""}]},{"id":"s5-170","number":170,"surah":5,"verses":[24],"verseLabel":"المائدة: 24","question":"ما الذي تكشفه صياغة قولهم: ﴿فاذهب أنت وربك فقاتلا إنا هاهنا قاعدون﴾؟","answer":"أكدوا الضميرين ليلقوا العبء على موسى وربه ويتنصلوا من أمر الجماعة بالدخول، ثم قابلوا القتال بقعودهم؛ ففضح التركيب غاية التمرد وسوء الأدب.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص783–790.","url":""}]},{"id":"s5-171","number":171,"surah":5,"verses":[24],"verseLabel":"المائدة: 24","question":"ما دلالة الجمع بين ﴿أبدًا﴾ و﴿ما داموا فيها﴾؟","answer":"﴿أبدًا﴾ تؤكد أنهم لن يدخلوا في أي وقت من أوقات بقاء الجبارين، و﴿ما داموا فيها﴾ يبين الحد الذي علقوا عليه امتناعهم؛ فالأبدية مقيدة بمدة وجودهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص786.","url":""}]},{"id":"s5-172","number":172,"surah":5,"verses":[24],"verseLabel":"المائدة: 24","question":"ما الصورة في قولهم: ﴿إنا هاهنا قاعدون﴾، دون: لن نقاتل؟","answer":"رسموا أنفسهم ثابتين في مكانهم قعودًا في مقابل موسى وأخيه المأمورين بالذهاب والقتال؛ فالصورة أصرح في التنصل والعناد من مجرد نفي القتال.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص789.","url":""}]},{"id":"s5-173","number":173,"surah":5,"verses":[25],"verseLabel":"المائدة: 25","question":"كيف يُفهم قول موسى: ﴿إني لا أملك إلا نفسي وأخي﴾ مع رسالته في قومه؟","answer":"الملك هنا القدرة على حمل الغير على الامتثال، لا مقام الرسالة؛ فلما أعلن القوم العصيان لم يبق ممن يضمن طاعته إلا نفسه وأخوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص791.","url":""}]},{"id":"s5-174","number":174,"surah":5,"verses":[25],"verseLabel":"المائدة: 25","question":"ما سرّ حذف حرف النداء في قوله تعالى: ﴿رب إني لا أملك إلا نفسي وأخي﴾؟","answer":"حذف حرف النداء يشعر بقرب المناجاة وشدة الالتجاء، ويجعل الدعاء مباشرًا سريعًا في لحظة انقطاع الأسباب.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص792.","url":""}]},{"id":"s5-175","number":175,"surah":5,"verses":[25],"verseLabel":"المائدة: 25","question":"ما سرّ اختيار ﴿فافرق بيننا وبين القوم الفاسقين﴾، دون: فاحكم أو فأهلكهم؟","answer":"الفرق طلب تمييز المؤمن المطيع من الخارج عن الطاعة في الحكم والمصير، وهو أعم وألطف من تعيين الهلاك؛ فقد سأل ألا يؤاخذ مع الفاسقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج8، ص791 فما بعدها.","url":""}]},{"id":"s5-176","number":176,"surah":5,"verses":[26],"verseLabel":"المائدة: 26","question":"كيف وُصفت الأرض بأنها ﴿محرمة عليهم﴾ مع تحديد التحريم بأربعين سنة؟","answer":"التحريم منع شرعي وقد يكون مؤقتًا أو مؤبدًا؛ وهنا بينت مدة المنع بعد الخبر، فلا تعارض بين وصفها بالمحرمة وتوقيت العقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص10–17.","url":""}]},{"id":"s5-177","number":177,"surah":5,"verses":[26],"verseLabel":"المائدة: 26","question":"ما دلالة تقديم ﴿محرمة عليهم﴾ على مدة ﴿أربعين سنة﴾؟","answer":"قدم الحكم الذي فاجأهم وهو الحرمان من الأرض موضع الوعد، ثم بين مدة العقوبة؛ فوقع أصل الجزاء في النفس قبل تحديد زمنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص10–17.","url":""}]},{"id":"s5-178","number":178,"surah":5,"verses":[26],"verseLabel":"المائدة: 26","question":"ما الصورة في قوله تعالى: ﴿يتيهون في الأرض﴾؟","answer":"التيه ضلال حسي في الطريق وافق تيههم المعنوي عن أمر الله؛ فصار الجزاء الخارجي صورة لما استقر في نفوسهم من حيرة وعصيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص10–17.","url":""}]},{"id":"s5-179","number":179,"surah":5,"verses":[26],"verseLabel":"المائدة: 26","question":"ما مناسبة قوله تعالى لموسى: ﴿فلا تأس على القوم الفاسقين﴾؟","answer":"نهاه عن شدة الحزن عليهم لأن الحرمان نتيجة فسقهم واختيارهم، وفي وصفهم بالفاسقين تعليل لاستحقاق العقوبة وتسلية للنبي من تبعتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص10–17.","url":""}]},{"id":"s5-180","number":180,"surah":5,"verses":[27],"verseLabel":"المائدة: 27","question":"ما سرّ التعبير بقوله تعالى: ﴿واتل عليهم نبأ ابني آدم بالحق﴾، دون: قصة ابني آدم؟","answer":"النبأ خبر عظيم ذو أثر، وتقييده بالحق ينفي ما لحق القصة من تحريف؛ فالمقصود حقيقة معتبرة في الحسد والقتل لا مجرد حكاية.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص18–24.","url":""}]},{"id":"s5-181","number":181,"surah":5,"verses":[27],"verseLabel":"المائدة: 27","question":"ما سرّ إبهام اسمي ابني آدم؟","answer":"لأن العبرة بموقفي القاتل والمقتول لا بتعيين اسميهما، فحذفهما يجرد القصة من الفضول ويجعل نموذج الحسد والعدوان صالحًا لكل زمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص18–24.","url":""}]},{"id":"s5-182","number":182,"surah":5,"verses":[27],"verseLabel":"المائدة: 27","question":"ما سرّ بناء قوله تعالى: ﴿فتقبل من أحدهما ولم يتقبل من الآخر﴾ للمجهول؟","answer":"وجه البناء العناية إلى وقوع القبول وظهور أثره لا إلى كيفيته، ثم صرح الفاعل في جواب الأخ: ﴿إنما يتقبل الله من المتقين﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص18–24.","url":""}]},{"id":"s5-183","number":183,"surah":5,"verses":[27],"verseLabel":"المائدة: 27","question":"ما دلالة جواب المهدد بقوله تعالى: ﴿إنما يتقبل الله من المتقين﴾ بدل الدفاع عن نفسه؟","answer":"رد سبب رفض قربان أخيه إلى تقواه لا إلى منافسة بينهما؛ والقصر يقرر أن طريق القبول إصلاح النفس، فيحول التهديد إلى موعظة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص18–24.","url":""}]},{"id":"s5-184","number":184,"surah":5,"verses":[28],"verseLabel":"المائدة: 28","question":"ما دلالة تفصيل الشرط والجواب في قوله تعالى: ﴿لئن بسطت إلي يدك لتقتلني ما أنا بباسط يدي إليك لأقتلك﴾؟","answer":"قابل بسط اليد ببسط اليد والقتل بالقتل ليظهر أن امتناعه قرار واع مع قيام الاعتداء، لا عجز مبهم عن الرد؛ فالتفصيل يجسم ضبط النفس.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص25–32.","url":""}]},{"id":"s5-185","number":185,"surah":5,"verses":[28],"verseLabel":"المائدة: 28","question":"ما الصورة في التعبير عن القتل ببسط اليد؟","answer":"بسط اليد كناية عن الشروع في البطش وإيصال الأذى، فاستحضر لحظة الحركة نحو الجريمة بدل ذكر نتيجتها وحدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص25–32.","url":""}]},{"id":"s5-186","number":186,"surah":5,"verses":[28],"verseLabel":"المائدة: 28","question":"ما دلالة التوكيد في قوله تعالى: ﴿ما أنا بباسط يدي إليك﴾، دون: لا أبسط؟","answer":"الجملة الاسمية ونفي الوصف والباء الزائدة في الخبر تؤكد ثبات امتناعه، كأنه ينفي أن يكون البسط صفةً له لا مجرد فعل مؤقت.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص25–32.","url":""}]},{"id":"s5-187","number":187,"surah":5,"verses":[28],"verseLabel":"المائدة: 28","question":"ما دلالة تعليل امتناعه بقوله تعالى: ﴿إني أخاف الله رب العالمين﴾؟","answer":"بيّن أن ترك المقابلة المحرمة ناشئ من خوف الله لا من الجبن، ووصفه برب العالمين يذكر القاتل بأنه تحت ربوبية من يحاسب الخلق جميعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص25–32.","url":""}]},{"id":"s5-188","number":188,"surah":5,"verses":[29],"verseLabel":"المائدة: 29","question":"كيف يُفهم قوله تعالى: ﴿إني أريد أن تبوء بإثمي وإثمك﴾؛ أيريد لأخيه الإثم؟","answer":"ليست إرادة محبة للمعصية، بل اختيار لأحد مآلين فرضهما المعتدي: إن أصررت على قتلي فإني لا أقتلك، فتتحمل إثم قتلي مع إثمك السابق، بدل أن أتحمل إثم قتلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص33–41.","url":""}]},{"id":"s5-189","number":189,"surah":5,"verses":[29],"verseLabel":"المائدة: 29","question":"ما دلالة تقديم ﴿بإثمي﴾ على ﴿وإثمك﴾؟","answer":"قدم الإثم الناشئ مباشرة من قتله لأخيه لأنه موضوع التهديد الحاضر، ثم ضم إليه إثمه السابق؛ فاجتمع عليه الجديد والقديم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص33–41.","url":""}]},{"id":"s5-190","number":190,"surah":5,"verses":[29],"verseLabel":"المائدة: 29","question":"ما سرّ التعبير بقوله تعالى: ﴿فتكون من أصحاب النار﴾، دون: فتدخل النار؟","answer":"الصحبة تدل على الملازمة والاستقرار، فتوعده بما وراء مجرد الدخول: أن يصير من الجماعة الملازمة للنار بسبب ظلمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص33–41.","url":""}]},{"id":"s5-191","number":191,"surah":5,"verses":[29],"verseLabel":"المائدة: 29","question":"ما دلالة قوله تعالى: ﴿وذلك جزاء الظالمين﴾، دون: القاتلين؟","answer":"الظلم هو الأصل الأعم الذي يدخل فيه القتل والحسد والعدوان، فتجاوزت الخاتمة الحادثة إلى قاعدة جزاء كل من يضع الحق في غير موضعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص33–41.","url":""}]},{"id":"s5-192","number":192,"surah":5,"verses":[30],"verseLabel":"المائدة: 30","question":"ما الصورة في قوله تعالى: ﴿فطوعت له نفسه قتل أخيه﴾؟","answer":"صورت النفس كأنها روضت الجريمة الشاقة وزينتها حتى صارت سهلة طيعة؛ فالفعل يكشف تدرجًا داخليًا سبق القتل لا اندفاعًا لحظيًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص42–49.","url":""}]},{"id":"s5-193","number":193,"surah":5,"verses":[30],"verseLabel":"المائدة: 30","question":"ما سرّ إظهار الأخوة في قوله تعالى: ﴿قتل أخيه﴾، دون: قتله؟","answer":"إظهار ﴿أخيه﴾ يجدد رابطة القرابة التي كان ينبغي أن تمنع الجريمة، فيزيد القتل فظاعة ويكشف مقدار ما غلب الحسد الفطرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص42–49.","url":""}]},{"id":"s5-194","number":194,"surah":5,"verses":[30],"verseLabel":"المائدة: 30","question":"ما دلالة التعقيب السريع في قوله تعالى: ﴿فقتله فأصبح من الخاسرين﴾؟","answer":"الفاء تجعل الخسارة أثرًا مباشرًا للقتل بلا مهلة؛ فما إن وقعت الجريمة حتى انقلبت أمنيته في التفوق إلى خسارة الدين والأخ والطمأنينة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص42–49.","url":""}]},{"id":"s5-195","number":195,"surah":5,"verses":[31],"verseLabel":"المائدة: 31","question":"ما دلالة بعث غراب ليعلم ابن آدم مواراة أخيه؟","answer":"في تعليم الحيوان له إذلال للقاتل وكشف لعجزه بعد جرأته على الدم؛ فصار الغراب أهدى منه إلى حرمة الجسد وستر الميت.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص50–60.","url":""}]},{"id":"s5-196","number":196,"surah":5,"verses":[31],"verseLabel":"المائدة: 31","question":"ما سرّ التعبير بقوله تعالى: ﴿يبحث في الأرض ليريه كيف يواري سوأة أخيه﴾، دون: يحفر قبرًا؟","answer":"البحث تقليب التراب وإثارته، فاستحضرت الآية حركة الغراب التي علمت القاتل المواراة، لا النتيجة الجامدة وحدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص50–60.","url":""}]},{"id":"s5-197","number":197,"surah":5,"verses":[31],"verseLabel":"المائدة: 31","question":"ما سرّ تسمية جثة أخيه ﴿سوأة أخيه﴾؟","answer":"السوأة ما يسوء ظهوره ويجب ستره، فصار جسد المقتول بعد تغيره مشهدًا يفضح الجريمة ويستدعي المواراة؛ وفي إضافة الأخ تجديد للتقريع.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص50–60.","url":""}]},{"id":"s5-198","number":198,"surah":5,"verses":[31],"verseLabel":"المائدة: 31","question":"ما دلالة قوله تعالى: ﴿يا ويلتى أعجزت أن أكون مثل هذا الغراب﴾؟","answer":"نداء الويل إعلان لحلول الهلاك والندامة، والاستفهام توبيخ للنفس؛ إذ رأى نفسه أعجز من غراب عن أبسط واجب نحو أخيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص50–60.","url":""}]},{"id":"s5-199","number":199,"surah":5,"verses":[31],"verseLabel":"المائدة: 31","question":"ما الفرق بين قوله تعالى: ﴿فأصبح من الخاسرين﴾ و﴿فأصبح من النادمين﴾؟","answer":"الخسارة حكم على مآل الجريمة عقب وقوعها، والندم حالة نفسية ظهرت حين عجز أمام الجسد وتعلم من الغراب؛ فانتقل من النتيجة الموضوعية إلى إحساسه المتأخر بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص50–60.","url":""}]},{"id":"s5-200","number":200,"surah":5,"verses":[32],"verseLabel":"المائدة: 32","question":"إلى ماذا يشير قوله تعالى: ﴿من أجل ذلك﴾ في افتتاح حكم حرمة الدماء؟","answer":"يشير إلى جريمة قتل أحد ابني آدم أخاه وما كشفت عنه من سرعة انتشار العدوان؛ فمن أجل هذا النموذج وآثاره كتب على بني إسرائيل تعظيم حرمة النفس.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص61–74.","url":""}]},{"id":"s5-201","number":201,"surah":5,"verses":[32],"verseLabel":"المائدة: 32","question":"ما سرّ تخصيص بني إسرائيل في قوله تعالى: ﴿كتبنا على بني إسرائيل﴾ مع أن حرمة القتل عامة؟","answer":"جاء هذا التشريع عقب قصة ابني آدم؛ لما كشفت عنه الجريمة من خطر العدوان في البشر، وخصّ بني إسرائيل بالذكر لأن الحكم كُتب عليهم في شريعتهم ولِما عُرف في تاريخهم من التهاون بالدماء، أما حرمة النفس فليست مقصورة عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص61–74.","url":""}]},{"id":"s5-202","number":202,"surah":5,"verses":[32],"verseLabel":"المائدة: 32","question":"ما سرّ ترتيب الاستثناءين في قوله تعالى: ﴿بغير نفس أو فساد في الأرض﴾؟","answer":"بدأ بالنفس لأن القصاص أظهر أسباب القتل المشروع وأشدها اتصالًا بالجريمة المذكورة، ثم عطف فساد الأرض ليشمل الجرائم العامة التي يترتب عليها استحقاق العقوبة؛ فانتقل من الاعتداء على فرد إلى الإفساد الذي يهدد المجتمع.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص61–74.","url":""}]},{"id":"s5-203","number":203,"surah":5,"verses":[32],"verseLabel":"المائدة: 32","question":"ما دلالة تشبيه قتل نفس واحدة بقتل الناس جميعًا، وإحيائها بإحياء الناس جميعًا؟","answer":"من استحل دمًا معصومًا فقد انتهك أصل حرمة الحياة الذي تقوم به سلامة الناس جميعًا، فكأنه اعتدى على الجميع؛ ومن صان نفسًا من الهلاك فقد صان ذلك الأصل العام، فكأنما أحيا الناس جميعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص61–74.","url":""}]},{"id":"s5-204","number":204,"surah":5,"verses":[32],"verseLabel":"المائدة: 32","question":"ما سرّ تقييد القتل بقوله تعالى: ﴿بغير نفس أو فساد في الأرض﴾، وعدم ذكر قيد مماثل في الإحياء؟","answer":"احتاج القتل إلى القيد لأن منه ما يكون بحق كالقصاص وعقوبة الإفساد، أما إنقاذ النفس المعصومة من الهلاك فخير في نفسه، فلم يحتج في هذا السياق إلى استثناء مقابل.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص61–74.","url":""}]},{"id":"s5-205","number":205,"surah":5,"verses":[32],"verseLabel":"المائدة: 32","question":"ما دلالة المؤكدات في قوله تعالى: ﴿ثم إن كثيرًا منهم بعد ذلك في الأرض لمسرفون﴾؟","answer":"تراكمت ﴿ثم﴾ و﴿إن﴾ ولفظ ﴿كثيرًا﴾ واللام لتأكيد غرابة استمرار كثير منهم في تجاوز الحدود بعد مجيء الرسل بالبينات وتشديد حرمة الدماء، ولفظ ﴿كثيرًا﴾ يحفظ الحكم من تعميمه على الجميع.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص61–74.","url":""}]},{"id":"s5-206","number":206,"surah":5,"verses":[33],"verseLabel":"المائدة: 33","question":"ما دلالة وصف المفسدين بأنهم ﴿يحاربون الله ورسوله﴾؟","answer":"لأن عدوانهم المسلح على الناس وأمن الطريق تمرد على حكم الله وسلطان رسوله، فصُوّر إفسادهم محاربةً لله ورسوله تغليظًا لجريمتهم، لا بمعنى إمكان محاربة الله حقيقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص75–84.","url":""}]},{"id":"s5-207","number":207,"surah":5,"verses":[33],"verseLabel":"المائدة: 33","question":"ما سرّ التعبير بقوله تعالى: ﴿ويسعون في الأرض فسادًا﴾ بدل: يفسدون في الأرض؟","answer":"السعي يصوّر القصد والحركة المتكررة وبذل الجهد في نشر الفساد، والمضارع يستحضر تجدد هذا المسلك واستمراره؛ فهو أبلغ من الدلالة على مجرد وقوع الفساد مرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص75–84؛ وبوابة البيان القرآني، «دلالة الفعل المضارع يسعون في الآية 33».","url":""}]},{"id":"s5-208","number":208,"surah":5,"verses":[33],"verseLabel":"المائدة: 33","question":"ما سرّ تنويع عقوبات الحرابة بين القتل والصلب والقطع والنفي؟","answer":"يناسب هذا التنويع اختلاف صور الحرابة ودرجات جنايتها؛ فالجزاء يغلظ بقدر القتل وأخذ المال وإخافة الطريق، فتتحقق المماثلة والردع، وتفصّل أحكام تطبيق ذلك كتب الفقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص75–84.","url":""}]},{"id":"s5-209","number":209,"surah":5,"verses":[33],"verseLabel":"المائدة: 33","question":"ما دلالة قوله تعالى: ﴿تُقطع أيديهم وأرجلهم من خلاف﴾؟","answer":"﴿من خلاف﴾ أي من جهتين متقابلتين، فتقطع اليد من جانب والرجل من الجانب الآخر؛ كاليمنى مع اليسرى. وفي ذلك عقوبة ظاهرة تعطل آلة العدوان وتحقق النكال.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص75–84.","url":""}]},{"id":"s5-210","number":210,"surah":5,"verses":[33],"verseLabel":"المائدة: 33","question":"ما دلالة الجمع بين ﴿خزي في الدنيا﴾ و﴿عذاب عظيم في الآخرة﴾ في جزاء المحاربين؟","answer":"الخزي هو ما يلحقهم في الدنيا من الذل والفضيحة والعقوبة، والعذاب العظيم جزاء الآخرة على عظم جنايتهم؛ فجمع الوعيد بين العاقبة العاجلة والآجلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص75–84.","url":""}]},{"id":"s5-211","number":211,"surah":5,"verses":[34],"verseLabel":"المائدة: 34","question":"ما دلالة تقييد توبة المحاربين بقوله تعالى: ﴿من قبل أن تقدروا عليهم﴾؟","answer":"التوبة قبل القدرة عليهم توبة اختيارية تدل على رجوعهم، فتسقط ما كان من العقوبات متعلقًا بحق الله، أما حقوق الناس من دم أو مال فلا تسقط إلا بأدائها أو عفو أصحابها. وخص هذا الوقت لأن التوبة بعد القدرة قد تكون اتقاءً للعقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص75–84.","url":""}]},{"id":"s5-212","number":212,"surah":5,"verses":[34],"verseLabel":"المائدة: 34","question":"ما مناسبة ختم استثناء التائبين بقوله تعالى: ﴿أن الله غفور رحيم﴾؟","answer":"الخاتمة تعلل قبول توبتهم وسقوط ما تعلق بحق الله من العقوبة؛ فالمغفرة تستر الذنب، والرحمة تفتح لهم باب الرجوع بعد عظم الجناية.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص75–84.","url":""}]},{"id":"s5-213","number":213,"surah":5,"verses":[35],"verseLabel":"المائدة: 35","question":"ما مناسبة الجمع بين التقوى وابتغاء الوسيلة والجهاد في سبيل الله؟","answer":"انتظمت الأوامر في طريق الفلاح: التقوى باجتناب ما يسخط الله، وابتغاء الوسيلة بطلب القرب منه بالطاعات، والجهاد ببذل الوسع في نصرة الحق؛ فجمعت الآية الكف عن الشر، وفعل الخير، وبذل الجهد فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص85–88.","url":""}]},{"id":"s5-214","number":214,"surah":5,"verses":[35],"verseLabel":"المائدة: 35","question":"ما دلالة قوله تعالى: ﴿وابتغوا إليه الوسيلة﴾؟","answer":"الوسيلة ما يُتقرّب به إلى الله من الإيمان والطاعة والعمل الصالح، و﴿ابتغوا﴾ تفيد قصدها وطلبها؛ فالمعنى اطلبوا كل سبب مشروع يبلغ بكم رضاه وقربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص85–88.","url":""}]},{"id":"s5-215","number":215,"surah":5,"verses":[35],"verseLabel":"المائدة: 35","question":"ما مناسبة قوله تعالى: ﴿وجاهدوا في سبيله﴾ بعد الأمر بابتغاء الوسيلة؟","answer":"لأن القرب من الله لا ينال بمجرد التمني، بل ببذل الوسع في طاعته ونصرة سبيله؛ فجاء الجهاد من أعظم صور الوسيلة العملية بعد الأمر العام بابتغائها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص85–88.","url":""}]},{"id":"s5-216","number":216,"surah":5,"verses":[35],"verseLabel":"المائدة: 35","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿لعلكم تفلحون﴾؟","answer":"جعل الفلاح غاية التقوى والوسيلة والجهاد، وهو الفوز بالمطلوب والنجاة من المرهوب. و﴿لعل﴾ تحث على العمل مع الرجاء، فلا يغتر المرء بمجرد الدعوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص85–88.","url":""}]},{"id":"s5-217","number":217,"surah":5,"verses":[36],"verseLabel":"المائدة: 36","question":"ما دلالة افتراض امتلاك الكافرين ما في الأرض جميعًا ومثله معه ليفتدوا به؟","answer":"تصوّر الآية أعظم فدية مادية يمكن أن تخطر بالبال، بل تضاعفها، ثم تنفي قبولها؛ لتقرر أن النجاة يوم القيامة لا تُشترى بمال بعد انقضاء زمن الإيمان والعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص89–93.","url":""}]},{"id":"s5-218","number":218,"surah":5,"verses":[36],"verseLabel":"المائدة: 36","question":"ما سرّ قوله تعالى: ﴿ليفتدوا به من عذاب يوم القيامة﴾ دون ذكر أنفسهم؟","answer":"الافتداء يتضمن بذل العوض لتخليص النفس، فاستغنى الفعل عن ذكرها، وتعلق الكلام بالعذاب لأنه المقصود تصوير هوله واستحالة النجاة منه بتلك الفدية.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص89–93.","url":""}]},{"id":"s5-219","number":219,"surah":5,"verses":[36],"verseLabel":"المائدة: 36","question":"ما دلالة بناء قوله تعالى: ﴿ما تُقبل منهم﴾ للمجهول؟","answer":"بُني الفعل للمجهول لتوجيه النظر إلى النتيجة الحاسمة: عدم قبول الفدية منهم مهما عظمت، أما القابل فمعلوم من السياق وهو الله تعالى.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص89–93.","url":""}]},{"id":"s5-220","number":220,"surah":5,"verses":[37],"verseLabel":"المائدة: 37","question":"ما دلالة الجمع بين قوله تعالى: ﴿يريدون أن يخرجوا من النار﴾ وقوله: ﴿وما هم بخارجين منها﴾؟","answer":"الأول يصوّر رغبتهم المتجددة ومحاولتهم اليائسة، والثاني ينفي خروجهم نفيًا مؤكدًا بالجملة الاسمية والباء؛ فتقابل دوام الإرادة حتمية البقاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص94–103.","url":""}]},{"id":"s5-221","number":221,"surah":5,"verses":[37],"verseLabel":"المائدة: 37","question":"ما دلالة المضارع في قوله تعالى: ﴿يريدون أن يخرجوا من النار﴾؟","answer":"المضارع يستحضر إرادتهم المتجددة للخروج كلما اشتد بهم العذاب، مع أن هذه الإرادة المتكررة لا تبلغ غايتها كما يقرر ما بعدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص94–103.","url":""}]},{"id":"s5-222","number":222,"surah":5,"verses":[37],"verseLabel":"المائدة: 37","question":"ما سرّ وصف العذاب بأنه ﴿مقيم﴾؟","answer":"المقيم هو الثابت الدائم الذي لا يفارق صاحبه؛ وفي اللفظ تصوير للعذاب كأنه مقيم بهم ومقيم لهم في النار، وهو أنسب بما سبقه من نفي خروجهم منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص94–103.","url":""}]},{"id":"s5-223","number":223,"surah":5,"verses":[2],"verseLabel":"المائدة: 38؛ النور: 2","question":"ما سرّ تقديم السارق على السارقة، وتقديم الزانية على الزاني في سورة النور؟","answer":"قُدّم السارق في السرقة لأن وقوعها من الرجال أغلب لما تحتاج إليه عادةً من اقتحام وقوة، وقدمت الزانية في الزنا لأن المرأة هي موضع الطمع، وبموافقتها يقع الفعل غالبًا؛ فناسب التقديم جهة البروز في كل جريمة، من غير أن يختص الحكم بأحد الجنسين.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص104–124.","url":""}]},{"id":"s5-224","number":224,"surah":5,"verses":[38],"verseLabel":"المائدة: 38","question":"ما سرّ جمع ﴿الأيدي﴾ في قوله تعالى: ﴿فاقطعوا أيديهما﴾ مع أن المراد يد من كل واحد؟","answer":"جيء بالجمع مع تثنية الضمير كراهة توالي تثنيتين في تركيب واحد، ولأن المضاف إذا أضيف إلى مثنى أو جمع جاز جمعه؛ والمعنى معلوم: اليد المستحقة للقطع من كل واحد منهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص104–124.","url":""}]},{"id":"s5-225","number":225,"surah":5,"verses":[38],"verseLabel":"المائدة: 38","question":"ما دلالة قوله تعالى: ﴿جزاء بما كسبا نكالًا من الله﴾، وما الفرق بين الجزاء والنكال؟","answer":"﴿جزاء﴾ يبين أن العقوبة مقابلة لما كسباه، و﴿نكالًا﴾ يبين أثرها الرادع الذي يمنع الجاني وغيره من العودة؛ فالأول نظر إلى الاستحقاق، والثاني إلى الزجر والاعتبار.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص104–124.","url":""}]},{"id":"s5-226","number":226,"surah":5,"verses":[38],"verseLabel":"المائدة: 38","question":"ما مناسبة ختم حد السرقة بقوله تعالى: ﴿والله عزيز حكيم﴾؟","answer":"﴿عزيز﴾ غالب لا يمتنع عليه إنفاذ حكمه، و﴿حكيم﴾ يضع العقوبة في موضعها ويقدرها بما يحفظ الحقوق؛ فجمعت الخاتمة قوة التشريع وحكمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص104–124.","url":""}]},{"id":"s5-227","number":227,"surah":5,"verses":[39],"verseLabel":"المائدة: 39","question":"ما دلالة الجمع بين التوبة والإصلاح في قوله تعالى: ﴿فمن تاب من بعد ظلمه وأصلح﴾؟","answer":"التوبة رجوع باطن عن الذنب، والإصلاح شاهد عملي عليها بإزالة آثاره ورد الحقوق وتغيير السلوك؛ لذلك لم يكتف السياق بدعوى الندم وحدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص104–124.","url":""}]},{"id":"s5-228","number":228,"surah":5,"verses":[39],"verseLabel":"المائدة: 39","question":"ما دلالة تسمية السرقة ﴿ظلمًا﴾ في قوله تعالى: ﴿من بعد ظلمه﴾؟","answer":"لأن السارق يضع يده على مال غيره بغير حق، فيظلم صاحبه، ويظلم نفسه بتعريضها للإثم والعقوبة؛ فاللفظ يكشف حقيقة الجناية ولا يقتصر على اسمها الفقهي.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص104–124.","url":""}]},{"id":"s5-229","number":229,"surah":5,"verses":[39],"verseLabel":"المائدة: 39","question":"ما دلالة قوله تعالى بعد توبة العبد: ﴿فإن الله يتوب عليه﴾؟","answer":"توبة العبد رجوعه عن المعصية، وتوبة الله عليه قبول ذلك الرجوع ومغفرة ذنبه والتفضل عليه بالرحمة؛ فاختلف متعلق الفعل في الموضعين.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص104–124.","url":""}]},{"id":"s5-230","number":230,"surah":5,"verses":[38,39],"verseLabel":"المائدة: 38–39","question":"ما سرّ ختم آية الحد بقوله تعالى: ﴿عزيز حكيم﴾، وختم آية التوبة بقوله: ﴿غفور رحيم﴾؟","answer":"ناسب العزة والحكمة مقام إنفاذ الحد وردع الجريمة، وناسبت المغفرة والرحمة مقام التوبة والإصلاح؛ فلكل خاتمة معناها الموافق لما قبلها، واجتمع في السياق العدل وفتح باب الرحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص104–124.","url":""}]},{"id":"s5-231","number":231,"surah":5,"verses":[40],"verseLabel":"المائدة: 40","question":"ما مناسبة قوله تعالى: ﴿ألم تعلم أن الله له ملك السماوات والأرض﴾ بعد بيان حد السرقة وقبول التوبة؟","answer":"الاستفهام للتقرير بأن الله هو المالك المطلق، ومن ثم فله وحده حق التشريع والحكم بالعقوبة أو المغفرة؛ فجاءت الآية أصلًا جامعًا لما سبق من الحد والتوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص125–133.","url":""}]},{"id":"s5-232","number":232,"surah":5,"verses":[40],"verseLabel":"المائدة: 40","question":"ما دلالة تقديم ﴿له﴾ في قوله تعالى: ﴿له ملك السماوات والأرض﴾؟","answer":"تقديم الجار والمجرور يفيد اختصاص الملك الحقيقي الكامل بالله تعالى؛ فلا يخرج شيء عن سلطانه وحكمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص125–133.","url":""}]},{"id":"s5-233","number":233,"surah":5,"verses":[40],"verseLabel":"المائدة: 40","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿والله على كل شيء قدير﴾؟","answer":"بعد تقرير ملك الله وتعذيبه من يشاء ومغفرته لمن يشاء، جاءت القدرة دليلًا على نفاذ ذلك كله؛ فلا يعجزه إقامة حكم ولا إنفاذ جزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص125–133.","url":""}]},{"id":"s5-234","number":234,"surah":5,"verses":[40],"verseLabel":"المائدة: 40","question":"ما سرّ تقديم العذاب على المغفرة في قوله تعالى: ﴿يعذب من يشاء ويغفر لمن يشاء﴾ مع أن المغفرة تُقدّم في مواضع أخرى؟","answer":"تقدم العذاب هنا لمناسبة السياق السابق في حد السرقة والوعيد، ثم أتبع بالمغفرة لمناسبة ذكر التوبة؛ فرتب اللفظ على ترتيب المقامين. أما المواضع التي يغلب عليها الترغيب وسعة الرحمة فتتقدم فيها المغفرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص125–133؛ والموضع العكسي: ج42، ص222 وما بعدها.","url":""}]},{"id":"s5-235","number":235,"surah":5,"verses":[41],"verseLabel":"المائدة: 41","question":"ما دلالة نداء النبي ﷺ بوصف الرسالة في قوله تعالى: ﴿يا أيها الرسول﴾؟","answer":"النداء بوصف ﴿الرسول﴾ تشريف له وتثبيت بأن ما يواجهه داخل في مهمة البلاغ، وفيه تذكير بأن عليه أداء الرسالة وألا يحزنه مسارعة المعاندين في الكفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص134–164.","url":""}]},{"id":"s5-236","number":236,"surah":5,"verses":[41],"verseLabel":"المائدة: 41","question":"ما دلالة قوله تعالى: ﴿يسارعون في الكفر﴾ دون: إلى الكفر؟","answer":"حرف ﴿في﴾ يصورهم منغمسين في دائرة الكفر يتنقلون مسرعين في أعماله، لا أنهم خارجون عنه ثم يقصدونه كما قد يوحي حرف ﴿إلى﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص134–164.","url":""}]},{"id":"s5-237","number":237,"surah":5,"verses":[41],"verseLabel":"المائدة: 41","question":"ما دلالة قوله تعالى: ﴿قالوا آمنا بأفواههم ولم تؤمن قلوبهم﴾؟","answer":"خص الأفواه لأنها أداة الدعوى الظاهرة التي لم تتجاوزها كلمة الإيمان، ونفى الإيمان عن القلوب لأنها موضع التصديق؛ فصور انفصال القول عن الاعتقاد تصويرًا حسيًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص134–164.","url":""}]},{"id":"s5-238","number":238,"surah":5,"verses":[41],"verseLabel":"المائدة: 41","question":"ما الفرق بين قوله تعالى: ﴿سماعون للكذب﴾ وقوله: ﴿سماعون لقوم آخرين لم يأتوك﴾؟","answer":"الأولى تصف شدة إصغائهم إلى الكذب وقبولهم له، والثانية تبين أنهم يسمعون لحساب قوم آخرين غائبين وينقلون إليهم؛ فليس التكرار محض إعادة، بل كشفٌ لنوع المسموع ولمن يعملون.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص134–164.","url":""}]},{"id":"s5-239","number":239,"surah":5,"verses":[41],"verseLabel":"المائدة: 41","question":"ما دلالة قوله تعالى: ﴿لم يأتوك﴾ في وصف القوم الآخرين؟","answer":"الإتيان يتضمن القصد والوصول إلى النبي ﷺ للتحاكم أو السماع، فنفيه يدل على تعمدهم الغياب وإرسال غيرهم ليستطلع الحكم، وهو أخص من مجرد نفي الحضور.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص134–164.","url":""}]},{"id":"s5-240","number":240,"surah":5,"verses":[13,41],"verseLabel":"المائدة: 13، 41","question":"ما الفرق بين قوله تعالى: ﴿يحرفون الكلم عن مواضعه﴾ في الآية 13، وقوله: ﴿يحرفون الكلم من بعد مواضعه﴾ في الآية 41؟","answer":"﴿عن مواضعه﴾ تصور إمالة الكلام وإبعاده عن الموضع الذي وضعه الله فيه، أما ﴿من بعد مواضعه﴾ فتدل على تحريفه بعد أن استقر في مواضعه وعُرف حكمه؛ فالثانية أصرح في التعمد بعد العلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص134–164؛ ج8، ص693–694.","url":""}]},{"id":"s5-241","number":241,"surah":5,"verses":[41],"verseLabel":"المائدة: 41","question":"ما دلالة حكاية قولهم: ﴿إن أوتيتم هذا فخذوه وإن لم تؤتوه فاحذروا﴾؟","answer":"تكشف الحكاية أنهم لم يطلبوا حكم الله طلب إذعان، بل اشترطوا قبول الحكم إن وافق ما اختاروه سلفًا والحذر منه إن خالفه؛ فهي تفضح انتقائية التحاكم وتحريفهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص134–164.","url":""}]},{"id":"s5-242","number":242,"surah":5,"verses":[41],"verseLabel":"المائدة: 41","question":"ما دلالة قوله تعالى: ﴿ومن يرد الله فتنته فلن تملك له من الله شيئًا﴾؟","answer":"المعنى أن من اختار الضلال واستحق أن يترك لفتنته فلا يملك أحد أن يدفع عنه من قضاء الله شيئًا؛ وفي ﴿من الله﴾ تأكيد أن الحماية لا تكون في مواجهة حكمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص134–164.","url":""}]},{"id":"s5-243","number":243,"surah":5,"verses":[41],"verseLabel":"المائدة: 41","question":"ما سرّ تعلق التطهير بالقلوب في قوله تعالى: ﴿لم يرد الله أن يطهر قلوبهم﴾؟","answer":"لأن القلب موضع الإيمان والنية، وفسادهم بدأ بإضمار التكذيب مع إظهار الإيمان؛ فناسب أن ينفى عن قلوبهم التطهير الذي أعرضوا عن أسبابه، لا مجرد طهارة الظاهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص134–164.","url":""}]},{"id":"s5-244","number":244,"surah":5,"verses":[41],"verseLabel":"المائدة: 41","question":"ما دلالة الجمع بين ﴿خزي في الدنيا﴾ و﴿عذاب عظيم في الآخرة﴾ في هذا السياق كما جُمع بينهما في آية الحرابة؟","answer":"يتفق الموضعان في الجمع بين أثر الجريمة العاجل وجزائها الآجل: لهؤلاء فضيحة وذلة في الدنيا وعذاب في الآخرة. غير أن السياق هنا في فساد الاعتقاد والتحاكم، وهناك في الحرابة والإفساد المسلح؛ فتتحد بنية الوعيد ويختلف سببها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص134–164.","url":""}]},{"id":"s5-245","number":245,"surah":5,"verses":[42],"verseLabel":"المائدة: 42","question":"ما دلالة الجمع بين وصفهم بـ﴿سماعون للكذب﴾ و﴿أكالون للسحت﴾؟","answer":"جمع الوصفان فساد التلقي وفساد الكسب: فهم يكثرون قبول الكذب بآذانهم، وأكل المال الحرام كالرشوة ببطونهم؛ فكشف التعبير أن التحريف تغذيه شهوة القول الباطل وشهوة المال.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص165–184.","url":""}]},{"id":"s5-246","number":246,"surah":5,"verses":[42],"verseLabel":"المائدة: 42","question":"ما دلالة تسمية المال الحرام ﴿السحت﴾؟","answer":"السحت في أصل دلالته الاستئصال والإهلاك؛ فسمي المال الحرام به لأنه يمحق البركة ويستأصل المروءة والدين، ومنه الرشوة التي يأكلونها على تبديل الحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص165–184.","url":""}]},{"id":"s5-247","number":247,"surah":5,"verses":[42],"verseLabel":"المائدة: 42","question":"ما دلالة تخيير النبي ﷺ في قوله تعالى: ﴿فاحكم بينهم أو أعرض عنهم﴾؟","answer":"لأنهم لم يجيئوا طالبين للحق، خُيّر النبي ﷺ بين أن يقبل التحاكم إليه وأن يعرض عنهم؛ فإن اختار الحكم وجب أن يكون بالقسط، فلا يجره فساد قصدهم إلى ترك العدل.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص165–184.","url":""}]},{"id":"s5-248","number":248,"surah":5,"verses":[42],"verseLabel":"المائدة: 42","question":"ما مناسبة قوله تعالى: ﴿وإن تعرض عنهم فلن يضروك شيئًا﴾؟","answer":"طمأنه الله أن إعراضه عن تحكيمهم لن يمكّنهم من إيذائه أو إفساد دعوته، فلا يحمله خوف مكرهم على قبول خصومة لم يقصدوا بها الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص165–184.","url":""}]},{"id":"s5-249","number":249,"surah":5,"verses":[42],"verseLabel":"المائدة: 42","question":"ما دلالة قوله تعالى: ﴿فاحكم بينهم بالقسط﴾ ثم ختمه بقوله: ﴿إن الله يحب المقسطين﴾؟","answer":"القسط هو العدل، و﴿المقسطين﴾ هم الذين يجعلونه صفة ثابتة في أحكامهم؛ فانتقل من الأمر بالفعل إلى الثناء على أهله ومحبة الله لهم، ترغيبًا في ملازمة العدل حتى مع سيئي القصد.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص165–184.","url":""}]},{"id":"s5-250","number":250,"surah":5,"verses":[43],"verseLabel":"المائدة: 43","question":"ما دلالة الاستفهام في قوله تعالى: ﴿وكيف يحكمونك وعندهم التوراة فيها حكم الله﴾؟","answer":"الاستفهام للتعجيب والإنكار؛ إذ يتركون حكم التوراة الموجود عندهم ثم يطلبون حكم النبي ﷺ، لا طلبًا للحق بل رجاء حكم يوافق أهواءهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص185–192.","url":""}]},{"id":"s5-251","number":251,"surah":5,"verses":[43],"verseLabel":"المائدة: 43","question":"ما دلالة قوله تعالى: ﴿وعندهم التوراة فيها حكم الله﴾؟","answer":"لفظ ﴿عندهم﴾ يصور التوراة حاضرة في أيديهم، و﴿فيها حكم الله﴾ يقرر أن الحكم المطلوب مثبت فيها؛ فتقوم الحجة عليهم من الكتاب الذي ينتسبون إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص185–192.","url":""}]},{"id":"s5-252","number":252,"surah":5,"verses":[43],"verseLabel":"المائدة: 43","question":"ما دلالة قوله تعالى: ﴿ثم يتولون من بعد ذلك﴾؟","answer":"﴿ثم﴾ تفيد تراخي الرتبة وتزيد فعلهم استبعادًا: فهم بعد أن أعرضوا عن حكم التوراة وجاؤوا إلى النبي ﷺ، يعودون فيعرضون عن حكمه أيضًا حين لا يوافق هواهم؛ و﴿من بعد ذلك﴾ تؤكد وقوع التولي بعد قيام الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص185–192.","url":""}]},{"id":"s5-253","number":253,"surah":5,"verses":[43],"verseLabel":"المائدة: 43","question":"ما مناسبة ختم الآية بقوله تعالى: ﴿وما أولئك بالمؤمنين﴾؟","answer":"لأن من شأن المؤمن أن يذعن لحكم الله، أما طلبهم الحكم انتقائيًا ثم توليهم عنه فيكشف فقدان حقيقة الإيمان. وزادت الباء في ﴿بالمؤمنين﴾ النفي توكيدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص185–192.","url":""}]},{"id":"s5-254","number":254,"surah":5,"verses":[44],"verseLabel":"المائدة: 44","question":"ما دلالة الجمع بين ﴿هدى﴾ و﴿نور﴾ في وصف التوراة؟","answer":"الهدى يدل على الإرشاد إلى الطريق الحق في الاعتقاد والعمل، والنور يكشف الحقائق والأحكام ويميزها من الباطل؛ فجمعت التوراة الدلالة والكشف.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص193–222.","url":""}]},{"id":"s5-255","number":255,"surah":5,"verses":[44],"verseLabel":"المائدة: 44","question":"ما دلالة قوله تعالى: ﴿يحكم بها النبيون الذين أسلموا للذين هادوا﴾؟","answer":"وصف الأنبياء بالإسلام، مع أنه معلوم، يقرر أن أصل دينهم جميعًا الاستسلام لله، وأن حكمهم بالتوراة صادر عن هذا الاستسلام لا عن عصبية قومية. و﴿للذين هادوا﴾ تبين أن التوراة شريعة حُكم بها في بني إسرائيل، لا ملكًا يبدلونه بأهوائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص193–222.","url":""}]},{"id":"s5-256","number":256,"surah":5,"verses":[44],"verseLabel":"المائدة: 44","question":"ما مناسبة عطف ﴿الربانيون والأحبار﴾ بعد النبيين؟","answer":"لبيان تسلسل القائمين على حفظ الشريعة والحكم بها: النبيون يبلغون ويحكمون، ثم يحمل الربانيون والأحبار علم الكتاب وتعليمه وصيانته بعدهم؛ فالعطف يقرر مسؤولية العلماء عن استمرار الحكم بالوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص193–222.","url":""}]},{"id":"s5-257","number":257,"surah":5,"verses":[44],"verseLabel":"المائدة: 44","question":"ما دلالة البناء للمجهول في قوله تعالى: ﴿بما استُحفظوا من كتاب الله﴾؟","answer":"المعنى أنهم كُلّفوا حفظ كتاب الله واستُودعوه، فالبناء للمجهول يبرز عهد الحفظ الواقع عليهم ومسؤوليتهم عنه، مع العلم أن المستحفِظ هو الله تعالى.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص193–222.","url":""}]},{"id":"s5-258","number":258,"surah":5,"verses":[44],"verseLabel":"المائدة: 44","question":"ما دلالة حذف ياء المتكلم في قوله تعالى: ﴿واخشون﴾؟","answer":"حُذفت الياء تخفيفًا ومراعاةً للفواصل، وبقيت الكسرة دالة عليها؛ فاللفظ في تمام معناه: واخشوني. وإيجاز الصورة يلائم قوة الأمر وقصره.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص214.","url":""}]},{"id":"s5-259","number":259,"surah":5,"verses":[44],"verseLabel":"المائدة: 44","question":"ما مناسبة الجمع بين النهي عن خشية الناس والنهي عن اشتراء الآيات بثمن قليل؟","answer":"لأن تحريف الحكم قد تدفع إليه رهبة أصحاب النفوذ أو الرغبة في منفعة دنيوية كالرشوة والجاه؛ فواجهت الآية سببي الانحراف: الخوف والطمع.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص193–222.","url":""}]},{"id":"s5-260","number":260,"surah":5,"verses":[44],"verseLabel":"المائدة: 44","question":"ما دلالة ختم الآية بقوله تعالى: ﴿فأولئك هم الكافرون﴾؟","answer":"جاء الوصف عقب النهي عن كتمان حكم الله وبيعه؛ فمن رد ما أنزل الله أو جحد صلاحيته واستبدل به غيره فقد ستر الحق وكفر به. والحكم على الأعيان وتفصيل أحوال الترك له باب آخر لا تتناوله العبارة البلاغية وحدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص193–222.","url":""}]},{"id":"s5-261","number":261,"surah":5,"verses":[2],"verseLabel":"المائدة: 44؛ الإسراء: 2","question":"ما سرّ وصف التوراة في الإسراء بأنها ﴿هدى﴾، وفي المائدة بأنها ﴿هدى ونور﴾؟","answer":"سياق الإسراء يذكر إيتاء موسى الكتاب لبني إسرائيل فاتجه إلى كونه هاديًا لهم، أما سياق المائدة ففي الاحتكام إلى التوراة وكشف ما فيها من حكم الله، فزيد ﴿نور﴾ لمناسبة إظهار الأحكام وكشف التحريف؛ والزيادة موافقة لمقتضى السياق.","sources":[{"label":"موسوعة التفسير البلاغي، الموضع العكسي: ج27، ص769–770.","url":""}]},{"id":"s5-262","number":262,"surah":5,"verses":[45],"verseLabel":"المائدة: 45","question":"ما دلالة تفصيل القصاص في قوله تعالى: ﴿النفس بالنفس والعين بالعين والأنف بالأنف...﴾؟","answer":"التفصيل يقرر المماثلة الدقيقة في القصاص، فلا تتجاوز العقوبة موضع الجناية، ويمنع عادة الجاهلية في مقابلة الواحد بأكثر منه أو الشريف بالضعيف.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص223–236.","url":""}]},{"id":"s5-263","number":263,"surah":5,"verses":[45],"verseLabel":"المائدة: 45","question":"ما سرّ ترتيب القصاص من النفس إلى الأعضاء ثم الجروح؟","answer":"بدأ بالنفس لأنها أعظم ما يعتدى عليه، ثم ذكر أعضاء ظاهرة عظيمة المنافع، ثم عمّم في سائر الجروح؛ فانتقل من الجناية الكبرى إلى أجزائها المعيّنة ثم إلى الحكم الجامع لما بقي.","sources":[{"label":"موسوعة التفسير البلاغي، ج9، ص223–236.","url":""}]}]);
